INSERT INTO public.content_items (
  id, subject_id, content_type, title, description, body, academic_year, file_url, file_key, sort_order, is_published, exam_type, file_name, file_size_bytes, submission_id, flashcard_unit_id, flashcard_topic_id, question_document, answer_document, created_at, updated_at
) VALUES
  ('2b11f90a-09ac-4883-a0df-771ba2e1f386', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Define risk in business and explain Knight''s Theory of Profit.', 'Priority: Tier 1 | PYQ Connection: 2025 Q1.2 — "Define risk in business and explain Knight''s Theory of Profit" (15 marks, direct match) and 2024 Q1P (comparison with Innovation Theory).', 'Knight distinguished between two types of unpredictability:

Risk – a situation where the probability of an outcome can be statistically measured or insured against (e.g., fire, theft).
Uncertainty – a situation where the probability of outcomes cannot be measured or insured because the future is genuinely unknown (e.g., changes in consumer taste, market demand).

Knight''s central argument is that profit is the entrepreneur''s reward for bearing this non-insurable uncertainty, not merely for bearing measurable/insurable risk. Because true uncertainty cannot be transferred to an insurance company, the entrepreneur who makes decisions under such uncertainty — and is right more often than wrong — earns profit as compensation for this uncertainty-bearing function. Entrepreneurial profit therefore differs fundamentally from wages, rent or interest, which are contractual and known in advance.', NULL, NULL, NULL, 15, true, 'University Exam', NULL, NULL, NULL, '032080f2-249a-4b0b-9e23-ad18a3e05122', 'e58b582e-24f9-451f-a326-d32b30d64420', '{"blocks":[{"id":"bpem-u1-c15-q-1","text":"Define risk in business and explain Knight''s Theory of Profit.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u1-c15-a-1","text":"Knight distinguished between two types of unpredictability:","type":"text","style":"paragraph"},{"id":"bpem-u1-c15-a-2","type":"bulletList","items":["Risk – a situation where the probability of an outcome can be statistically measured or insured against (e.g., fire, theft).","Uncertainty – a situation where the probability of outcomes cannot be measured or insured because the future is genuinely unknown (e.g., changes in consumer taste, market demand)."]},{"id":"bpem-u1-c15-a-3","text":"Knight''s central argument is that profit is the entrepreneur''s reward for bearing this non-insurable uncertainty, not merely for bearing measurable/insurable risk. Because true uncertainty cannot be transferred to an insurance company, the entrepreneur who makes decisions under such uncertainty — and is right more often than wrong — earns profit as compensation for this uncertainty-bearing function. Entrepreneurial profit therefore differs fundamentally from wages, rent or interest, which are contractual and known in advance.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:38.327363+00', '2026-09-21 02:33:38.327363+00'),
  ('fdce35e2-ac6a-4d9d-8e97-2c0001ab109a', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Explain Everett Hagen''s Theory of Social Change.', 'Priority: Tier 2 | PYQ Connection: Not directly tested in the supplied papers; important as the syllabus''s sole "social" theory and a strong candidate for future standalone or comparison questions.', 'Hagen explained entrepreneurship as a consequence of social-psychological change, particularly the phenomenon of "status withdrawal." When a social group (e.g., a particular community or class) loses its accustomed status or respect within society — due to conquest, displacement, disapproval by a dominant group, or non-recognition of status — its members experience a status gap. Some respond with retreat or rebellion, but a section responds by seeking to regain status through innovative, achievement-oriented activity, including entrepreneurship. Over generations, changes in child-rearing practices (particularly a shift toward greater independence and less authoritarian parenting) foster a "creative" or innovational personality suited to entrepreneurial roles. Thus, Hagen locates the origin of entrepreneurship in social change and status dynamics rather than purely in economic incentives.', NULL, NULL, NULL, 16, true, 'University Exam', NULL, NULL, NULL, '032080f2-249a-4b0b-9e23-ad18a3e05122', 'e58b582e-24f9-451f-a326-d32b30d64420', '{"blocks":[{"id":"bpem-u1-c16-q-1","text":"Explain Everett Hagen''s Theory of Social Change.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u1-c16-a-1","text":"Hagen explained entrepreneurship as a consequence of social-psychological change, particularly the phenomenon of \"status withdrawal.\" When a social group (e.g., a particular community or class) loses its accustomed status or respect within society — due to conquest, displacement, disapproval by a dominant group, or non-recognition of status — its members experience a status gap. Some respond with retreat or rebellion, but a section responds by seeking to regain status through innovative, achievement-oriented activity, including entrepreneurship. Over generations, changes in child-rearing practices (particularly a shift toward greater independence and less authoritarian parenting) foster a \"creative\" or innovational personality suited to entrepreneurial roles. Thus, Hagen locates the origin of entrepreneurship in social change and status dynamics rather than purely in economic incentives.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:38.327363+00', '2026-09-21 02:33:38.327363+00'),
  ('cdd99d90-3177-41e5-9bb0-dd0517b3cc8a', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Make a comparative study between Innovation Theory (Schumpeter) and Theory of Profit (Knight).', 'Priority: Tier 1 | PYQ Connection: 2024 Q1P — directly asked (10 marks). Highest-priority comparison flashcard in this unit.', 'Basis | Innovation Theory (Schumpeter) | Theory of Profit (Knight)
Core idea | Entrepreneur is primarily an innovator who creates "new combinations" | Entrepreneur is primarily an uncertainty-bearer; profit rewards bearing non-insurable uncertainty
Driving force | Innovation and creative destruction | Uncertainty (as distinct from measurable risk)
Source of reward | Reward for innovation and disturbing market equilibrium | Reward for bearing uncertainty that cannot be insured
View of risk | Risk is incidental to innovation | Risk/uncertainty is the central defining feature
Economic role | Entrepreneur drives economic development through change | Entrepreneur stabilises production decisions under an unpredictable future
Nature of profit | Profit = reward for innovation | Profit = residual reward after bearing uncertainty

Both theories agree entrepreneurial profit is distinct from wages/rent/interest and both see the entrepreneur as central to economic activity, but they differ on why that profit arises — creative innovation (Schumpeter) versus uncertainty-bearing (Knight).', NULL, NULL, NULL, 17, true, 'University Exam', NULL, NULL, NULL, '032080f2-249a-4b0b-9e23-ad18a3e05122', 'e58b582e-24f9-451f-a326-d32b30d64420', '{"blocks":[{"id":"bpem-u1-c17-q-1","text":"Make a comparative study between Innovation Theory (Schumpeter) and Theory of Profit (Knight).","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u1-c17-a-1","rows":[["Basis","Innovation Theory (Schumpeter)","Theory of Profit (Knight)"],["Core idea","Entrepreneur is primarily an innovator who creates \"new combinations\"","Entrepreneur is primarily an uncertainty-bearer; profit rewards bearing non-insurable uncertainty"],["Driving force","Innovation and creative destruction","Uncertainty (as distinct from measurable risk)"],["Source of reward","Reward for innovation and disturbing market equilibrium","Reward for bearing uncertainty that cannot be insured"],["View of risk","Risk is incidental to innovation","Risk/uncertainty is the central defining feature"],["Economic role","Entrepreneur drives economic development through change","Entrepreneur stabilises production decisions under an unpredictable future"],["Nature of profit","Profit = reward for innovation","Profit = residual reward after bearing uncertainty"]],"type":"table"},{"id":"bpem-u1-c17-a-2","text":"Both theories agree entrepreneurial profit is distinct from wages/rent/interest and both see the entrepreneur as central to economic activity, but they differ on why that profit arises — creative innovation (Schumpeter) versus uncertainty-bearing (Knight).","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:38.327363+00', '2026-09-21 02:33:38.327363+00'),
  ('0584e573-95ad-42a9-b990-bfcbc9652af2', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Explain the personal factors influencing entrepreneurship development.', 'Priority: Tier 2 | PYQ Connection: Part of the syllabus''s "external factors" set; covered under the general 2024 "influence of external factors" question.', 'Personal factors include: individual personality traits (risk appetite, need for achievement, self-confidence), family background and upbringing, level of education and skill/training, prior work experience, age, personal financial position, and individual goals/aspirations. These personal traits determine whether a person, even in a favourable external environment, actually chooses to become an entrepreneur.', NULL, NULL, NULL, 22, true, 'University Exam', NULL, NULL, NULL, '032080f2-249a-4b0b-9e23-ad18a3e05122', '87ad7987-c622-4512-83f2-c4f2e3c7cd85', '{"blocks":[{"id":"bpem-u1-c22-q-1","text":"Explain the personal factors influencing entrepreneurship development.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u1-c22-a-1","text":"Personal factors include: individual personality traits (risk appetite, need for achievement, self-confidence), family background and upbringing, level of education and skill/training, prior work experience, age, personal financial position, and individual goals/aspirations. These personal traits determine whether a person, even in a favourable external environment, actually chooses to become an entrepreneur.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:38.327363+00', '2026-09-21 02:33:38.327363+00'),
  ('ddf22d98-6107-49d1-bc2b-aa6106a415dc', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Compare McClelland''s Theory of High Achievement with Hagen''s Theory of Social Change.', 'Priority: Tier 3 | PYQ Connection: Not directly asked; a plausible analytical comparison question given both are psychological/sociological theories.', 'Both are psychological/social (rather than purely economic) explanations of entrepreneurship. McClelland locates the drive at the individual level — the internal need for achievement (n-Ach), which can be built through training. Hagen locates the drive at the group/social level — status withdrawal of a community triggers entrepreneurial behaviour across generations via changed child-rearing patterns. McClelland is therefore more applicable to designing individual-level EDPs/training, while Hagen explains why entrepreneurship clusters within particular communities or social groups over time.', NULL, NULL, NULL, 18, true, 'University Exam', NULL, NULL, NULL, '032080f2-249a-4b0b-9e23-ad18a3e05122', 'e58b582e-24f9-451f-a326-d32b30d64420', '{"blocks":[{"id":"bpem-u1-c18-q-1","text":"Compare McClelland''s Theory of High Achievement with Hagen''s Theory of Social Change.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u1-c18-a-1","text":"Both are psychological/social (rather than purely economic) explanations of entrepreneurship. McClelland locates the drive at the individual level — the internal need for achievement (n-Ach), which can be built through training. Hagen locates the drive at the group/social level — status withdrawal of a community triggers entrepreneurial behaviour across generations via changed child-rearing patterns. McClelland is therefore more applicable to designing individual-level EDPs/training, while Hagen explains why entrepreneurship clusters within particular communities or social groups over time.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:38.327363+00', '2026-09-21 02:33:38.327363+00'),
  ('35555534-b34f-4349-85fa-0d354e143def', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Explain the socio-cultural factors influencing entrepreneurship development.', 'Priority: Tier 1 | PYQ Connection: 2025 Q1.3 and 2024 Q1Q — social factors tested directly in both supplied papers.', 'Socio-cultural factors include: family background and business lineage, caste/community attitudes toward trade and risk-taking, prevailing social values and status attached to entrepreneurship versus salaried employment, level of education and awareness, religious beliefs, availability of role models and mentors, and social/family support networks. A society that values risk-taking, achievement and self-employment produces more entrepreneurs than one that prizes only secure, salaried jobs.', NULL, NULL, NULL, 19, true, 'University Exam', NULL, NULL, NULL, '032080f2-249a-4b0b-9e23-ad18a3e05122', '87ad7987-c622-4512-83f2-c4f2e3c7cd85', '{"blocks":[{"id":"bpem-u1-c19-q-1","text":"Explain the socio-cultural factors influencing entrepreneurship development.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u1-c19-a-1","text":"Socio-cultural factors include: family background and business lineage, caste/community attitudes toward trade and risk-taking, prevailing social values and status attached to entrepreneurship versus salaried employment, level of education and awareness, religious beliefs, availability of role models and mentors, and social/family support networks. A society that values risk-taking, achievement and self-employment produces more entrepreneurs than one that prizes only secure, salaried jobs.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:38.327363+00', '2026-09-21 02:33:38.327363+00'),
  ('0f31604a-6b88-4e4c-b971-037ae635d43e', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Explain the political factors influencing entrepreneurship development.', 'Priority: Tier 1 | PYQ Connection: 2025 Q1.3 and 2024 Q1Q — political factors tested directly in both supplied papers.', 'Political factors include: political stability, government industrial and trade policy, licensing and regulatory requirements, taxation policy, government incentive/subsidy schemes (e.g., Start-up India, MSME schemes), ease-of-doing-business reforms, and the legal/administrative framework for setting up and running a business. Stable, pro-business government policy encourages entrepreneurship, while frequent policy changes, excessive regulation or political instability discourage it.', NULL, NULL, NULL, 20, true, 'University Exam', NULL, NULL, NULL, '032080f2-249a-4b0b-9e23-ad18a3e05122', '87ad7987-c622-4512-83f2-c4f2e3c7cd85', '{"blocks":[{"id":"bpem-u1-c20-q-1","text":"Explain the political factors influencing entrepreneurship development.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u1-c20-a-1","text":"Political factors include: political stability, government industrial and trade policy, licensing and regulatory requirements, taxation policy, government incentive/subsidy schemes (e.g., Start-up India, MSME schemes), ease-of-doing-business reforms, and the legal/administrative framework for setting up and running a business. Stable, pro-business government policy encourages entrepreneurship, while frequent policy changes, excessive regulation or political instability discourage it.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:38.327363+00', '2026-09-21 02:33:38.327363+00'),
  ('de7cc74d-d441-4494-9767-a76927d4a773', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Explain the economic factors influencing entrepreneurship development.', 'Priority: Tier 2 | PYQ Connection: Not directly named in the supplied papers'' factor questions (which emphasised social/political), but part of the syllabus''s "external factors" set and asked as part of the general 2024 "external factors" question.', 'Economic factors include: availability of capital and credit facilities, banking and financial infrastructure, availability of raw materials and labour, existing market demand and purchasing power, physical infrastructure (power, transport, communication), and the overall rate of economic growth/stability. Favourable economic conditions lower the cost and risk of starting and running an enterprise.', NULL, NULL, NULL, 21, true, 'University Exam', NULL, NULL, NULL, '032080f2-249a-4b0b-9e23-ad18a3e05122', '87ad7987-c622-4512-83f2-c4f2e3c7cd85', '{"blocks":[{"id":"bpem-u1-c21-q-1","text":"Explain the economic factors influencing entrepreneurship development.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u1-c21-a-1","text":"Economic factors include: availability of capital and credit facilities, banking and financial infrastructure, availability of raw materials and labour, existing market demand and purchasing power, physical infrastructure (power, transport, communication), and the overall rate of economic growth/stability. Favourable economic conditions lower the cost and risk of starting and running an enterprise.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:38.327363+00', '2026-09-21 02:33:38.327363+00'),
  ('3a3814b7-ae64-4eca-a3b2-73465b3418a8', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Elaborate the influence of external factors on entrepreneurship development (all four factors together).', 'Priority: Tier 1 | PYQ Connection: 2024 Q1Q (9 marks, direct match — asked as a combined question) and echoed by 2025 Q1.3 (social + political specifically).', 'Entrepreneurship development is shaped jointly by socio-cultural factors (values, family, community attitudes), political factors (government policy, stability, incentives), economic factors (capital, infrastructure, market conditions), and personal factors (individual traits, education, experience). None of these operates in isolation — for example, a favourable government policy (political) is of limited use without adequate capital access (economic), and neither matters if social attitudes discourage risk-taking (socio-cultural) or the individual lacks the personal motivation/skills (personal) to act on the opportunity. A comprehensive ecosystem across all four dimensions is necessary for sustained entrepreneurship growth.', NULL, NULL, NULL, 23, true, 'University Exam', NULL, NULL, NULL, '032080f2-249a-4b0b-9e23-ad18a3e05122', '87ad7987-c622-4512-83f2-c4f2e3c7cd85', '{"blocks":[{"id":"bpem-u1-c23-q-1","text":"Elaborate the influence of external factors on entrepreneurship development (all four factors together).","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u1-c23-a-1","text":"Entrepreneurship development is shaped jointly by socio-cultural factors (values, family, community attitudes), political factors (government policy, stability, incentives), economic factors (capital, infrastructure, market conditions), and personal factors (individual traits, education, experience). None of these operates in isolation — for example, a favourable government policy (political) is of limited use without adequate capital access (economic), and neither matters if social attitudes discourage risk-taking (socio-cultural) or the individual lacks the personal motivation/skills (personal) to act on the opportunity. A comprehensive ecosystem across all four dimensions is necessary for sustained entrepreneurship growth.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:38.327363+00', '2026-09-21 02:33:38.327363+00'),
  ('34fe2803-107e-4014-afaf-7a615f356047', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Analytical — "Which external factor is most critical to entrepreneurship development?"', 'Priority: Tier 3 | PYQ Connection: Anticipated analytical extension of the recurring external-factors theme; not directly asked but consistent with examiner''s demonstrated interest in this topic.', 'There is no single universally "most critical" factor — the answer should be argued rather than asserted. A strong answer would note: economic factors (capital, market, infrastructure) are often argued as the most immediate/practical constraint on actually starting a venture; socio-cultural factors are argued as the deepest/longest-term influence because they shape whether risk-taking is even socially acceptable; political factors act as an enabling or constraining "umbrella" over both; and personal factors ultimately determine whether a given individual, within any environment, converts opportunity into action. The best answers argue a reasoned position (e.g., "economic factors are most critical because...") while acknowledging that all four interact.', NULL, NULL, NULL, 24, true, 'University Exam', NULL, NULL, NULL, '032080f2-249a-4b0b-9e23-ad18a3e05122', '87ad7987-c622-4512-83f2-c4f2e3c7cd85', '{"blocks":[{"id":"bpem-u1-c24-q-1","text":"Analytical — \"Which external factor is most critical to entrepreneurship development?\"","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u1-c24-a-1","text":"There is no single universally \"most critical\" factor — the answer should be argued rather than asserted. A strong answer would note: economic factors (capital, market, infrastructure) are often argued as the most immediate/practical constraint on actually starting a venture; socio-cultural factors are argued as the deepest/longest-term influence because they shape whether risk-taking is even socially acceptable; political factors act as an enabling or constraining \"umbrella\" over both; and personal factors ultimately determine whether a given individual, within any environment, converts opportunity into action. The best answers argue a reasoned position (e.g., \"economic factors are most critical because...\") while acknowledging that all four interact.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:38.327363+00', '2026-09-21 02:33:38.327363+00'),
  ('416f9fba-4e0c-4ee6-a2e8-e12b7119b36b', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What is the meaning/concept of an Intrapreneur?', 'Priority: Tier 1 | PYQ Connection: 2024 Q2B and 2025 Q2.3 — both directly require defining/explaining the intrapreneur.', 'An intrapreneur is an employee within an existing organisation who behaves like an entrepreneur — identifying opportunities, innovating new products/processes/ventures, and driving them forward — but does so using the organisation''s resources and under its umbrella, rather than starting an independent enterprise. The intrapreneur brings entrepreneurial thinking (innovation, initiative, risk-taking) inside a corporate structure.', NULL, NULL, NULL, 1, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', '8f63be53-4bee-48a2-ae1b-dcad02df809a', '{"blocks":[{"id":"bpem-u2-c1-q-1","text":"What is the meaning/concept of an Intrapreneur?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c1-a-1","text":"An intrapreneur is an employee within an existing organisation who behaves like an entrepreneur — identifying opportunities, innovating new products/processes/ventures, and driving them forward — but does so using the organisation''s resources and under its umbrella, rather than starting an independent enterprise. The intrapreneur brings entrepreneurial thinking (innovation, initiative, risk-taking) inside a corporate structure.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('87f69ceb-8b12-4677-9159-1b526cbca9c5', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'State the characteristics of an intrapreneur.', 'Priority: Tier 2 | PYQ Connection: Supports 2024/2025 intrapreneur questions if asked in "characteristics" form rather than "definition" form.', 'Innovative and idea-driven; self-motivated and proactive within the organisation; willing to take calculated risks within approved limits; comfortable working within organisational rules, budgets and reporting lines; strong internal networking/persuasion skills to get management buy-in; result-oriented and accountable for the project''s success, even though personal financial risk is limited.', NULL, NULL, NULL, 2, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', '8f63be53-4bee-48a2-ae1b-dcad02df809a', '{"blocks":[{"id":"bpem-u2-c2-q-1","text":"State the characteristics of an intrapreneur.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c2-a-1","text":"Innovative and idea-driven; self-motivated and proactive within the organisation; willing to take calculated risks within approved limits; comfortable working within organisational rules, budgets and reporting lines; strong internal networking/persuasion skills to get management buy-in; result-oriented and accountable for the project''s success, even though personal financial risk is limited.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('6b899ad9-3bec-4130-940d-c902028ccb76', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'How is intrapreneurship developed within an organisation?', 'Priority: Tier 2 | PYQ Connection: Natural extension of the "concept of intrapreneur" theme tested in both papers; likely follow-up/analytical variant.', 'Organisations foster intrapreneurship by: granting employees autonomy and "free time"/budget to pursue new ideas; building a culture that tolerates experimentation and failure; setting up internal innovation cells or incubators; rewarding and recognising successful internal ventures (bonuses, promotions, equity-like incentives); ensuring top management support and quick approval processes for promising ideas; and providing access to company resources, technology and market channels for the intrapreneur''s project.', NULL, NULL, NULL, 3, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', '8f63be53-4bee-48a2-ae1b-dcad02df809a', '{"blocks":[{"id":"bpem-u2-c3-q-1","text":"How is intrapreneurship developed within an organisation?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c3-a-1","text":"Organisations foster intrapreneurship by: granting employees autonomy and \"free time\"/budget to pursue new ideas; building a culture that tolerates experimentation and failure; setting up internal innovation cells or incubators; rewarding and recognising successful internal ventures (bonuses, promotions, equity-like incentives); ensuring top management support and quick approval processes for promising ideas; and providing access to company resources, technology and market channels for the intrapreneur''s project.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('b13d8d5f-893f-46c1-bf83-c144fb5833bd', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Differentiate between an Entrepreneur and an Intrapreneur, with suitable examples.', 'Priority: Tier 1 | PYQ Connection: 2025 Q2.3 — "differentiate between entrepreneur and intrapreneur with suitable examples" (direct match, 15 marks) and 2024 Q2B (note on intrapreneur with examples).', 'Basis | Entrepreneur | Intrapreneur
Ownership | Owns and starts an independent enterprise | Works within an existing organisation
Capital/Resources | Arranges own capital and resources | Uses the organisation''s capital and resources
Risk-bearing | Bears full personal financial risk | Organisation bears the financial risk; personal risk is largely career-related
Independence | Fully independent in decision-making | Operates within organisational policies and approval chains
Reward | Entitled to full profit (and loss) of the venture | Receives salary, bonus, or other incentives; not full residual profit
Objective | Builds and grows own enterprise | Drives innovation/growth for the employer''s enterprise

Example: An individual who leaves a job to found their own start-up (e.g., building an independent tech company) is an entrepreneur; an employee inside a large company who develops and champions a new internal product line using company resources (e.g., the internal team that built Gmail within Google) is acting as an intrapreneur.', NULL, NULL, NULL, 4, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', '8f63be53-4bee-48a2-ae1b-dcad02df809a', '{"blocks":[{"id":"bpem-u2-c4-q-1","text":"Differentiate between an Entrepreneur and an Intrapreneur, with suitable examples.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c4-a-1","rows":[["Basis","Entrepreneur","Intrapreneur"],["Ownership","Owns and starts an independent enterprise","Works within an existing organisation"],["Capital/Resources","Arranges own capital and resources","Uses the organisation''s capital and resources"],["Risk-bearing","Bears full personal financial risk","Organisation bears the financial risk; personal risk is largely career-related"],["Independence","Fully independent in decision-making","Operates within organisational policies and approval chains"],["Reward","Entitled to full profit (and loss) of the venture","Receives salary, bonus, or other incentives; not full residual profit"],["Objective","Builds and grows own enterprise","Drives innovation/growth for the employer''s enterprise"]],"type":"table"},{"id":"bpem-u2-c4-a-2","text":"Example: An individual who leaves a job to found their own start-up (e.g., building an independent tech company) is an entrepreneur; an employee inside a large company who develops and champions a new internal product line using company resources (e.g., the internal team that built Gmail within Google) is acting as an intrapreneur.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('a2adbede-71e9-452c-be2c-ba8eb4a13852', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What is the meaning/concept of a Women Entrepreneur?', 'Priority: Tier 1 | PYQ Connection: Foundational to 2024 Q2A (speech + government support, 10 marks).', 'A woman entrepreneur is a woman (or group of women) who initiates, organises and manages a business enterprise, taking on the associated risk and responsibility of ownership and decision-making, with the objectives of economic independence, wealth creation, and often, broader social empowerment.', NULL, NULL, NULL, 5, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', '717b71bc-6870-4555-be06-2b8e4aecabdd', '{"blocks":[{"id":"bpem-u2-c5-q-1","text":"What is the meaning/concept of a Women Entrepreneur?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c5-a-1","text":"A woman entrepreneur is a woman (or group of women) who initiates, organises and manages a business enterprise, taking on the associated risk and responsibility of ownership and decision-making, with the objectives of economic independence, wealth creation, and often, broader social empowerment.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('23a62b1a-fccd-4880-8bd6-f9bb77e03ccb', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Why is women entrepreneurship important?', 'Priority: Tier 1 | PYQ Connection: Supports the "speech motivating young women" theme (2024 Q2A) — motivational content typically draws on this importance.', 'It contributes to: economic independence and improved socio-economic status of women; additional household and national income; employment generation, particularly for other women; more inclusive and balanced economic development; diversification of the entrepreneurial talent pool; and a shift in social attitudes toward gender roles in business and leadership.', NULL, NULL, NULL, 6, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', '717b71bc-6870-4555-be06-2b8e4aecabdd', '{"blocks":[{"id":"bpem-u2-c6-q-1","text":"Why is women entrepreneurship important?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c6-a-1","text":"It contributes to: economic independence and improved socio-economic status of women; additional household and national income; employment generation, particularly for other women; more inclusive and balanced economic development; diversification of the entrepreneurial talent pool; and a shift in social attitudes toward gender roles in business and leadership.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('eb7f061d-28c4-4d9f-bac8-7fd249f9de8c', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What problems/challenges do women entrepreneurs commonly face?', 'Priority: Tier 1 | PYQ Connection: Directly relevant background for 2024 Q2A — a strong "speech" answer should acknowledge these barriers before motivating the audience to overcome them.', 'Common challenges include: gender bias and social/cultural attitudes discouraging women from business roles; limited access to capital and credit due to lack of collateral or financial independence; difficulty balancing family/household responsibilities with business demands; restricted mobility and networking opportunities in some social contexts; limited access to technical and managerial training; risk-averse conditioning from upbringing; and bureaucratic/legal hurdles in registration, licensing and compliance.', NULL, NULL, NULL, 7, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', '717b71bc-6870-4555-be06-2b8e4aecabdd', '{"blocks":[{"id":"bpem-u2-c7-q-1","text":"What problems/challenges do women entrepreneurs commonly face?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c7-a-1","text":"Common challenges include: gender bias and social/cultural attitudes discouraging women from business roles; limited access to capital and credit due to lack of collateral or financial independence; difficulty balancing family/household responsibilities with business demands; restricted mobility and networking opportunities in some social contexts; limited access to technical and managerial training; risk-averse conditioning from upbringing; and bureaucratic/legal hurdles in registration, licensing and compliance.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('d2c052ba-f196-42e8-8dd8-814ef93963f7', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Write a speech motivating young women toward entrepreneurship (key points to include).', 'Priority: Tier 1 | PYQ Connection: 2024 Q2A — direct match (speech format, 10 marks).', 'A strong speech-format answer should cover: (1) an opening that reframes entrepreneurship as a path to independence and self-worth, not just income; (2) acknowledgement of real barriers women face (family expectations, access to finance, social bias) — showing empathy builds credibility; (3) examples of successful women entrepreneurs (e.g., Kiran Mazumdar-Shaw of Biocon, Falguni Nayar of Nykaa) to show it is achievable; (4) practical starting points — Self Help Groups, government schemes, and small-scale/home-based ventures as low-risk entry points; (5) a call to action encouraging the audience to start small, seek mentorship, and use available support systems; (6) a closing message of confidence and collective empowerment.', NULL, NULL, NULL, 8, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', '717b71bc-6870-4555-be06-2b8e4aecabdd', '{"blocks":[{"id":"bpem-u2-c8-q-1","text":"Write a speech motivating young women toward entrepreneurship (key points to include).","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c8-a-1","text":"A strong speech-format answer should cover: (1) an opening that reframes entrepreneurship as a path to independence and self-worth, not just income; (2) acknowledgement of real barriers women face (family expectations, access to finance, social bias) — showing empathy builds credibility; (3) examples of successful women entrepreneurs (e.g., Kiran Mazumdar-Shaw of Biocon, Falguni Nayar of Nykaa) to show it is achievable; (4) practical starting points — Self Help Groups, government schemes, and small-scale/home-based ventures as low-risk entry points; (5) a call to action encouraging the audience to start small, seek mentorship, and use available support systems; (6) a closing message of confidence and collective empowerment.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('525ddfb9-8c8b-41f3-869e-862e66ea0821', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What institutional/government support is available to women entrepreneurs in India?', 'Priority: Tier 1 | PYQ Connection: 2024 Q2A — "highlight the support given by government to the women entrepreneur" (direct match).', 'Commonly cited support measures include: Stand-Up India (facilitating bank loans for women entrepreneurs for greenfield enterprises), the Pradhan Mantri Mudra Yojana (PMMY) (collateral-free loans for micro/small enterprises, widely used by women-led ventures), the TREAD (Trade Related Entrepreneurship Assistance and Development) scheme, Mahila e-Haat (an online marketing platform for women entrepreneurs/SHGs), and the SHG-Bank Linkage Programme promoted by NABARD, which channels credit to women through Self Help Groups. These aim to ease access to finance, provide skill training, and open market linkages for women entrepreneurs.', NULL, NULL, NULL, 9, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', '717b71bc-6870-4555-be06-2b8e4aecabdd', '{"blocks":[{"id":"bpem-u2-c9-q-1","text":"What institutional/government support is available to women entrepreneurs in India?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c9-a-1","text":"Commonly cited support measures include: Stand-Up India (facilitating bank loans for women entrepreneurs for greenfield enterprises), the Pradhan Mantri Mudra Yojana (PMMY) (collateral-free loans for micro/small enterprises, widely used by women-led ventures), the TREAD (Trade Related Entrepreneurship Assistance and Development) scheme, Mahila e-Haat (an online marketing platform for women entrepreneurs/SHGs), and the SHG-Bank Linkage Programme promoted by NABARD, which channels credit to women through Self Help Groups. These aim to ease access to finance, provide skill training, and open market linkages for women entrepreneurs.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('5118cf06-153c-4456-b378-98928e197e53', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What is the role of Self Help Groups (SHGs) in developing women entrepreneurs?', 'Priority: Tier 1 | PYQ Connection: 2024 Q2B (alternate) — "short note on Self Help Group and EDP" and syllabus point "Development of Women Entrepreneurs with reference to Self Help Groups."', 'SHGs are small, voluntary groups (typically of women) who regularly pool small savings and extend micro-credit to members without requiring traditional collateral. Their role in developing women entrepreneurs includes: building a savings and credit discipline; providing access to affordable finance for starting small enterprises; developing basic financial literacy, confidence and decision-making skills through group participation; enabling collective bargaining power for raw material purchase or product sale; and acting as a stepping stone from group-based micro-enterprise to individual entrepreneurship. The SHG-Bank Linkage model (promoted by NABARD) is the key mechanism connecting SHGs to formal banking credit.', NULL, NULL, NULL, 10, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', '717b71bc-6870-4555-be06-2b8e4aecabdd', '{"blocks":[{"id":"bpem-u2-c10-q-1","text":"What is the role of Self Help Groups (SHGs) in developing women entrepreneurs?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c10-a-1","text":"SHGs are small, voluntary groups (typically of women) who regularly pool small savings and extend micro-credit to members without requiring traditional collateral. Their role in developing women entrepreneurs includes: building a savings and credit discipline; providing access to affordable finance for starting small enterprises; developing basic financial literacy, confidence and decision-making skills through group participation; enabling collective bargaining power for raw material purchase or product sale; and acting as a stepping stone from group-based micro-enterprise to individual entrepreneurship. The SHG-Bank Linkage model (promoted by NABARD) is the key mechanism connecting SHGs to formal banking credit.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('91b2ea2d-4f22-4de8-a8ee-2e5dc9016bc8', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What is the meaning/concept of Social Entrepreneurship?', 'Priority: Tier 1 | PYQ Connection: 2024 Q2B and 2025 Q2.1 — both directly require explaining "who is a social entrepreneur."', 'Social entrepreneurship refers to the process of identifying and applying innovative, business-like methods to solve pressing social or environmental problems (e.g., poverty, education gaps, healthcare access, sanitation) in a financially sustainable way. Unlike a pure charity, the social enterprise typically aims to be self-sustaining or profitable to some degree, so that impact can be scaled and continued without permanent dependence on donations.', NULL, NULL, NULL, 11, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', '00baebe5-e38e-458e-9ed0-1e6beb8e9c6e', '{"blocks":[{"id":"bpem-u2-c11-q-1","text":"What is the meaning/concept of Social Entrepreneurship?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c11-a-1","text":"Social entrepreneurship refers to the process of identifying and applying innovative, business-like methods to solve pressing social or environmental problems (e.g., poverty, education gaps, healthcare access, sanitation) in a financially sustainable way. Unlike a pure charity, the social enterprise typically aims to be self-sustaining or profitable to some degree, so that impact can be scaled and continued without permanent dependence on donations.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('bf009e64-a286-4cb6-a237-0e0da7e9950d', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'State the characteristics of a social entrepreneur.', 'Priority: Tier 2 | PYQ Connection: Supports both 2024 Q2B and 2025 Q2.1 if the examiner asks for characteristics rather than a plain definition.', 'Mission-driven (social value creation is the primary goal, not just profit maximisation); innovative in designing solutions to social problems; resourceful in mobilising funding, volunteers and partnerships despite limited resources; committed to measurable social impact alongside (or above) financial return; and resilient/persistent, since social problems are often complex and slow to solve.', NULL, NULL, NULL, 12, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', '00baebe5-e38e-458e-9ed0-1e6beb8e9c6e', '{"blocks":[{"id":"bpem-u2-c12-q-1","text":"State the characteristics of a social entrepreneur.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c12-a-1","text":"Mission-driven (social value creation is the primary goal, not just profit maximisation); innovative in designing solutions to social problems; resourceful in mobilising funding, volunteers and partnerships despite limited resources; committed to measurable social impact alongside (or above) financial return; and resilient/persistent, since social problems are often complex and slow to solve.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('a8372152-cf55-4791-b8d8-113d132dd467', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What are the objectives of social entrepreneurship?', 'Priority: Tier 2 | PYQ Connection: Background depth for the recurring "social entrepreneur" theme.', 'To address unmet social needs where government or market solutions have failed; to create scalable and financially sustainable solutions rather than one-time relief; to generate employment and empower marginalised communities; and to balance social impact with a viable revenue/business model so the enterprise can continue and grow.', NULL, NULL, NULL, 13, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', '00baebe5-e38e-458e-9ed0-1e6beb8e9c6e', '{"blocks":[{"id":"bpem-u2-c13-q-1","text":"What are the objectives of social entrepreneurship?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c13-a-1","text":"To address unmet social needs where government or market solutions have failed; to create scalable and financially sustainable solutions rather than one-time relief; to generate employment and empower marginalised communities; and to balance social impact with a viable revenue/business model so the enterprise can continue and grow.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('c4195568-deb3-438f-a699-3926aff47560', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'How has social entrepreneurship developed in India?', 'Priority: Tier 2 | PYQ Connection: Full syllabus point ("Development of Social Entrepreneurship in India") not directly tested yet, but a natural extension of the recurring social-entrepreneur theme.', 'India has seen growing social entrepreneurship activity through: NGOs transitioning into self-sustaining social enterprises rather than relying purely on donations; the rise of impact investing and social venture funds supporting mission-driven start-ups; well-known examples such as Aravind Eye Care System (affordable, scalable eye-care), SELCO India (solar energy solutions for underserved communities), and Amul (cooperative dairy model uplifting rural farmers); increased institutional support through incubators, business plan competitions and CSR-linked funding; and growing recognition of the "double bottom line" (social impact + financial sustainability) as a legitimate business model in Indian B-school and policy discourse.', NULL, NULL, NULL, 14, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', '00baebe5-e38e-458e-9ed0-1e6beb8e9c6e', '{"blocks":[{"id":"bpem-u2-c14-q-1","text":"How has social entrepreneurship developed in India?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c14-a-1","text":"India has seen growing social entrepreneurship activity through: NGOs transitioning into self-sustaining social enterprises rather than relying purely on donations; the rise of impact investing and social venture funds supporting mission-driven start-ups; well-known examples such as Aravind Eye Care System (affordable, scalable eye-care), SELCO India (solar energy solutions for underserved communities), and Amul (cooperative dairy model uplifting rural farmers); increased institutional support through incubators, business plan competitions and CSR-linked funding; and growing recognition of the \"double bottom line\" (social impact + financial sustainability) as a legitimate business model in Indian B-school and policy discourse.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('8329983f-b250-4ec7-bbb5-a223d78d5f73', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Write a motivating speech for a friend who is an upcoming social entrepreneur (key points to include).', 'Priority: Tier 1 | PYQ Connection: 2025 Q2.1 — direct match (speech format).', 'A strong answer should include: (1) validating that solving a real social problem while building a sustainable enterprise is both impactful and challenging; (2) emphasising that a social enterprise must still be financially viable to create lasting impact — it is not the same as charity; (3) citing inspiring examples (e.g., Aravind Eye Care, SELCO) to show scalable social models succeed; (4) practical encouragement — start with a clearly defined social problem, a lean/sustainable revenue model, and measurable impact goals; (5) acknowledging resource constraints are real but solvable through partnerships, grants, and impact investors; (6) a motivating close on the long-term significance of the work.', NULL, NULL, NULL, 15, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', '00baebe5-e38e-458e-9ed0-1e6beb8e9c6e', '{"blocks":[{"id":"bpem-u2-c15-q-1","text":"Write a motivating speech for a friend who is an upcoming social entrepreneur (key points to include).","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c15-a-1","text":"A strong answer should include: (1) validating that solving a real social problem while building a sustainable enterprise is both impactful and challenging; (2) emphasising that a social enterprise must still be financially viable to create lasting impact — it is not the same as charity; (3) citing inspiring examples (e.g., Aravind Eye Care, SELCO) to show scalable social models succeed; (4) practical encouragement — start with a clearly defined social problem, a lean/sustainable revenue model, and measurable impact goals; (5) acknowledging resource constraints are real but solvable through partnerships, grants, and impact investors; (6) a motivating close on the long-term significance of the work.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('0515b243-2bd0-44ce-8c14-ddd0536f0b88', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Differentiate between a Social Entrepreneur and a conventional Entrepreneur.', 'Priority: Tier 2 | PYQ Connection: Natural comparison extension of the recurring social-entrepreneur theme; not directly asked but examinable.', 'Basis | Conventional Entrepreneur | Social Entrepreneur
Primary objective | Profit maximisation | Social/environmental impact, alongside financial sustainability
Measure of success | Financial performance (revenue, profit, market share) | Social impact achieved, plus financial sustainability
Target beneficiary | Customers/shareholders | Underserved communities/society at large
Business model | Fully profit-driven | Often a "double bottom line" (impact + modest/self-sustaining profit)', NULL, NULL, NULL, 16, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', '00baebe5-e38e-458e-9ed0-1e6beb8e9c6e', '{"blocks":[{"id":"bpem-u2-c16-q-1","text":"Differentiate between a Social Entrepreneur and a conventional Entrepreneur.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c16-a-1","rows":[["Basis","Conventional Entrepreneur","Social Entrepreneur"],["Primary objective","Profit maximisation","Social/environmental impact, alongside financial sustainability"],["Measure of success","Financial performance (revenue, profit, market share)","Social impact achieved, plus financial sustainability"],["Target beneficiary","Customers/shareholders","Underserved communities/society at large"],["Business model","Fully profit-driven","Often a \"double bottom line\" (impact + modest/self-sustaining profit)"]],"type":"table"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('1a64d503-c4d1-4e38-9fde-f75690d03d92', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What is the meaning/concept of an Entrepreneurship Development Programme (EDP)?', 'Priority: Tier 1 | PYQ Connection: 2024 Q2B (alternate) — "short note on Self Help Group and EDP" (direct match).', 'An EDP is a structured training programme designed to identify potential entrepreneurs and develop their entrepreneurial knowledge, skills, attitudes and behaviour — covering areas such as opportunity/idea identification, business plan preparation, finance, marketing, and basic legal/regulatory knowledge — so that participants are better equipped to successfully start and manage their own enterprise.', NULL, NULL, NULL, 17, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', 'e948baeb-4797-4793-874b-19364bd2e385', '{"blocks":[{"id":"bpem-u2-c17-q-1","text":"What is the meaning/concept of an Entrepreneurship Development Programme (EDP)?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c17-a-1","text":"An EDP is a structured training programme designed to identify potential entrepreneurs and develop their entrepreneurial knowledge, skills, attitudes and behaviour — covering areas such as opportunity/idea identification, business plan preparation, finance, marketing, and basic legal/regulatory knowledge — so that participants are better equipped to successfully start and manage their own enterprise.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('be539d52-b1df-4ec3-92f4-c79b0e582063', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What is the importance of EDP in entrepreneurship development?', 'Priority: Tier 2 | PYQ Connection: Supports the recurring EDP theme (2024 Q2B alternate).', 'EDPs bridge the gap between "potential" and "actual" entrepreneurs by building confidence, technical know-how and managerial competence; reduce the rate of business failure through structured planning guidance; motivate participants (especially first-generation entrepreneurs) who may lack a business family background; and often connect participants to funding sources, mentors and market linkages after training.', NULL, NULL, NULL, 18, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', 'e948baeb-4797-4793-874b-19364bd2e385', '{"blocks":[{"id":"bpem-u2-c18-q-1","text":"What is the importance of EDP in entrepreneurship development?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c18-a-1","text":"EDPs bridge the gap between \"potential\" and \"actual\" entrepreneurs by building confidence, technical know-how and managerial competence; reduce the rate of business failure through structured planning guidance; motivate participants (especially first-generation entrepreneurs) who may lack a business family background; and often connect participants to funding sources, mentors and market linkages after training.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('adec7926-b3a9-415e-a400-a09805e60f22', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What factors influence the effectiveness of an EDP?', 'Priority: Tier 1 | PYQ Connection: Explicit syllabus point ("Factors influencing EDP") and a natural depth-add to the 2024 EDP short-note question.', 'Key factors include: the quality and relevance of the training curriculum; the competence and experience of trainers/mentors; careful selection of participants with genuine entrepreneurial potential; availability of adequate infrastructure and financial support during and after training; institutional/government backing and follow-up support once the programme ends; the motivation level and background of participants; and the availability of market linkages and continued mentorship after the formal training concludes.', NULL, NULL, NULL, 19, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', 'e948baeb-4797-4793-874b-19364bd2e385', '{"blocks":[{"id":"bpem-u2-c19-q-1","text":"What factors influence the effectiveness of an EDP?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c19-a-1","text":"Key factors include: the quality and relevance of the training curriculum; the competence and experience of trainers/mentors; careful selection of participants with genuine entrepreneurial potential; availability of adequate infrastructure and financial support during and after training; institutional/government backing and follow-up support once the programme ends; the motivation level and background of participants; and the availability of market linkages and continued mentorship after the formal training concludes.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('88575bf8-4e4b-4206-92a3-e859498d3833', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Write a short note comparing SHG and EDP as tools of entrepreneurship development.', 'Priority: Tier 1 | PYQ Connection: 2024 Q2B (alternate) — "short note on Self Help Group and EDP" (direct match).', 'Both aim to build entrepreneurial capacity among individuals who otherwise lack access to capital, skills or confidence, but they differ in approach: an SHG is a group-based, member-driven savings-and-credit model, primarily used to extend micro-finance and build collective confidence, especially among women; an EDP is a formal, structured training programme run by institutions (government bodies, business schools, NGOs) that builds specific entrepreneurial skills (business planning, finance, marketing) for individuals, regardless of gender or group membership. SHGs are often a more grassroots, informal, community-based route, while EDPs are a more formal, curriculum-driven route — the two can complement each other, with SHG members sometimes going on to attend EDPs.', NULL, NULL, NULL, 20, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', 'e948baeb-4797-4793-874b-19364bd2e385', '{"blocks":[{"id":"bpem-u2-c20-q-1","text":"Write a short note comparing SHG and EDP as tools of entrepreneurship development.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c20-a-1","text":"Both aim to build entrepreneurial capacity among individuals who otherwise lack access to capital, skills or confidence, but they differ in approach: an SHG is a group-based, member-driven savings-and-credit model, primarily used to extend micro-finance and build collective confidence, especially among women; an EDP is a formal, structured training programme run by institutions (government bodies, business schools, NGOs) that builds specific entrepreneurial skills (business planning, finance, marketing) for individuals, regardless of gender or group membership. SHGs are often a more grassroots, informal, community-based route, while EDPs are a more formal, curriculum-driven route — the two can complement each other, with SHG members sometimes going on to attend EDPs.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('cc096887-9262-4a06-b6ba-2e29e1f20cc6', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What is Ancillarisation? Why is it considered a fast route to establishing a business?', 'Priority: Tier 2 | PYQ Connection: Not directly tested in the supplied papers; full syllabus topic under "Fast Routes to Establish Business."', 'Ancillarisation refers to setting up a small/ancillary unit that manufactures components, parts, or provides services required by a larger "parent" (usually large-scale) industry. It is considered a fast route because: the ancillary unit has an assured market in the parent company, removing much of the demand uncertainty; it typically requires lower capital investment than a full independent enterprise; the parent company often provides technical know-how, quality standards, and sometimes managerial guidance; and the ancillary unit can be set up relatively quickly since it plugs into an already-established supply chain rather than building market access from scratch.', NULL, NULL, NULL, 21, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', 'ef3fff41-d417-4f3f-a144-bbfccb32ca76', '{"blocks":[{"id":"bpem-u2-c21-q-1","text":"What is Ancillarisation? Why is it considered a fast route to establishing a business?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c21-a-1","text":"Ancillarisation refers to setting up a small/ancillary unit that manufactures components, parts, or provides services required by a larger \"parent\" (usually large-scale) industry. It is considered a fast route because: the ancillary unit has an assured market in the parent company, removing much of the demand uncertainty; it typically requires lower capital investment than a full independent enterprise; the parent company often provides technical know-how, quality standards, and sometimes managerial guidance; and the ancillary unit can be set up relatively quickly since it plugs into an already-established supply chain rather than building market access from scratch.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('016197d2-58aa-4ea3-bdcd-bde4a9f788d8', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What is BPO? Why is it considered a fast route to establishing a business?', 'Priority: Tier 2 | PYQ Connection: Not directly tested in the supplied papers; full syllabus topic under "Fast Routes to Establish Business."', 'BPO (Business Process Outsourcing) involves setting up a unit that performs specific business processes (e.g., customer support, data entry/processing, HR or finance-related back-office work) on a contractual basis for other companies, domestically or internationally. It is considered a fast route because it is largely knowledge/people-based rather than capital/asset-heavy, requiring comparatively low fixed investment (mainly office space, computers, and trained staff); it can tap into strong global demand for cost-effective outsourced services; and it can typically be operational much faster than a manufacturing enterprise, since it does not require plant, machinery or complex supply chains.', NULL, NULL, NULL, 22, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', 'ef3fff41-d417-4f3f-a144-bbfccb32ca76', '{"blocks":[{"id":"bpem-u2-c22-q-1","text":"What is BPO? Why is it considered a fast route to establishing a business?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c22-a-1","text":"BPO (Business Process Outsourcing) involves setting up a unit that performs specific business processes (e.g., customer support, data entry/processing, HR or finance-related back-office work) on a contractual basis for other companies, domestically or internationally. It is considered a fast route because it is largely knowledge/people-based rather than capital/asset-heavy, requiring comparatively low fixed investment (mainly office space, computers, and trained staff); it can tap into strong global demand for cost-effective outsourced services; and it can typically be operational much faster than a manufacturing enterprise, since it does not require plant, machinery or complex supply chains.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('49edc708-49e2-4def-afa1-563d31b16ce9', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What is franchising? Why is franchising considered one of the fastest routes to establish a business?', 'Priority: Tier 1 | PYQ Connection: 2025 Q2.2 — direct match ("why is franchising considered one of the fastest routes," 15 marks).', 'Franchising is a business arrangement in which the franchisor (owner of an established brand/business model) grants a franchisee the right to use its trademark, business systems, and operating processes in exchange for a fee and/or ongoing royalty. It is considered one of the fastest routes to establish a business because the franchisee starts with an already-established brand name and customer recognition, eliminating the time and cost of building a brand from zero; the business model, operating procedures and quality standards are already proven and tested, reducing trial-and-error; the franchisor typically provides training, initial setup support, and ongoing operational guidance; and supply chains and marketing systems are already in place, allowing the franchisee to become operational and profitable much faster than an independent start-up.', NULL, NULL, NULL, 23, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', 'ef3fff41-d417-4f3f-a144-bbfccb32ca76', '{"blocks":[{"id":"bpem-u2-c23-q-1","text":"What is franchising? Why is franchising considered one of the fastest routes to establish a business?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c23-a-1","text":"Franchising is a business arrangement in which the franchisor (owner of an established brand/business model) grants a franchisee the right to use its trademark, business systems, and operating processes in exchange for a fee and/or ongoing royalty. It is considered one of the fastest routes to establish a business because the franchisee starts with an already-established brand name and customer recognition, eliminating the time and cost of building a brand from zero; the business model, operating procedures and quality standards are already proven and tested, reducing trial-and-error; the franchisor typically provides training, initial setup support, and ongoing operational guidance; and supply chains and marketing systems are already in place, allowing the franchisee to become operational and profitable much faster than an independent start-up.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('73a49518-fecd-486a-b49d-79f450e65ea0', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Explain the advantages franchising offers compared to starting an independent venture.', 'Priority: Tier 1 | PYQ Connection: 2025 Q2.2 — direct match ("advantages it offers... compared to starting an independent venture").', 'Compared to an independent venture, franchising offers: lower risk of failure, since the business model is already market-tested; immediate brand recognition and customer trust, avoiding years of brand-building; training and ongoing operational support from the franchisor (site selection, staff training, standard operating procedures); established supply chain and bulk-purchasing benefits, often at lower costs than an independent business could negotiate alone; shared marketing and advertising, typically funded partly by the franchisor at a national/regional level; and generally a faster path to profitability/break-even, since the franchisee is not building demand from scratch.', NULL, NULL, NULL, 24, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', 'ef3fff41-d417-4f3f-a144-bbfccb32ca76', '{"blocks":[{"id":"bpem-u2-c24-q-1","text":"Explain the advantages franchising offers compared to starting an independent venture.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c24-a-1","text":"Compared to an independent venture, franchising offers: lower risk of failure, since the business model is already market-tested; immediate brand recognition and customer trust, avoiding years of brand-building; training and ongoing operational support from the franchisor (site selection, staff training, standard operating procedures); established supply chain and bulk-purchasing benefits, often at lower costs than an independent business could negotiate alone; shared marketing and advertising, typically funded partly by the franchisor at a national/regional level; and generally a faster path to profitability/break-even, since the franchisee is not building demand from scratch.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('96319114-8054-4222-9d76-5bce05091f65', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What are the limitations of franchising for the franchisee?', 'Priority: Tier 2 | PYQ Connection: A natural "limitations" counter-question to the 2025 franchise question; strengthens exam readiness if asked for a balanced view.', 'Limitations include: ongoing royalty and franchise fee payments that reduce net profit; limited independence/control, since the franchisee must follow the franchisor''s set processes, branding and pricing guidelines; shared brand reputation risk — problems at other franchise outlets or with the parent brand can affect the local franchisee; and a comparatively high initial franchise fee in well-established brands, which can still represent a significant capital outlay.', NULL, NULL, NULL, 25, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', 'ef3fff41-d417-4f3f-a144-bbfccb32ca76', '{"blocks":[{"id":"bpem-u2-c25-q-1","text":"What are the limitations of franchising for the franchisee?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c25-a-1","text":"Limitations include: ongoing royalty and franchise fee payments that reduce net profit; limited independence/control, since the franchisee must follow the franchisor''s set processes, branding and pricing guidelines; shared brand reputation risk — problems at other franchise outlets or with the parent brand can affect the local franchisee; and a comparatively high initial franchise fee in well-established brands, which can still represent a significant capital outlay.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('2cdc02f0-4333-450a-965f-b3b015ea451d', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Differentiate between a Franchise business and an Independent business.', 'Priority: Tier 1 | PYQ Connection: Direct extension of 2025 Q2.2 ("advantages... compared to starting an independent venture").', 'Basis | Franchise Business | Independent Business
Brand | Uses an established, recognised brand | Must build brand from scratch
Business model | Proven, standardised model provided by franchisor | Entrepreneur designs the entire model
Risk | Lower — model already market-tested | Higher — no track record to rely on
Support | Training, supply chain and marketing support from franchisor | Entrepreneur arranges everything independently
Control/Independence | Limited — must follow franchisor''s rules | Full control over all business decisions
Costs | Franchise fee + ongoing royalty | No royalty, but all setup costs borne alone', NULL, NULL, NULL, 26, true, 'University Exam', NULL, NULL, NULL, 'bc160fd3-c590-410e-b705-72a3718107a8', 'ef3fff41-d417-4f3f-a144-bbfccb32ca76', '{"blocks":[{"id":"bpem-u2-c26-q-1","text":"Differentiate between a Franchise business and an Independent business.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u2-c26-a-1","rows":[["Basis","Franchise Business","Independent Business"],["Brand","Uses an established, recognised brand","Must build brand from scratch"],["Business model","Proven, standardised model provided by franchisor","Entrepreneur designs the entire model"],["Risk","Lower — model already market-tested","Higher — no track record to rely on"],["Support","Training, supply chain and marketing support from franchisor","Entrepreneur arranges everything independently"],["Control/Independence","Limited — must follow franchisor''s rules","Full control over all business decisions"],["Costs","Franchise fee + ongoing royalty","No royalty, but all setup costs borne alone"]],"type":"table"}],"version":1}'::jsonb, '2026-09-21 02:33:41.145477+00', '2026-09-21 02:33:41.145477+00'),
  ('ec03bbf8-18ff-4b06-9380-14d6f75ccfe1', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Distinguish between Invention, Innovation and Creativity.', 'Priority: Tier 1 | PYQ Connection: 2024 Q3A — "role of creativity and innovation in entrepreneurship" (10 marks); this distinction is the necessary foundation for a full-marks answer.', 'Concept | Meaning
Creativity | The mental process of generating new ideas, concepts or associations — the ability to think of something original. It is the source of new possibilities.
Invention | The creation of something genuinely new — a new product, process, or technology that did not exist before. It is the output of creative/technical effort, often research-driven.
Innovation | The successful commercial application or exploitation of an invention (or an existing idea) — converting a new idea into a marketable product, process or service that creates economic/customer value.

In short: Creativity generates the idea → Invention creates the new thing → Innovation makes it commercially useful. Creativity is necessary but not sufficient for innovation; many inventions never become innovations because they are never successfully commercialised.', NULL, NULL, NULL, 1, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', 'dd07aa0b-2ec9-4fe9-b3fc-e6d19155dd97', '{"blocks":[{"id":"bpem-u3-c1-q-1","text":"Distinguish between Invention, Innovation and Creativity.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c1-a-1","rows":[["Concept","Meaning"],["Creativity","The mental process of generating new ideas, concepts or associations — the ability to think of something original. It is the source of new possibilities."],["Invention","The creation of something genuinely new — a new product, process, or technology that did not exist before. It is the output of creative/technical effort, often research-driven."],["Innovation","The successful commercial application or exploitation of an invention (or an existing idea) — converting a new idea into a marketable product, process or service that creates economic/customer value."]],"type":"table"},{"id":"bpem-u3-c1-a-2","text":"In short: Creativity generates the idea → Invention creates the new thing → Innovation makes it commercially useful. Creativity is necessary but not sufficient for innovation; many inventions never become innovations because they are never successfully commercialised.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('9801c13c-ee1c-484a-abf4-d6bd7151a8bb', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Explain the relationship between creativity, invention and innovation.', 'Priority: Tier 2 | PYQ Connection: Supports 2024 Q3A as conceptual depth beyond a plain definition.', 'The three form a sequential chain: creativity is the cognitive process that produces novel ideas; when a creative idea is technically developed into something new, it becomes an invention; when that invention (or any new idea) is successfully brought to market and adopted by customers, it becomes an innovation. An entrepreneur''s core value-add often lies not in being the most creative or the original inventor, but in being the one who successfully innovates — i.e., converts an idea or invention into a viable, adopted business offering.', NULL, NULL, NULL, 2, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', 'dd07aa0b-2ec9-4fe9-b3fc-e6d19155dd97', '{"blocks":[{"id":"bpem-u3-c2-q-1","text":"Explain the relationship between creativity, invention and innovation.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c2-a-1","text":"The three form a sequential chain: creativity is the cognitive process that produces novel ideas; when a creative idea is technically developed into something new, it becomes an invention; when that invention (or any new idea) is successfully brought to market and adopted by customers, it becomes an innovation. An entrepreneur''s core value-add often lies not in being the most creative or the original inventor, but in being the one who successfully innovates — i.e., converts an idea or invention into a viable, adopted business offering.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('50177358-ea74-4aae-b76f-7210003e67b3', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Discuss the role of creativity and innovation in entrepreneurship.', 'Priority: Tier 1 | PYQ Connection: 2024 Q3A — direct match (10 marks).', 'Creativity and innovation are central to entrepreneurship because they: (1) help identify unique, unmet market opportunities that competitors have overlooked; (2) enable product/service differentiation, creating competitive advantage; (3) allow entrepreneurs to solve problems in novel, more efficient ways, reducing cost or improving quality; (4) drive business growth and renewal, since markets and technologies keep changing; (5) are the mechanism through which an entrepreneur converts an ordinary idea into a scalable business opportunity (per Schumpeter''s view of the entrepreneur as an innovator, covered in Unit 1); and (6) help a venture stay relevant by continuously adapting to changing customer needs and external conditions.', NULL, NULL, NULL, 3, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', 'dd07aa0b-2ec9-4fe9-b3fc-e6d19155dd97', '{"blocks":[{"id":"bpem-u3-c3-q-1","text":"Discuss the role of creativity and innovation in entrepreneurship.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c3-a-1","text":"Creativity and innovation are central to entrepreneurship because they: (1) help identify unique, unmet market opportunities that competitors have overlooked; (2) enable product/service differentiation, creating competitive advantage; (3) allow entrepreneurs to solve problems in novel, more efficient ways, reducing cost or improving quality; (4) drive business growth and renewal, since markets and technologies keep changing; (5) are the mechanism through which an entrepreneur converts an ordinary idea into a scalable business opportunity (per Schumpeter''s view of the entrepreneur as an innovator, covered in Unit 1); and (6) help a venture stay relevant by continuously adapting to changing customer needs and external conditions.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('d6a20787-b824-47bf-9842-93ef91a49362', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What does "Opportunities through Change" mean in the entrepreneurial context?', 'Priority: Tier 2 | PYQ Connection: Syllabus sub-point under "Innovation and Opportunity"; not directly tested yet but a natural companion to the creativity/innovation question.', 'Changes in the external environment — technological advances, shifts in demographics, changes in government regulation/policy, evolving consumer preferences, or economic shifts — constantly create gaps between what the market currently offers and what it now needs. An alert entrepreneur treats such change as a source of opportunity rather than a threat, spotting the gap early and building a venture to fill it before competitors react. This links directly to environmental scanning (Section C) as the tool used to detect such changes.', NULL, NULL, NULL, 4, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', 'dd07aa0b-2ec9-4fe9-b3fc-e6d19155dd97', '{"blocks":[{"id":"bpem-u3-c4-q-1","text":"What does \"Opportunities through Change\" mean in the entrepreneurial context?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c4-a-1","text":"Changes in the external environment — technological advances, shifts in demographics, changes in government regulation/policy, evolving consumer preferences, or economic shifts — constantly create gaps between what the market currently offers and what it now needs. An alert entrepreneur treats such change as a source of opportunity rather than a threat, spotting the gap early and building a venture to fill it before competitors react. This links directly to environmental scanning (Section C) as the tool used to detect such changes.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('297b508d-fe62-432f-b738-880c5525e08f', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What are the main sources of business ideas?', 'Priority: Tier 1 | PYQ Connection: 2024 Q3B — "different ways of generating new ideas for business" (9 marks) and 2025 Q3.1 — direct match in both papers.', 'Common sources include: personal experience, hobbies and skills; observation of gaps or unmet needs in the market; changes in technology creating new possibilities; changes in government policy/regulation opening new sectors; family business background; trade fairs, exhibitions and industry events; customer complaints and feedback on existing products; competitor products and services (studied for improvement opportunities); market research and surveys; and general reading — trade journals, magazines, and industry reports.', NULL, NULL, NULL, 5, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', 'c0ef4301-53aa-40cd-a6d8-bd05cef3477e', '{"blocks":[{"id":"bpem-u3-c5-q-1","text":"What are the main sources of business ideas?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c5-a-1","text":"Common sources include: personal experience, hobbies and skills; observation of gaps or unmet needs in the market; changes in technology creating new possibilities; changes in government policy/regulation opening new sectors; family business background; trade fairs, exhibitions and industry events; customer complaints and feedback on existing products; competitor products and services (studied for improvement opportunities); market research and surveys; and general reading — trade journals, magazines, and industry reports.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('b80b79f4-3c78-4f5c-b5ee-0a5c964f9609', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Explain the techniques/methods used for generating innovative business ideas.', 'Priority: Tier 1 | PYQ Connection: 2025 Q3.1 — "explain different techniques used for generating innovative business ideas" (direct match, 15 marks).', 'Key techniques include: brainstorming (group idea generation without immediate criticism, to maximise quantity of ideas); focus groups (structured discussion with target customers to surface unmet needs); problem inventory analysis (starting from a list of known customer problems and generating solutions); market research and surveys (systematically identifying gaps in customer needs); analysis of customer complaints on existing products/services; reverse engineering/studying competitor offerings for improvement opportunities; and trend/technology scanning (observing emerging technologies or social trends for early-mover opportunities).', NULL, NULL, NULL, 6, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', 'c0ef4301-53aa-40cd-a6d8-bd05cef3477e', '{"blocks":[{"id":"bpem-u3-c6-q-1","text":"Explain the techniques/methods used for generating innovative business ideas.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c6-a-1","text":"Key techniques include: brainstorming (group idea generation without immediate criticism, to maximise quantity of ideas); focus groups (structured discussion with target customers to surface unmet needs); problem inventory analysis (starting from a list of known customer problems and generating solutions); market research and surveys (systematically identifying gaps in customer needs); analysis of customer complaints on existing products/services; reverse engineering/studying competitor offerings for improvement opportunities; and trend/technology scanning (observing emerging technologies or social trends for early-mover opportunities).","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('de341cd1-c6f7-48fe-a85b-db1c3288baa1', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Explain the process of developing a business idea into a product.', 'Priority: Tier 2 | PYQ Connection: Syllabus point "Development of product/idea"; a natural process-style extension of the recurring idea-generation theme.', 'The typical sequence is: (1) Idea screening — filtering raw ideas for basic viability and fit with entrepreneur''s resources/interests; (2) Concept development and testing — refining the idea into a clear product/service concept and testing customer reaction; (3) Feasibility analysis — assessing technical, market and financial viability (see Section E); (4) Prototype/pilot development — building a working sample or minimum viable version; (5) Test marketing — offering the product on a small scale to gauge real market response; and (6) Commercialisation/launch — full-scale production and market rollout once the concept is validated. This process converts a raw idea into a tested, launch-ready business opportunity.', NULL, NULL, NULL, 7, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', 'c0ef4301-53aa-40cd-a6d8-bd05cef3477e', '{"blocks":[{"id":"bpem-u3-c7-q-1","text":"Explain the process of developing a business idea into a product.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c7-a-1","text":"The typical sequence is: (1) Idea screening — filtering raw ideas for basic viability and fit with entrepreneur''s resources/interests; (2) Concept development and testing — refining the idea into a clear product/service concept and testing customer reaction; (3) Feasibility analysis — assessing technical, market and financial viability (see Section E); (4) Prototype/pilot development — building a working sample or minimum viable version; (5) Test marketing — offering the product on a small scale to gauge real market response; and (6) Commercialisation/launch — full-scale production and market rollout once the concept is validated. This process converts a raw idea into a tested, launch-ready business opportunity.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('0e6a88c5-9565-4eed-b918-6bbb2bff7931', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', '"Idea generation" vs "Opportunity" — what is the distinction, and why does it matter?', 'Priority: Tier 2 | PYQ Connection: Conceptual bridge connecting the idea-generation theme (tested in both papers) to feasibility analysis and environmental scanning (Sections C and E).', 'An idea is simply a possible concept for a product/service — it is untested and may or may not have market demand. An opportunity is an idea that has been validated as having genuine, addressable market demand, a feasible business model, and timing/conditions favourable for launch. The distinction matters because entrepreneurship depends not on having ideas (which are abundant) but on correctly identifying which ideas are true opportunities — this is exactly what feasibility analysis and environmental scanning are designed to test.', NULL, NULL, NULL, 8, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', 'c0ef4301-53aa-40cd-a6d8-bd05cef3477e', '{"blocks":[{"id":"bpem-u3-c8-q-1","text":"\"Idea generation\" vs \"Opportunity\" — what is the distinction, and why does it matter?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c8-a-1","text":"An idea is simply a possible concept for a product/service — it is untested and may or may not have market demand. An opportunity is an idea that has been validated as having genuine, addressable market demand, a feasible business model, and timing/conditions favourable for launch. The distinction matters because entrepreneurship depends not on having ideas (which are abundant) but on correctly identifying which ideas are true opportunities — this is exactly what feasibility analysis and environmental scanning are designed to test.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('33bc510a-88cf-42d2-a1ef-724fea242744', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What is Environmental Scanning? What is its purpose?', 'Priority: Tier 2 | PYQ Connection: Not directly tested as a standalone question in the supplied papers, but forms the analytical basis for SWOT Analysis (2025 Q3.3) and "opportunities through change."', 'Environmental scanning is the continuous process of monitoring and analysing both the external environment (economic, political, social, technological, legal and competitive factors) and the internal environment (organisational resources and capabilities) in order to identify emerging trends, opportunities and threats relevant to business decision-making. Its purpose is to give the entrepreneur early warning of changes so the venture can adapt proactively rather than react too late.', NULL, NULL, NULL, 9, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', 'd1345909-2234-4a4e-a7fc-c98d97d29da1', '{"blocks":[{"id":"bpem-u3-c9-q-1","text":"What is Environmental Scanning? What is its purpose?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c9-a-1","text":"Environmental scanning is the continuous process of monitoring and analysing both the external environment (economic, political, social, technological, legal and competitive factors) and the internal environment (organisational resources and capabilities) in order to identify emerging trends, opportunities and threats relevant to business decision-making. Its purpose is to give the entrepreneur early warning of changes so the venture can adapt proactively rather than react too late.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('d906ff2a-5cc8-4a6a-bd4b-4711f6fc4e0a', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Why is environmental scanning important for an entrepreneur?', 'Priority: Tier 2 | PYQ Connection: Supporting depth for SWOT (2025 Q3.3) and business planning (2025 Q3.2) questions.', 'It reduces uncertainty by systematically tracking external change; feeds directly into opportunity identification (spotting gaps created by regulatory, technological or social shifts); supports realistic business planning by grounding assumptions in actual market/industry conditions; and forms the informational base for tools such as SWOT analysis and feasibility analysis.', NULL, NULL, NULL, 10, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', 'd1345909-2234-4a4e-a7fc-c98d97d29da1', '{"blocks":[{"id":"bpem-u3-c10-q-1","text":"Why is environmental scanning important for an entrepreneur?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c10-a-1","text":"It reduces uncertainty by systematically tracking external change; feeds directly into opportunity identification (spotting gaps created by regulatory, technological or social shifts); supports realistic business planning by grounding assumptions in actual market/industry conditions; and forms the informational base for tools such as SWOT analysis and feasibility analysis.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('4bcf79f8-2bad-45b6-ae57-66e4a8abf2ff', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What is the Entrepreneurship Development Cycle (EDC)? What are its phases?', 'Priority: Tier 1 | PYQ Connection: 2024 Q3Q — "discuss the different phases of Entrepreneurship Development Cycle" (direct match, 9 marks).', 'The Entrepreneurship Development Cycle is the structured sequence of stages through which a potential entrepreneur is identified, motivated, trained and supported until a sustainable enterprise is established and grown. It is generally understood in three broad phases:

Stimulation Phase — creating awareness about entrepreneurship as a career option, identifying and motivating potential entrepreneurs (often through Entrepreneurship Development Programmes/EDPs), and building the confidence and basic knowledge needed to consider starting a venture.
Support Phase — providing practical assistance to convert motivation into action: help with business registration and legal formalities, access to finance/credit, infrastructure support, guidance on selecting a viable project, and connecting the entrepreneur to relevant government schemes or institutions.
Sustenance (Development) Phase — assistance provided after the enterprise is established, to help it survive and grow: marketing assistance, modernisation and technology upgradation support, expansion guidance, and ongoing mentorship to help the venture scale sustainably.', NULL, NULL, NULL, 16, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', '6ac261c7-7c05-493b-b931-bf7a09340ef7', '{"blocks":[{"id":"bpem-u3-c16-q-1","text":"What is the Entrepreneurship Development Cycle (EDC)? What are its phases?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c16-a-1","text":"The Entrepreneurship Development Cycle is the structured sequence of stages through which a potential entrepreneur is identified, motivated, trained and supported until a sustainable enterprise is established and grown. It is generally understood in three broad phases:","type":"text","style":"paragraph"},{"id":"bpem-u3-c16-a-2","type":"numberList","items":["Stimulation Phase — creating awareness about entrepreneurship as a career option, identifying and motivating potential entrepreneurs (often through Entrepreneurship Development Programmes/EDPs), and building the confidence and basic knowledge needed to consider starting a venture.","Support Phase — providing practical assistance to convert motivation into action: help with business registration and legal formalities, access to finance/credit, infrastructure support, guidance on selecting a viable project, and connecting the entrepreneur to relevant government schemes or institutions.","Sustenance (Development) Phase — assistance provided after the enterprise is established, to help it survive and grow: marketing assistance, modernisation and technology upgradation support, expansion guidance, and ongoing mentorship to help the venture scale sustainably."]}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('c539680f-5e69-47dd-b138-773343a97414', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What factors are typically scanned in environmental scanning?', 'Priority: Tier 2 | PYQ Connection: Provides the "components/factors" depth needed if environmental scanning is asked as a standalone or combined question with SWOT.', 'Commonly scanned factors include: Economic (interest rates, inflation, income levels, market demand), Political/Legal (government policy, regulation, taxation), Social/Cultural (demographic shifts, consumer attitudes and lifestyle trends), Technological (emerging technologies, automation, digital trends), and Competitive/Industry factors (competitor moves, new entrants, industry growth rate). These external factors are then weighed against the venture''s internal resources — which is where environmental scanning feeds directly into SWOT analysis.', NULL, NULL, NULL, 11, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', 'd1345909-2234-4a4e-a7fc-c98d97d29da1', '{"blocks":[{"id":"bpem-u3-c11-q-1","text":"What factors are typically scanned in environmental scanning?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c11-a-1","text":"Commonly scanned factors include: Economic (interest rates, inflation, income levels, market demand), Political/Legal (government policy, regulation, taxation), Social/Cultural (demographic shifts, consumer attitudes and lifestyle trends), Technological (emerging technologies, automation, digital trends), and Competitive/Industry factors (competitor moves, new entrants, industry growth rate). These external factors are then weighed against the venture''s internal resources — which is where environmental scanning feeds directly into SWOT analysis.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('6638d162-504c-4187-a9a2-ecfa6ceacdeb', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What is SWOT Analysis? What does the acronym stand for?', 'Priority: Tier 1 | PYQ Connection: 2025 Q3.3 — "What is SWOT analysis?" (direct match, 15 marks).', 'SWOT Analysis is a strategic planning tool used to evaluate a business venture (or business idea) by systematically examining four factors: Strengths, Weaknesses, Opportunities, and Threats. Strengths and Weaknesses are internal factors — within the entrepreneur''s/organisation''s control. Opportunities and Threats are external factors — arising from the environment, largely outside the organisation''s direct control.', NULL, NULL, NULL, 12, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', '84e4c04c-6366-4f87-ac95-dd115c7db378', '{"blocks":[{"id":"bpem-u3-c12-q-1","text":"What is SWOT Analysis? What does the acronym stand for?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c12-a-1","text":"SWOT Analysis is a strategic planning tool used to evaluate a business venture (or business idea) by systematically examining four factors: Strengths, Weaknesses, Opportunities, and Threats. Strengths and Weaknesses are internal factors — within the entrepreneur''s/organisation''s control. Opportunities and Threats are external factors — arising from the environment, largely outside the organisation''s direct control.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('3f0198d2-49ae-477c-bdc6-bda8f0f8dc67', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Explain each element of SWOT with reference to a business venture.', 'Priority: Tier 1 | PYQ Connection: 2025 Q3.3 — core content for "explain how it helps entrepreneurs evaluate business strategies with suitable examples."', 'Strengths (internal, positive): resources or capabilities that give the venture an advantage — e.g., a unique recipe/formula, strong brand, skilled team, proprietary technology, low-cost production.
Weaknesses (internal, negative): internal limitations that put the venture at a disadvantage — e.g., limited capital, lack of experience, poor location, weak distribution network.
Opportunities (external, positive): favourable external conditions the venture could exploit — e.g., a growing market segment, favourable government policy, an emerging technology, or a gap left by competitors.
Threats (external, negative): external conditions that could harm the venture — e.g., new/aggressive competitors, changing regulations, economic downturn, changing consumer preferences.', NULL, NULL, NULL, 13, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', '84e4c04c-6366-4f87-ac95-dd115c7db378', '{"blocks":[{"id":"bpem-u3-c13-q-1","text":"Explain each element of SWOT with reference to a business venture.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c13-a-1","type":"bulletList","items":["Strengths (internal, positive): resources or capabilities that give the venture an advantage — e.g., a unique recipe/formula, strong brand, skilled team, proprietary technology, low-cost production.","Weaknesses (internal, negative): internal limitations that put the venture at a disadvantage — e.g., limited capital, lack of experience, poor location, weak distribution network.","Opportunities (external, positive): favourable external conditions the venture could exploit — e.g., a growing market segment, favourable government policy, an emerging technology, or a gap left by competitors.","Threats (external, negative): external conditions that could harm the venture — e.g., new/aggressive competitors, changing regulations, economic downturn, changing consumer preferences."]}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('9ec18759-a227-4f99-9fd3-518e3c7e8095', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'How does SWOT Analysis help entrepreneurs evaluate business strategies?', 'Priority: Tier 1 | PYQ Connection: 2025 Q3.3 — direct match.', 'SWOT helps entrepreneurs: build strategies that leverage strengths to exploit opportunities (e.g., using a strong brand to enter a growing market); design plans to overcome weaknesses that could prevent capturing an opportunity (e.g., raising additional capital before scaling); prepare contingency plans for external threats (e.g., diversifying suppliers to guard against a single-supplier risk); and make more realistic, evidence-based go/no-go decisions on a business idea before committing significant resources. In short, it aligns internal capability with external reality, which is the essence of sound strategic decision-making.', NULL, NULL, NULL, 14, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', '84e4c04c-6366-4f87-ac95-dd115c7db378', '{"blocks":[{"id":"bpem-u3-c14-q-1","text":"How does SWOT Analysis help entrepreneurs evaluate business strategies?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c14-a-1","text":"SWOT helps entrepreneurs: build strategies that leverage strengths to exploit opportunities (e.g., using a strong brand to enter a growing market); design plans to overcome weaknesses that could prevent capturing an opportunity (e.g., raising additional capital before scaling); prepare contingency plans for external threats (e.g., diversifying suppliers to guard against a single-supplier risk); and make more realistic, evidence-based go/no-go decisions on a business idea before committing significant resources. In short, it aligns internal capability with external reality, which is the essence of sound strategic decision-making.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('2fded819-2102-49ec-a251-45abaad82eea', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Apply SWOT Analysis to a hypothetical small bakery start-up.', 'Priority: Tier 2 | PYQ Connection: Application-style extension of the SWOT theme (2025 Q3.3), preparing the student for a "suitable example" requirement.', 'Strength: unique, closely-guarded recipes and strong local reputation for quality.
Weakness: limited working capital restricting expansion and marketing spend.
Opportunity: rising consumer demand for healthier/artisanal baked goods in the area.
Threat: entry of large organised bakery chains with greater marketing budgets and economies of scale.

Strategic implication: the bakery should leverage its recipe strength and reputation (Strength) to capture the healthy/artisanal demand trend (Opportunity), while seeking small-scale financing to address its capital weakness before large chains (Threat) can dominate the local market.', NULL, NULL, NULL, 15, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', '84e4c04c-6366-4f87-ac95-dd115c7db378', '{"blocks":[{"id":"bpem-u3-c15-q-1","text":"Apply SWOT Analysis to a hypothetical small bakery start-up.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c15-a-1","type":"bulletList","items":["Strength: unique, closely-guarded recipes and strong local reputation for quality.","Weakness: limited working capital restricting expansion and marketing spend.","Opportunity: rising consumer demand for healthier/artisanal baked goods in the area.","Threat: entry of large organised bakery chains with greater marketing budgets and economies of scale."]},{"id":"bpem-u3-c15-a-2","text":"Strategic implication: the bakery should leverage its recipe strength and reputation (Strength) to capture the healthy/artisanal demand trend (Opportunity), while seeking small-scale financing to address its capital weakness before large chains (Threat) can dominate the local market.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('40cc3d35-11db-4f84-aafc-0b1f98f44e1c', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Explain the relationship between the phases of the Entrepreneurship Development Cycle.', 'Priority: Tier 2 | PYQ Connection: Depth-add to 2024 Q3Q, useful if the examiner asks for phase inter-relationship rather than a plain listing.', 'The three phases are sequential and interdependent: the Stimulation phase creates the pool of motivated potential entrepreneurs; without it, the Support phase has no one to assist. The Support phase converts motivation into an actual functioning enterprise by resolving practical start-up barriers (finance, registration, infrastructure); without it, motivated individuals may fail to actually launch. The Sustenance phase ensures the newly launched enterprise does not merely start but survives and grows; without it, many ventures started in the Support phase would fail early due to lack of continued guidance. Together, the three phases form a complete pipeline from "potential entrepreneur" to "sustainable enterprise."', NULL, NULL, NULL, 17, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', '6ac261c7-7c05-493b-b931-bf7a09340ef7', '{"blocks":[{"id":"bpem-u3-c17-q-1","text":"Explain the relationship between the phases of the Entrepreneurship Development Cycle.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c17-a-1","text":"The three phases are sequential and interdependent: the Stimulation phase creates the pool of motivated potential entrepreneurs; without it, the Support phase has no one to assist. The Support phase converts motivation into an actual functioning enterprise by resolving practical start-up barriers (finance, registration, infrastructure); without it, motivated individuals may fail to actually launch. The Sustenance phase ensures the newly launched enterprise does not merely start but survives and grows; without it, many ventures started in the Support phase would fail early due to lack of continued guidance. Together, the three phases form a complete pipeline from \"potential entrepreneur\" to \"sustainable enterprise.\"","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('577e1945-3052-4576-bf55-0cccfb78eb49', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Why is the Entrepreneurship Development Cycle important?', 'Priority: Tier 2 | PYQ Connection: Supporting depth for 2024 Q3Q.', 'It provides a structured framework that increases the success rate of new enterprises by ensuring entrepreneurs are not left to figure out every stage alone — it systematically builds motivation, then capability, then post-launch resilience. This reduces the high failure rate typically seen among first-generation entrepreneurs and creates a more supportive overall entrepreneurial ecosystem in the economy.', NULL, NULL, NULL, 18, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', '6ac261c7-7c05-493b-b931-bf7a09340ef7', '{"blocks":[{"id":"bpem-u3-c18-q-1","text":"Why is the Entrepreneurship Development Cycle important?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c18-a-1","text":"It provides a structured framework that increases the success rate of new enterprises by ensuring entrepreneurs are not left to figure out every stage alone — it systematically builds motivation, then capability, then post-launch resilience. This reduces the high failure rate typically seen among first-generation entrepreneurs and creates a more supportive overall entrepreneurial ecosystem in the economy.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('6489c54e-cc41-41ca-a2f7-524c7208ab0c', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What is Business Planning? Explain its process.', 'Priority: Tier 1 | PYQ Connection: 2025 Q3.2 — "What is business planning? Discuss its scope and importance" (direct match, 15 marks).', 'Business planning is the systematic process of translating a business idea into a structured, actionable document (the business plan) that defines the venture''s objectives, strategies, and the resources needed to achieve them. The typical process follows these steps: (1) idea generation and screening; (2) environmental scanning and SWOT analysis to assess opportunity and internal readiness; (3) feasibility analysis (technical, market, financial, organisational); (4) setting clear business objectives; (5) developing detailed functional plans — marketing, operations, and finance; (6) compiling the complete business plan document; and (7) implementation, followed by ongoing monitoring and review against the plan.', NULL, NULL, NULL, 19, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', '0169795b-2d24-4b33-a049-de63000db961', '{"blocks":[{"id":"bpem-u3-c19-q-1","text":"What is Business Planning? Explain its process.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c19-a-1","text":"Business planning is the systematic process of translating a business idea into a structured, actionable document (the business plan) that defines the venture''s objectives, strategies, and the resources needed to achieve them. The typical process follows these steps: (1) idea generation and screening; (2) environmental scanning and SWOT analysis to assess opportunity and internal readiness; (3) feasibility analysis (technical, market, financial, organisational); (4) setting clear business objectives; (5) developing detailed functional plans — marketing, operations, and finance; (6) compiling the complete business plan document; and (7) implementation, followed by ongoing monitoring and review against the plan.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('9f5c7a72-22c8-4696-b57c-7a163d45529b', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Discuss the scope and importance of business planning.', 'Priority: Tier 1 | PYQ Connection: 2025 Q3.2 — direct match ("scope and importance").', 'The scope of business planning covers every functional area of the proposed venture — marketing, operations/production, human resources, finance, and legal/regulatory compliance — ensuring no critical area is overlooked before launch. Its importance/value lies in: acting as a clear roadmap for execution; helping secure funding, since banks and investors require a credible business plan before committing capital; forcing the entrepreneur to think through risks and assumptions before committing real resources; setting measurable objectives that later serve as a benchmark for evaluating actual performance; and improving internal coordination by giving every functional area (marketing, finance, operations) a shared, consistent set of goals.', NULL, NULL, NULL, 20, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', '0169795b-2d24-4b33-a049-de63000db961', '{"blocks":[{"id":"bpem-u3-c20-q-1","text":"Discuss the scope and importance of business planning.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c20-a-1","text":"The scope of business planning covers every functional area of the proposed venture — marketing, operations/production, human resources, finance, and legal/regulatory compliance — ensuring no critical area is overlooked before launch. Its importance/value lies in: acting as a clear roadmap for execution; helping secure funding, since banks and investors require a credible business plan before committing capital; forcing the entrepreneur to think through risks and assumptions before committing real resources; setting measurable objectives that later serve as a benchmark for evaluating actual performance; and improving internal coordination by giving every functional area (marketing, finance, operations) a shared, consistent set of goals.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('712ce9b2-e1c1-4f1d-bc19-ce0f1f971835', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'List and explain the important components of a business plan.', 'Priority: Tier 1 | PYQ Connection: 2024 Q3P — "list down the important components of a business plan" (direct match, 10 marks).', 'Executive Summary — a concise overview of the entire plan, highlighting the business concept, objectives and key financial highlights.
Business Description/Objectives — what the business does, its mission, and its specific, measurable objectives.
Market Analysis — study of target market size, customer segments, demand trends, and competitor landscape.
Organisation & Management Structure — ownership structure, management team, and key roles/responsibilities.
Product/Service Description — details of what is being offered and its unique value proposition.
Marketing & Sales Strategy — the 4Ps (product, price, place, promotion), sales channels, and customer acquisition approach.
Feasibility/Operational Plan — production process, location, technology, supply chain, and day-to-day operations.
Financial Plan — start-up cost estimates, sources of funding, projected profit & loss, cash flow, and break-even analysis.
Appendices/Supporting Documents — licences, resumes of key team members, or any supporting research.', NULL, NULL, NULL, 21, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', '0169795b-2d24-4b33-a049-de63000db961', '{"blocks":[{"id":"bpem-u3-c21-q-1","text":"List and explain the important components of a business plan.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c21-a-1","type":"numberList","items":["Executive Summary — a concise overview of the entire plan, highlighting the business concept, objectives and key financial highlights.","Business Description/Objectives — what the business does, its mission, and its specific, measurable objectives.","Market Analysis — study of target market size, customer segments, demand trends, and competitor landscape.","Organisation & Management Structure — ownership structure, management team, and key roles/responsibilities.","Product/Service Description — details of what is being offered and its unique value proposition.","Marketing & Sales Strategy — the 4Ps (product, price, place, promotion), sales channels, and customer acquisition approach.","Feasibility/Operational Plan — production process, location, technology, supply chain, and day-to-day operations.","Financial Plan — start-up cost estimates, sources of funding, projected profit & loss, cash flow, and break-even analysis.","Appendices/Supporting Documents — licences, resumes of key team members, or any supporting research."]}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('c8999306-b710-4b8a-8036-e72a642a5e98', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Scenario — A friend wants to start a small organic snacks business but only has a rough idea and no clear plan. Walk through how they should proceed using the concepts in this unit.', 'Priority: Tier 3 | PYQ Connection: Synthesis question combining idea generation, SWOT, feasibility, and business planning — all recurring PYQ themes — into one applied scenario; a strong candidate for a long-answer/case-style question.', 'Idea generation/refinement: validate the raw idea using techniques like market research or a focus group to confirm real demand for organic snacks in the target area.
Environmental scanning: check relevant technological (e.g., packaging/preservation tech), regulatory (FSSAI food licensing), and social trends (rising health consciousness) that affect this idea.
SWOT analysis: e.g., Strength — unique recipe; Weakness — no prior food-business experience; Opportunity — growing health-food trend; Threat — established snack brands entering the "healthy" category.
Feasibility analysis: confirm technical feasibility (can the product be consistently produced/scaled), market feasibility (is demand large enough), and financial feasibility (will margins support the business).
Business plan preparation: compile objectives, market analysis, marketing (4Ps) and financial projections into a formal business plan, following the Entrepreneurship Development Cycle''s Support phase to access finance and complete registration.
Launch and Sustenance: begin operations, then use ongoing marketing assistance and feedback to grow — matching the EDC''s Sustenance phase.

This shows how the unit''s tools work together in sequence rather than as isolated, unconnected concepts.', NULL, NULL, NULL, 27, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', '73156a45-cefb-4e83-aede-78267618b669', '{"blocks":[{"id":"bpem-u3-c27-q-1","text":"Scenario — A friend wants to start a small organic snacks business but only has a rough idea and no clear plan. Walk through how they should proceed using the concepts in this unit.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c27-a-1","type":"numberList","items":["Idea generation/refinement: validate the raw idea using techniques like market research or a focus group to confirm real demand for organic snacks in the target area.","Environmental scanning: check relevant technological (e.g., packaging/preservation tech), regulatory (FSSAI food licensing), and social trends (rising health consciousness) that affect this idea.","SWOT analysis: e.g., Strength — unique recipe; Weakness — no prior food-business experience; Opportunity — growing health-food trend; Threat — established snack brands entering the \"healthy\" category.","Feasibility analysis: confirm technical feasibility (can the product be consistently produced/scaled), market feasibility (is demand large enough), and financial feasibility (will margins support the business).","Business plan preparation: compile objectives, market analysis, marketing (4Ps) and financial projections into a formal business plan, following the Entrepreneurship Development Cycle''s Support phase to access finance and complete registration.","Launch and Sustenance: begin operations, then use ongoing marketing assistance and feedback to grow — matching the EDC''s Sustenance phase."]},{"id":"bpem-u3-c27-a-2","text":"This shows how the unit''s tools work together in sequence rather than as isolated, unconnected concepts.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('32f66df8-3c79-4319-9445-0aa6413a600b', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What is the role of objectives in a business plan?', 'Priority: Tier 2 | PYQ Connection: Embedded sub-element of the "components of a business plan" theme (2024 Q3P).', 'Objectives clearly state what the venture aims to achieve — in terms of sales, market share, profitability, or growth — within a defined timeframe. They give direction to every functional plan within the business plan (marketing, operations, finance), and serve as a concrete benchmark against which actual performance can later be measured, helping the entrepreneur identify and correct deviations early.', NULL, NULL, NULL, 22, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', '0169795b-2d24-4b33-a049-de63000db961', '{"blocks":[{"id":"bpem-u3-c22-q-1","text":"What is the role of objectives in a business plan?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c22-a-1","text":"Objectives clearly state what the venture aims to achieve — in terms of sales, market share, profitability, or growth — within a defined timeframe. They give direction to every functional plan within the business plan (marketing, operations, finance), and serve as a concrete benchmark against which actual performance can later be measured, helping the entrepreneur identify and correct deviations early.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('1c980680-2330-4c0c-9250-ed4c409b02d0', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Explain the purpose and key considerations of market analysis in a business plan.', 'Priority: Tier 2 | PYQ Connection: Embedded sub-element of "components of a business plan" (2024 Q3P) and closely tied to feasibility analysis.', 'Market analysis assesses whether genuine, sufficient demand exists for the proposed product/service. Key considerations include: target market size and growth rate, customer segmentation and buying behaviour, competitor analysis (who else serves this market and how), demand estimation, and pricing benchmarks. It provides the evidence base that justifies the venture''s marketing and sales strategy, and reassures investors/lenders that the business idea addresses a real market need.', NULL, NULL, NULL, 23, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', '0169795b-2d24-4b33-a049-de63000db961', '{"blocks":[{"id":"bpem-u3-c23-q-1","text":"Explain the purpose and key considerations of market analysis in a business plan.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c23-a-1","text":"Market analysis assesses whether genuine, sufficient demand exists for the proposed product/service. Key considerations include: target market size and growth rate, customer segmentation and buying behaviour, competitor analysis (who else serves this market and how), demand estimation, and pricing benchmarks. It provides the evidence base that justifies the venture''s marketing and sales strategy, and reassures investors/lenders that the business idea addresses a real market need.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('81d06585-8f0a-47e9-add0-a45649cca96e', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What is feasibility analysis? Why is it important before finalising a business plan?', 'Priority: Tier 2 | PYQ Connection: Embedded sub-element of the business planning process (2025 Q3.2) and directly linked to the idea-to-opportunity theme tested in both papers.', 'Feasibility analysis is the assessment of whether a proposed business idea is realistically viable before significant resources are committed. It typically examines four dimensions: Technical feasibility (can the product/service actually be produced with available technology/resources?), Market feasibility (is there sufficient real demand?), Financial feasibility (will the venture be profitable and fundable?), and Organisational feasibility (can the venture be managed effectively with available skills/team?). It is important because it filters out unviable ideas early, before the entrepreneur invests significant time, money and effort into a full business plan and launch.', NULL, NULL, NULL, 24, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', '0169795b-2d24-4b33-a049-de63000db961', '{"blocks":[{"id":"bpem-u3-c24-q-1","text":"What is feasibility analysis? Why is it important before finalising a business plan?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c24-a-1","text":"Feasibility analysis is the assessment of whether a proposed business idea is realistically viable before significant resources are committed. It typically examines four dimensions: Technical feasibility (can the product/service actually be produced with available technology/resources?), Market feasibility (is there sufficient real demand?), Financial feasibility (will the venture be profitable and fundable?), and Organisational feasibility (can the venture be managed effectively with available skills/team?). It is important because it filters out unviable ideas early, before the entrepreneur invests significant time, money and effort into a full business plan and launch.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('bf04ecb8-6d7e-4d4b-93d2-41673381e4a1', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Explain the marketing component of a business plan.', 'Priority: Tier 2 | PYQ Connection: Embedded sub-element of "components of a business plan" (2024 Q3P).', 'The marketing section defines how the venture will reach and sell to its target customers, typically structured around the 4Ps: Product (features, positioning, unique value proposition), Price (pricing strategy relative to competitors and customer willingness to pay), Place (distribution channels — direct, retail, online), and Promotion (advertising, digital marketing, sales promotion strategy). It also includes realistic sales projections tied to the market analysis findings.', NULL, NULL, NULL, 25, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', '0169795b-2d24-4b33-a049-de63000db961', '{"blocks":[{"id":"bpem-u3-c25-q-1","text":"Explain the marketing component of a business plan.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c25-a-1","text":"The marketing section defines how the venture will reach and sell to its target customers, typically structured around the 4Ps: Product (features, positioning, unique value proposition), Price (pricing strategy relative to competitors and customer willingness to pay), Place (distribution channels — direct, retail, online), and Promotion (advertising, digital marketing, sales promotion strategy). It also includes realistic sales projections tied to the market analysis findings.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('ebc9b99b-207d-46a1-840e-ec66c6591685', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Explain the financial component of a business plan.', 'Priority: Tier 2 | PYQ Connection: Embedded sub-element of "components of a business plan" (2024 Q3P) and central to demonstrating the "value" of a business plan (2025 Q3.2).', 'The financial section quantifies the venture''s viability and funding needs. It typically includes: start-up cost estimation (capital required to launch); sources of funds (owner''s capital, bank loans, investors, government schemes); projected Profit & Loss statement (expected revenue and expenses over a defined period); cash flow projections (to ensure the venture can meet short-term obligations); and break-even analysis (the sales level at which the venture starts covering all costs). This section is what most directly determines whether banks/investors will fund the venture.', NULL, NULL, NULL, 26, true, 'University Exam', NULL, NULL, NULL, '92d1a467-5d61-4c6a-9709-89d075678621', '0169795b-2d24-4b33-a049-de63000db961', '{"blocks":[{"id":"bpem-u3-c26-q-1","text":"Explain the financial component of a business plan.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u3-c26-a-1","text":"The financial section quantifies the venture''s viability and funding needs. It typically includes: start-up cost estimation (capital required to launch); sources of funds (owner''s capital, bank loans, investors, government schemes); projected Profit & Loss statement (expected revenue and expenses over a defined period); cash flow projections (to ensure the venture can meet short-term obligations); and break-even analysis (the sales level at which the venture starts covering all costs). This section is what most directly determines whether banks/investors will fund the venture.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:43.485045+00', '2026-09-21 02:33:43.485045+00'),
  ('b2a1fd58-afb6-4f23-94bb-ecc4843f6150', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Elaborate the legal requirements for starting a business in India.', 'Priority: Tier 1 | PYQ Connection: 2024 Q4A — "elaborate the legal requirement of starting a business in India" (direct match, 8 marks).', 'Setting up a business in India typically involves the following legal/regulatory steps:

Choice of business structure — deciding the legal form: sole proprietorship, partnership (under the Indian Partnership Act), Limited Liability Partnership (LLP), or private/public limited company (under the Companies Act, 2013). This choice determines the subsequent registration route.
Business registration — registering the chosen entity with the appropriate authority (e.g., Registrar of Companies for a company/LLP, local registration for partnership/proprietorship).
PAN and TAN — obtaining a Permanent Account Number and Tax Deduction/Collection Account Number for tax purposes.
GST registration — mandatory once turnover crosses the prescribed threshold, or voluntarily for input tax credit and inter-state trade.
MSME/Udyam registration — registering as a Micro, Small or Medium Enterprise to access related government benefits and schemes.
Shop and Establishment Act registration — required for most commercial establishments under state-level Shops and Establishments legislation.
Industry/sector-specific licences — such as an FSSAI licence for food businesses, a drug licence for pharmaceuticals, or an Import Export Code (IEC) for import/export activity.
Bank account opening in the business''s name for financial transactions.
Labour law compliance, where applicable (Provident Fund, ESI registration) once the enterprise crosses prescribed employee thresholds.

Legal compliance is important because it gives the business a recognised legal identity, limits/defines owner liability depending on the structure chosen, enables access to formal credit and government schemes, and protects the business from penalties for non-compliance.', NULL, NULL, NULL, 1, true, 'University Exam', NULL, NULL, NULL, '1b61adb6-3e84-4c29-9d69-9a4aae1bbd2e', '5b81af19-2f29-4811-b541-c0df4d980601', '{"blocks":[{"id":"bpem-u4-c1-q-1","text":"Elaborate the legal requirements for starting a business in India.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u4-c1-a-1","text":"Setting up a business in India typically involves the following legal/regulatory steps:","type":"text","style":"paragraph"},{"id":"bpem-u4-c1-a-2","type":"numberList","items":["Choice of business structure — deciding the legal form: sole proprietorship, partnership (under the Indian Partnership Act), Limited Liability Partnership (LLP), or private/public limited company (under the Companies Act, 2013). This choice determines the subsequent registration route.","Business registration — registering the chosen entity with the appropriate authority (e.g., Registrar of Companies for a company/LLP, local registration for partnership/proprietorship).","PAN and TAN — obtaining a Permanent Account Number and Tax Deduction/Collection Account Number for tax purposes.","GST registration — mandatory once turnover crosses the prescribed threshold, or voluntarily for input tax credit and inter-state trade.","MSME/Udyam registration — registering as a Micro, Small or Medium Enterprise to access related government benefits and schemes.","Shop and Establishment Act registration — required for most commercial establishments under state-level Shops and Establishments legislation.","Industry/sector-specific licences — such as an FSSAI licence for food businesses, a drug licence for pharmaceuticals, or an Import Export Code (IEC) for import/export activity.","Bank account opening in the business''s name for financial transactions.","Labour law compliance, where applicable (Provident Fund, ESI registration) once the enterprise crosses prescribed employee thresholds."]},{"id":"bpem-u4-c1-a-3","text":"Legal compliance is important because it gives the business a recognised legal identity, limits/defines owner liability depending on the structure chosen, enables access to formal credit and government schemes, and protects the business from penalties for non-compliance.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:46.113608+00', '2026-09-21 02:33:46.113608+00'),
  ('b9bb1288-0f7b-494d-a041-68c3df89edaf', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Why is legal compliance important for a new venture?', 'Priority: Tier 2 | PYQ Connection: Supporting depth for 2024 Q4A.', 'It gives the enterprise formal legal recognition and standing to enter contracts; it defines and (depending on structure) limits the owner''s personal liability; it is a precondition for opening business bank accounts and accessing institutional finance; it enables eligibility for government schemes and MSME benefits; and it protects the business from fines, penalties or forced closure due to non-compliance.', NULL, NULL, NULL, 2, true, 'University Exam', NULL, NULL, NULL, '1b61adb6-3e84-4c29-9d69-9a4aae1bbd2e', '5b81af19-2f29-4811-b541-c0df4d980601', '{"blocks":[{"id":"bpem-u4-c2-q-1","text":"Why is legal compliance important for a new venture?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u4-c2-a-1","text":"It gives the enterprise formal legal recognition and standing to enter contracts; it defines and (depending on structure) limits the owner''s personal liability; it is a precondition for opening business bank accounts and accessing institutional finance; it enables eligibility for government schemes and MSME benefits; and it protects the business from fines, penalties or forced closure due to non-compliance.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:46.113608+00', '2026-09-21 02:33:46.113608+00'),
  ('7fa006a2-0394-4c02-b7b3-6fbb4a51ee25', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Explain the key steps involved in starting a business venture in India.', 'Priority: Tier 1 | PYQ Connection: 2025 Q4.1 — "key steps involved in starting a business venture in India" (direct match, 15 marks).', 'Idea generation and opportunity identification — identifying a viable business idea (see Unit 3).
Feasibility and SWOT analysis — validating technical, market and financial viability before committing resources.
Choice of legal structure — selecting proprietorship, partnership, LLP or company based on liability, scale and funding needs.
Business plan preparation — documenting objectives, market analysis, operations and financial projections (see Unit 3).
Arranging capital/finance — securing fixed and working capital from appropriate sources (Section D).
Legal registration and compliance — completing all registrations covered in Section A (PAN, GST, MSME, licences, etc.).
Location and infrastructure setup — securing premises, machinery, utilities and technology needed for operations.
Procurement and staffing — sourcing raw materials/inventory and recruiting the initial team.
Launch of operations — commencing production/service delivery.
Marketing and sales roll-out — executing the marketing plan to acquire the first customers.
Monitoring and growth — tracking performance against the business plan and adjusting strategy for sustainable growth.

Each step builds on the previous one — for instance, the business plan (step 4) cannot be finalised without feasibility analysis (step 2), and registration (step 6) is typically required before formal finance can be secured (step 5) in the case of institutional lenders.', NULL, NULL, NULL, 3, true, 'University Exam', NULL, NULL, NULL, '1b61adb6-3e84-4c29-9d69-9a4aae1bbd2e', '94351aa8-881a-4723-af18-00c485a4277d', '{"blocks":[{"id":"bpem-u4-c3-q-1","text":"Explain the key steps involved in starting a business venture in India.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u4-c3-a-1","type":"numberList","items":["Idea generation and opportunity identification — identifying a viable business idea (see Unit 3).","Feasibility and SWOT analysis — validating technical, market and financial viability before committing resources.","Choice of legal structure — selecting proprietorship, partnership, LLP or company based on liability, scale and funding needs.","Business plan preparation — documenting objectives, market analysis, operations and financial projections (see Unit 3).","Arranging capital/finance — securing fixed and working capital from appropriate sources (Section D).","Legal registration and compliance — completing all registrations covered in Section A (PAN, GST, MSME, licences, etc.).","Location and infrastructure setup — securing premises, machinery, utilities and technology needed for operations.","Procurement and staffing — sourcing raw materials/inventory and recruiting the initial team.","Launch of operations — commencing production/service delivery.","Marketing and sales roll-out — executing the marketing plan to acquire the first customers.","Monitoring and growth — tracking performance against the business plan and adjusting strategy for sustainable growth."]},{"id":"bpem-u4-c3-a-2","text":"Each step builds on the previous one — for instance, the business plan (step 4) cannot be finalised without feasibility analysis (step 2), and registration (step 6) is typically required before formal finance can be secured (step 5) in the case of institutional lenders.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:46.113608+00', '2026-09-21 02:33:46.113608+00'),
  ('4ad23a75-d0e6-426e-bf0d-850f88a9cb83', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What is meant by institutional support to entrepreneurs? Why is it important?', 'Priority: Tier 2 | PYQ Connection: Not directly tested in the supplied papers, but a core syllabus topic and a natural companion to the "sources of finance" question (2024 Q4B).', 'Institutional support refers to the assistance — financial, technical, managerial, or promotional — provided to entrepreneurs by government and quasi-government bodies to help them start, run and grow their enterprises. It is important because new entrepreneurs, especially first-generation ones, often lack access to capital, technical know-how, or market linkages on their own; institutional support fills these gaps and improves the survival and growth rate of new ventures.', NULL, NULL, NULL, 4, true, 'University Exam', NULL, NULL, NULL, '1b61adb6-3e84-4c29-9d69-9a4aae1bbd2e', '5c3e1293-d7af-4b18-8199-8878593f9b10', '{"blocks":[{"id":"bpem-u4-c4-q-1","text":"What is meant by institutional support to entrepreneurs? Why is it important?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u4-c4-a-1","text":"Institutional support refers to the assistance — financial, technical, managerial, or promotional — provided to entrepreneurs by government and quasi-government bodies to help them start, run and grow their enterprises. It is important because new entrepreneurs, especially first-generation ones, often lack access to capital, technical know-how, or market linkages on their own; institutional support fills these gaps and improves the survival and growth rate of new ventures.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:46.113608+00', '2026-09-21 02:33:46.113608+00'),
  ('c1780d2f-84c4-4cf0-b477-48865cfe5874', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What types of institutional support are available to entrepreneurs in India?', 'Priority: Tier 2 | PYQ Connection: Core syllabus topic; complements "sources of finance" (2024 Q4B) if the examiner asks for institutional rather than general sources.', 'Broadly, institutional support falls into these categories:

Financial support institutions — e.g., SIDBI (Small Industries Development Bank of India), commercial banks, and State Financial Corporations (SFCs), which provide loans and credit facilities to small and medium enterprises.
Promotional/developmental institutions — e.g., District Industries Centres (DICs), which act as single-window agencies at the district level for registration, guidance and scheme information; NSIC (National Small Industries Corporation), which supports marketing, technology and raw-material assistance for small enterprises; and KVIC (Khadi and Village Industries Commission), which promotes khadi and village-level industries.
Training and development institutions — e.g., EDII (Entrepreneurship Development Institute of India), which conducts EDPs and entrepreneurship training programmes.
State-level industrial development agencies (SIDCs), which support industrial infrastructure and project financing at the state level.

Together, these institutions provide the finance, guidance, training and market linkages that help convert a business plan into a functioning, sustainable enterprise.', NULL, NULL, NULL, 5, true, 'University Exam', NULL, NULL, NULL, '1b61adb6-3e84-4c29-9d69-9a4aae1bbd2e', '5c3e1293-d7af-4b18-8199-8878593f9b10', '{"blocks":[{"id":"bpem-u4-c5-q-1","text":"What types of institutional support are available to entrepreneurs in India?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u4-c5-a-1","text":"Broadly, institutional support falls into these categories:","type":"text","style":"paragraph"},{"id":"bpem-u4-c5-a-2","type":"bulletList","items":["Financial support institutions — e.g., SIDBI (Small Industries Development Bank of India), commercial banks, and State Financial Corporations (SFCs), which provide loans and credit facilities to small and medium enterprises.","Promotional/developmental institutions — e.g., District Industries Centres (DICs), which act as single-window agencies at the district level for registration, guidance and scheme information; NSIC (National Small Industries Corporation), which supports marketing, technology and raw-material assistance for small enterprises; and KVIC (Khadi and Village Industries Commission), which promotes khadi and village-level industries.","Training and development institutions — e.g., EDII (Entrepreneurship Development Institute of India), which conducts EDPs and entrepreneurship training programmes.","State-level industrial development agencies (SIDCs), which support industrial infrastructure and project financing at the state level."]},{"id":"bpem-u4-c5-a-3","text":"Together, these institutions provide the finance, guidance, training and market linkages that help convert a business plan into a functioning, sustainable enterprise.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:46.113608+00', '2026-09-21 02:33:46.113608+00'),
  ('dcada49c-2eba-4565-9b0d-8f8669fa570d', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What is meant by "Venture Funding"? Why is it critical to a new business?', 'Priority: Tier 2 | PYQ Connection: Conceptual base for 2024 Q4B (sources of funds) and Q4Q (types of capital).', 'Venture funding refers to the process of raising the capital required to start, operate and grow a business enterprise. It is critical because virtually every stage of a venture — acquiring assets, running daily operations, marketing, and scaling — requires money, and inadequate or poorly-planned funding is one of the most common reasons new ventures fail even when the underlying business idea is sound.', NULL, NULL, NULL, 6, true, 'University Exam', NULL, NULL, NULL, '1b61adb6-3e84-4c29-9d69-9a4aae1bbd2e', '8e50e5c6-ab42-4b62-8185-78088d12d450', '{"blocks":[{"id":"bpem-u4-c6-q-1","text":"What is meant by \"Venture Funding\"? Why is it critical to a new business?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u4-c6-a-1","text":"Venture funding refers to the process of raising the capital required to start, operate and grow a business enterprise. It is critical because virtually every stage of a venture — acquiring assets, running daily operations, marketing, and scaling — requires money, and inadequate or poorly-planned funding is one of the most common reasons new ventures fail even when the underlying business idea is sound.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:46.113608+00', '2026-09-21 02:33:46.113608+00'),
  ('765c2c22-7b84-414f-bec9-8c2348681c7b', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Distinguish between Fixed Capital and Working Capital, and explain the significance of each.', 'Priority: Tier 1 | PYQ Connection: 2024 Q4Q — "elaborate different types of capital and their significance in business" (direct match, 8 marks).', 'Basis | Fixed Capital | Working Capital
Meaning | Funds invested in long-term/fixed assets used repeatedly over time | Funds required for day-to-day operational expenses
Nature | Long-term investment | Short-term, recurring/cyclical requirement
Examples | Land, buildings, plant and machinery, equipment, furniture | Raw material purchase, wages, utility bills, inventory, receivables
Liquidity | Low — assets are not easily converted to cash | High — directly tied to the operating cash cycle
Purpose | Sets up the productive capacity of the business | Keeps daily operations running smoothly

Significance: Fixed capital determines the scale and productive capacity a venture can build — insufficient fixed capital limits the business''s ability to produce at the intended scale. Working capital determines the venture''s ability to sustain day-to-day operations — insufficient working capital can cause even a profitable business to fail due to an inability to pay short-term bills, purchase inventory, or meet payroll (a cash-flow crisis). Both must be planned for separately, since a venture can be well-capitalised in fixed assets yet still collapse from a working capital shortage.', NULL, NULL, NULL, 7, true, 'University Exam', NULL, NULL, NULL, '1b61adb6-3e84-4c29-9d69-9a4aae1bbd2e', '8e50e5c6-ab42-4b62-8185-78088d12d450', '{"blocks":[{"id":"bpem-u4-c7-q-1","text":"Distinguish between Fixed Capital and Working Capital, and explain the significance of each.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u4-c7-a-1","rows":[["Basis","Fixed Capital","Working Capital"],["Meaning","Funds invested in long-term/fixed assets used repeatedly over time","Funds required for day-to-day operational expenses"],["Nature","Long-term investment","Short-term, recurring/cyclical requirement"],["Examples","Land, buildings, plant and machinery, equipment, furniture","Raw material purchase, wages, utility bills, inventory, receivables"],["Liquidity","Low — assets are not easily converted to cash","High — directly tied to the operating cash cycle"],["Purpose","Sets up the productive capacity of the business","Keeps daily operations running smoothly"]],"type":"table"},{"id":"bpem-u4-c7-a-2","text":"Significance: Fixed capital determines the scale and productive capacity a venture can build — insufficient fixed capital limits the business''s ability to produce at the intended scale. Working capital determines the venture''s ability to sustain day-to-day operations — insufficient working capital can cause even a profitable business to fail due to an inability to pay short-term bills, purchase inventory, or meet payroll (a cash-flow crisis). Both must be planned for separately, since a venture can be well-capitalised in fixed assets yet still collapse from a working capital shortage.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:46.113608+00', '2026-09-21 02:33:46.113608+00'),
  ('68b659d9-d009-4edf-88b8-409a0d01a946', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Discuss the various sources from which entrepreneurs can generate funds.', 'Priority: Tier 1 | PYQ Connection: 2024 Q4B — "discuss different sources from where entrepreneurs can generate funds" (direct match, 8 marks).', 'Owned/Internal sources: personal savings, funds from family and friends, and retained earnings (for an already-operating business) — low-cost but often limited in amount.
Borrowed/External sources: bank loans and term loans, financial institutions such as SIDBI, trade credit from suppliers, and debentures/bonds (for larger enterprises) — these expand available capital but come with repayment obligations and interest cost.
Equity sources: angel investors and venture capital firms, who provide funding in exchange for ownership stake — useful for high-growth start-ups that may not qualify for conventional loans, but involves dilution of ownership/control.
Government schemes: collateral-free credit schemes (e.g., Mudra Yojana-type schemes) and Start-Up India-linked funding support, aimed at easing access to finance for new and small entrepreneurs.
Other modern sources: crowdfunding platforms, where a large number of individuals contribute small amounts, typically used by early-stage or creative/product-based ventures.

Each source differs in cost, risk, and the degree of control the entrepreneur retains, so the right mix depends on the venture''s stage, scale, and risk appetite.', NULL, NULL, NULL, 8, true, 'University Exam', NULL, NULL, NULL, '1b61adb6-3e84-4c29-9d69-9a4aae1bbd2e', '8e50e5c6-ab42-4b62-8185-78088d12d450', '{"blocks":[{"id":"bpem-u4-c8-q-1","text":"Discuss the various sources from which entrepreneurs can generate funds.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u4-c8-a-1","type":"bulletList","items":["Owned/Internal sources: personal savings, funds from family and friends, and retained earnings (for an already-operating business) — low-cost but often limited in amount.","Borrowed/External sources: bank loans and term loans, financial institutions such as SIDBI, trade credit from suppliers, and debentures/bonds (for larger enterprises) — these expand available capital but come with repayment obligations and interest cost.","Equity sources: angel investors and venture capital firms, who provide funding in exchange for ownership stake — useful for high-growth start-ups that may not qualify for conventional loans, but involves dilution of ownership/control.","Government schemes: collateral-free credit schemes (e.g., Mudra Yojana-type schemes) and Start-Up India-linked funding support, aimed at easing access to finance for new and small entrepreneurs.","Other modern sources: crowdfunding platforms, where a large number of individuals contribute small amounts, typically used by early-stage or creative/product-based ventures."]},{"id":"bpem-u4-c8-a-2","text":"Each source differs in cost, risk, and the degree of control the entrepreneur retains, so the right mix depends on the venture''s stage, scale, and risk appetite.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:46.113608+00', '2026-09-21 02:33:46.113608+00'),
  ('567ef4cd-a4a9-4913-80d3-220e121bbc99', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What is the Make in India campaign? Explain its relevance to entrepreneurs.', 'Priority: Tier 1 | PYQ Connection: 2024 Q4P — "relevance of Start Up India, Digital India and Make in India in creating opportunities for budding entrepreneurs" (direct match, 8 marks).', 'Make in India is a national initiative aimed at encouraging both domestic and foreign companies to manufacture their products within India, with the broader objective of transforming India into a global manufacturing hub. Its objectives include increasing the manufacturing sector''s contribution to GDP, generating large-scale employment, attracting foreign direct investment (FDI), and improving India''s ease-of-doing-business ranking. For entrepreneurs, its relevance lies in: opening up opportunities across multiple identified priority sectors (such as automobiles, textiles, and electronics manufacturing); easier FDI norms in several sectors, which can attract foreign partners/investors for Indian ventures; and a broader push toward improved industrial infrastructure and simplified regulatory approval processes that benefit new manufacturing enterprises.', NULL, NULL, NULL, 9, true, 'University Exam', NULL, NULL, NULL, '1b61adb6-3e84-4c29-9d69-9a4aae1bbd2e', '575ef32f-2ea8-450b-aa3e-db20f968962b', '{"blocks":[{"id":"bpem-u4-c9-q-1","text":"What is the Make in India campaign? Explain its relevance to entrepreneurs.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u4-c9-a-1","text":"Make in India is a national initiative aimed at encouraging both domestic and foreign companies to manufacture their products within India, with the broader objective of transforming India into a global manufacturing hub. Its objectives include increasing the manufacturing sector''s contribution to GDP, generating large-scale employment, attracting foreign direct investment (FDI), and improving India''s ease-of-doing-business ranking. For entrepreneurs, its relevance lies in: opening up opportunities across multiple identified priority sectors (such as automobiles, textiles, and electronics manufacturing); easier FDI norms in several sectors, which can attract foreign partners/investors for Indian ventures; and a broader push toward improved industrial infrastructure and simplified regulatory approval processes that benefit new manufacturing enterprises.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:46.113608+00', '2026-09-21 02:33:46.113608+00'),
  ('365899b6-1d3f-4b50-9737-fe43dc1b5f44', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What is the Digital India campaign? Discuss its objectives and major initiatives.', 'Priority: Tier 1 | PYQ Connection: 2024 Q4P (bundled with Make in India/Start-Up India) and 2025 Q4.2 (standalone, 15 marks) — the only Unit 4 theme tested directly in both papers; treat as the highest-priority topic in this unit.', 'Digital India is a national campaign aimed at transforming India into a digitally empowered society and knowledge-based economy. Its core objectives are typically explained around three themes: (1) providing digital infrastructure as a core utility to every citizen (e.g., broadband connectivity); (2) enabling governance and services on demand, i.e., delivering government services electronically; and (3) achieving the digital empowerment of citizens, including digital literacy and access to digital resources. Major initiatives associated with this campaign include expansion of broadband/internet connectivity to rural areas, promotion of e-governance and electronic delivery of public services, digital identity and document infrastructure, and the wider push toward a digital payments ecosystem. For entrepreneurs, Digital India''s relevance includes: the rise of e-commerce, fintech and digital-service-based business models; easier, faster digital registration and compliance processes for new businesses; and expanded market reach through digital/online channels rather than dependence on physical infrastructure alone.', NULL, NULL, NULL, 10, true, 'University Exam', NULL, NULL, NULL, '1b61adb6-3e84-4c29-9d69-9a4aae1bbd2e', '575ef32f-2ea8-450b-aa3e-db20f968962b', '{"blocks":[{"id":"bpem-u4-c10-q-1","text":"What is the Digital India campaign? Discuss its objectives and major initiatives.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u4-c10-a-1","text":"Digital India is a national campaign aimed at transforming India into a digitally empowered society and knowledge-based economy. Its core objectives are typically explained around three themes: (1) providing digital infrastructure as a core utility to every citizen (e.g., broadband connectivity); (2) enabling governance and services on demand, i.e., delivering government services electronically; and (3) achieving the digital empowerment of citizens, including digital literacy and access to digital resources. Major initiatives associated with this campaign include expansion of broadband/internet connectivity to rural areas, promotion of e-governance and electronic delivery of public services, digital identity and document infrastructure, and the wider push toward a digital payments ecosystem. For entrepreneurs, Digital India''s relevance includes: the rise of e-commerce, fintech and digital-service-based business models; easier, faster digital registration and compliance processes for new businesses; and expanded market reach through digital/online channels rather than dependence on physical infrastructure alone.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:46.113608+00', '2026-09-21 02:33:46.113608+00'),
  ('85a66c96-b4ad-420f-a9ee-adac3fb89f98', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What opportunities exist for start-ups in India, and what role do national initiatives like Start-Up India play?', 'Priority: Tier 2 | PYQ Connection: Complements 2024 Q4P (Start-Up India named directly) and is a natural extension of the recurring government-initiative theme.', 'India''s start-up ecosystem has grown through a combination of factors: easier access to early-stage funding via angel investors, venture capital and government-backed funding support; incubators and accelerators that provide mentorship, workspace and early guidance; simplified compliance and tax-related benefits available to recognised start-ups under Start-Up India-type initiatives; fast-tracked intellectual property (patent/trademark) support to help young ventures protect innovation; and growing digital infrastructure (via Digital India) and manufacturing-friendly policy (via Make in India) that widen the range of viable business models — from digital/e-commerce ventures to manufacturing-based start-ups. Together, these create a more supportive entrepreneurial ecosystem than existed a decade earlier, though entrepreneurs must still navigate genuine challenges such as access to affordable long-term capital, regulatory compliance burden for smaller players, and intense market competition.', NULL, NULL, NULL, 11, true, 'University Exam', NULL, NULL, NULL, '1b61adb6-3e84-4c29-9d69-9a4aae1bbd2e', '575ef32f-2ea8-450b-aa3e-db20f968962b', '{"blocks":[{"id":"bpem-u4-c11-q-1","text":"What opportunities exist for start-ups in India, and what role do national initiatives like Start-Up India play?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u4-c11-a-1","text":"India''s start-up ecosystem has grown through a combination of factors: easier access to early-stage funding via angel investors, venture capital and government-backed funding support; incubators and accelerators that provide mentorship, workspace and early guidance; simplified compliance and tax-related benefits available to recognised start-ups under Start-Up India-type initiatives; fast-tracked intellectual property (patent/trademark) support to help young ventures protect innovation; and growing digital infrastructure (via Digital India) and manufacturing-friendly policy (via Make in India) that widen the range of viable business models — from digital/e-commerce ventures to manufacturing-based start-ups. Together, these create a more supportive entrepreneurial ecosystem than existed a decade earlier, though entrepreneurs must still navigate genuine challenges such as access to affordable long-term capital, regulatory compliance burden for smaller players, and intense market competition.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:46.113608+00', '2026-09-21 02:33:46.113608+00'),
  ('a82a0de0-0517-4799-bf72-24e9f8667110', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'Discuss the new trends in entrepreneurship, with suitable examples.', 'Priority: Tier 1 | PYQ Connection: 2025 Q4.3 — "new trends in entrepreneurship... with suitable examples" (direct match, 15 marks).', 'Emerging trends shaping entrepreneurship today include:

E-entrepreneurship — businesses built primarily around internet/digital platforms (covered in detail below).
Technology-driven start-ups — ventures built around emerging technology such as fintech, SaaS (software-as-a-service), and AI-enabled products/services.
Social and sustainable/green entrepreneurship — ventures that combine business viability with social or environmental impact (linking back to Unit 2''s social entrepreneurship theme).
Franchise-based growth — more entrepreneurs choosing the franchise route (Unit 2) as a faster, lower-risk way to enter business, rather than building a brand from scratch.
Rural and women entrepreneurship — growing entrepreneurial activity outside traditional urban/male-dominated business hubs, supported by SHGs and targeted government schemes (Unit 2).
Gig-economy-linked ventures — businesses built around flexible, platform-mediated work models rather than traditional full-time employment structures.

Example: A digitally-native beauty and personal-care retailer built entirely around an e-commerce platform (e.g., Nykaa) illustrates the convergence of e-entrepreneurship and technology-driven growth as a defining trend of the current entrepreneurial landscape.', NULL, NULL, NULL, 12, true, 'University Exam', NULL, NULL, NULL, '1b61adb6-3e84-4c29-9d69-9a4aae1bbd2e', '59a5ea27-d457-4588-a326-5f6b4231f0ae', '{"blocks":[{"id":"bpem-u4-c12-q-1","text":"Discuss the new trends in entrepreneurship, with suitable examples.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u4-c12-a-1","text":"Emerging trends shaping entrepreneurship today include:","type":"text","style":"paragraph"},{"id":"bpem-u4-c12-a-2","type":"bulletList","items":["E-entrepreneurship — businesses built primarily around internet/digital platforms (covered in detail below).","Technology-driven start-ups — ventures built around emerging technology such as fintech, SaaS (software-as-a-service), and AI-enabled products/services.","Social and sustainable/green entrepreneurship — ventures that combine business viability with social or environmental impact (linking back to Unit 2''s social entrepreneurship theme).","Franchise-based growth — more entrepreneurs choosing the franchise route (Unit 2) as a faster, lower-risk way to enter business, rather than building a brand from scratch.","Rural and women entrepreneurship — growing entrepreneurial activity outside traditional urban/male-dominated business hubs, supported by SHGs and targeted government schemes (Unit 2).","Gig-economy-linked ventures — businesses built around flexible, platform-mediated work models rather than traditional full-time employment structures."]},{"id":"bpem-u4-c12-a-3","text":"Example: A digitally-native beauty and personal-care retailer built entirely around an e-commerce platform (e.g., Nykaa) illustrates the convergence of e-entrepreneurship and technology-driven growth as a defining trend of the current entrepreneurial landscape.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:46.113608+00', '2026-09-21 02:33:46.113608+00'),
  ('9710920e-f30e-49dd-bc65-664ad6b28cf6', '1ba3fabc-a2c8-4c58-a388-cb07c2a4d70d', 'flashcard', 'What is an E-entrepreneur? Explain the concept, characteristics and opportunities of E-entrepreneurship.', 'Priority: Tier 1 | PYQ Connection: Explicit syllabus topic under "New Trends," and directly supports 2025 Q4.3 — an E-entrepreneurship example is one of the strongest, most syllabus-aligned examples available for that question.', 'An E-entrepreneur is an individual who conceives, establishes and manages a business primarily through the internet/digital platforms — such as e-commerce, digital services, or app-based businesses — rather than through a traditional brick-and-mortar model. Characteristics: strong reliance on digital technology and online platforms for sales/service delivery; typically lower physical infrastructure requirements compared to traditional businesses; ability to reach a wide, even global, customer base through the internet; heavy use of digital marketing and data/analytics for decision-making; and often faster scalability than a purely physical business model.

Opportunities: lower entry barriers and start-up costs (no need for large physical retail space); access to a much larger market than a purely local physical store could reach; ability to test and iterate business models quickly using online customer data; and alignment with the broader Digital India push toward a digitally-enabled economy, which continues to expand the online customer base available to e-entrepreneurs.

Example: Online marketplaces and app-based service platforms (e.g., e-commerce ventures, food-delivery platforms) represent classic E-entrepreneurship models — value is created and delivered primarily through a digital interface rather than a physical storefront.', NULL, NULL, NULL, 13, true, 'University Exam', NULL, NULL, NULL, '1b61adb6-3e84-4c29-9d69-9a4aae1bbd2e', '59a5ea27-d457-4588-a326-5f6b4231f0ae', '{"blocks":[{"id":"bpem-u4-c13-q-1","text":"What is an E-entrepreneur? Explain the concept, characteristics and opportunities of E-entrepreneurship.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"bpem-u4-c13-a-1","text":"An E-entrepreneur is an individual who conceives, establishes and manages a business primarily through the internet/digital platforms — such as e-commerce, digital services, or app-based businesses — rather than through a traditional brick-and-mortar model. Characteristics: strong reliance on digital technology and online platforms for sales/service delivery; typically lower physical infrastructure requirements compared to traditional businesses; ability to reach a wide, even global, customer base through the internet; heavy use of digital marketing and data/analytics for decision-making; and often faster scalability than a purely physical business model.","type":"text","style":"paragraph"},{"id":"bpem-u4-c13-a-2","text":"Opportunities: lower entry barriers and start-up costs (no need for large physical retail space); access to a much larger market than a purely local physical store could reach; ability to test and iterate business models quickly using online customer data; and alignment with the broader Digital India push toward a digitally-enabled economy, which continues to expand the online customer base available to e-entrepreneurs.","type":"text","style":"paragraph"},{"id":"bpem-u4-c13-a-3","text":"Example: Online marketplaces and app-based service platforms (e.g., e-commerce ventures, food-delivery platforms) represent classic E-entrepreneurship models — value is created and delivered primarily through a digital interface rather than a physical storefront.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 02:33:46.113608+00', '2026-09-21 02:33:46.113608+00'),
  ('1f6f2662-226f-402b-8b83-716ebde86349', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What is the Current Ratio?', '', 'The Current Ratio measures a company''s ability to pay short-term obligations (due within

one year) using its short-term assets. It indicates the margin of safety for creditors. Purpose: Assess short-term liquidity and working capital adequacy.', NULL, NULL, NULL, 10, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '3daef71f-b3d9-493c-8013-148426ceb854', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c10-q","text":"What is the Current Ratio?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c10-1","text":"The Current Ratio measures a company''s ability to pay short-term obligations (due within","type":"text","style":"paragraph"},{"id":"amd-u2-c10-2","text":"one year) using its short-term assets. It indicates the margin of safety for creditors. Purpose: Assess short-term liquidity and working capital adequacy.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('8adcc737-59b8-4b45-89fd-1f8abe71f640', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Define Management Accounting. Explain its meaning. (4–5 marks)', 'Priority: Tier 2 | PYQ Connection: None in supplied papers (2022, 2025); syllabus-derived. Definition-type openers are standard for Q1-type theory.', 'Meaning: Management Accounting is the process of identifying, measuring, analysing, interpreting and communicating accounting (financial and non-financial) information to management so that it can plan, control and take decisions. It reshapes data from financial accounting, cost accounting, budgets and statistics into a form managers can use.
Definitions (learn any two):
Anglo-American Council on Productivity (1950): presentation of accounting information in such a way as to assist management in the creation of policy and the day-to-day operation of an undertaking.
Robert N. Anthony: management accounting is concerned with accounting information that is useful to management.
ICMA (UK): application of professional knowledge and skill in preparing accounting information so as to assist management in formulating policies and in planning and controlling operations.
Keywords to hit: assist management · policy formulation · planning · control · decision-making · internal use.', NULL, NULL, NULL, 1, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'af42c8f2-f95c-4979-afba-54dc63cfec84', '{"blocks":[{"id":"amd-u1-c1-q-1","text":"Define Management Accounting. Explain its meaning. (4–5 marks)","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c1-1","type":"bulletList","items":["Meaning: Management Accounting is the process of identifying, measuring, analysing, interpreting and communicating accounting (financial and non-financial) information to management so that it can plan, control and take decisions. It reshapes data from financial accounting, cost accounting, budgets and statistics into a form managers can use.","Definitions (learn any two):","Anglo-American Council on Productivity (1950): presentation of accounting information in such a way as to assist management in the creation of policy and the day-to-day operation of an undertaking.","Robert N. Anthony: management accounting is concerned with accounting information that is useful to management.","ICMA (UK): application of professional knowledge and skill in preparing accounting information so as to assist management in formulating policies and in planning and controlling operations.","Keywords to hit: assist management · policy formulation · planning · control · decision-making · internal use."]}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('30525a13-ca4e-4a23-8f55-9dff0ae0f8c6', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Explain the features of Management Accounting. (7.5 marks)', 'Priority: Tier 2 | PYQ Connection: Not in supplied papers; syllabus item ("Features").', '(write 7–8 with one explanatory line each)

Decision-oriented: built to help managers choose between alternatives.
Future-oriented: uses budgets, forecasts and projections, not just past data.
For internal use: meant for management; confidential, not published.
Selective and analytical: picks only relevant information and analyses/interprets it.
Flexible, no prescribed format: not bound by Ind AS/AS or law; format tailored to the manager''s need.
Multi-source data: draws on financial accounting, cost accounting, statistics, economics.
Quantitative + qualitative, financial + non-financial information.
Timely and frequent: daily/weekly/monthly reports as needed.
Segment/responsibility focus: reports by product, department or manager rather than only the whole firm.
Supplementary, not a substitute for financial accounting; it depends on FA data.
Emphasis on control: standards, budgets and variance analysis.', NULL, NULL, NULL, 2, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'af42c8f2-f95c-4979-afba-54dc63cfec84', '{"blocks":[{"id":"amd-u1-c2-q-1","text":"Explain the features of Management Accounting. (7.5 marks)","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c2-1","text":"(write 7–8 with one explanatory line each)","type":"text","style":"paragraph"},{"id":"amd-u1-c2-2","type":"numberList","items":["Decision-oriented: built to help managers choose between alternatives.","Future-oriented: uses budgets, forecasts and projections, not just past data.","For internal use: meant for management; confidential, not published.","Selective and analytical: picks only relevant information and analyses/interprets it.","Flexible, no prescribed format: not bound by Ind AS/AS or law; format tailored to the manager''s need.","Multi-source data: draws on financial accounting, cost accounting, statistics, economics.","Quantitative + qualitative, financial + non-financial information.","Timely and frequent: daily/weekly/monthly reports as needed.","Segment/responsibility focus: reports by product, department or manager rather than only the whole firm.","Supplementary, not a substitute for financial accounting; it depends on FA data.","Emphasis on control: standards, budgets and variance analysis."]}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('13941c3e-275b-4830-a2ae-57aa617864fa', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Discuss the scope of Management Accounting.', 'Priority: Tier 3 | PYQ Connection: Not in supplied papers; syllabus item ("Scope").', 'Scope covers all areas that generate or use information for management:

Area | What it contributes
Financial accounting | Base data on assets, liabilities, income, expenses
Cost accounting | Cost ascertainment, cost control and cost reduction data
Budgeting and forecasting | Plans and targets for each department
Standard costing & variance analysis | Performance yardsticks; deviations and their causes
Marginal costing / CVP | Break-even, contribution, pricing and product-mix decisions
Financial statement analysis & interpretation | Comparative, common-size, trend, ratio, funds/cash-flow analysis
Decision accounting | Make-or-buy, capital budgeting, pricing, shutdown decisions
Management reporting / MIS | Right information, right person, right time
Taxation | Tax planning and compliance data
Internal audit and control | Checks on efficiency and adherence to policy
Statistical/quantitative methods | Forecasting, graphs, index numbers', NULL, NULL, NULL, 3, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'af42c8f2-f95c-4979-afba-54dc63cfec84', '{"blocks":[{"id":"amd-u1-c3-q-1","text":"Discuss the scope of Management Accounting.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c3-1","text":"Scope covers all areas that generate or use information for management:","type":"text","style":"paragraph"},{"id":"amd-u1-c3-2","rows":[["Area","What it contributes"],["Financial accounting","Base data on assets, liabilities, income, expenses"],["Cost accounting","Cost ascertainment, cost control and cost reduction data"],["Budgeting and forecasting","Plans and targets for each department"],["Standard costing & variance analysis","Performance yardsticks; deviations and their causes"],["Marginal costing / CVP","Break-even, contribution, pricing and product-mix decisions"],["Financial statement analysis & interpretation","Comparative, common-size, trend, ratio, funds/cash-flow analysis"],["Decision accounting","Make-or-buy, capital budgeting, pricing, shutdown decisions"],["Management reporting / MIS","Right information, right person, right time"],["Taxation","Tax planning and compliance data"],["Internal audit and control","Checks on efficiency and adherence to policy"],["Statistical/quantitative methods","Forecasting, graphs, index numbers"]],"type":"table"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('fbaa5327-d47f-4dfa-8e78-1555ed39d348', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Explain the importance of Management Accounting.', 'Priority: Tier 3 | PYQ Connection: Not in supplied papers; syllabus item ("Importance").', 'It matters because it:

Supports planning (budgets, targets, forecasts).
Improves decision-making with relevant, analysed data.
Enables control (actual vs budget/standard; variance analysis).
Helps evaluate performance of departments and managers.
Coordinates departments through common budgets and targets.
Motivates staff through clear targets and responsibility.
Supports cost control and reduction, raising profitability.
Improves communication through structured reports.
Helps identify strengths and weaknesses early (through analysis of accounts).
Aids tax planning and better use of resources.', NULL, NULL, NULL, 4, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'af42c8f2-f95c-4979-afba-54dc63cfec84', '{"blocks":[{"id":"amd-u1-c4-q-1","text":"Explain the importance of Management Accounting.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c4-1","text":"It matters because it:","type":"text","style":"paragraph"},{"id":"amd-u1-c4-2","type":"numberList","items":["Supports planning (budgets, targets, forecasts).","Improves decision-making with relevant, analysed data.","Enables control (actual vs budget/standard; variance analysis).","Helps evaluate performance of departments and managers.","Coordinates departments through common budgets and targets.","Motivates staff through clear targets and responsibility.","Supports cost control and reduction, raising profitability.","Improves communication through structured reports.","Helps identify strengths and weaknesses early (through analysis of accounts).","Aids tax planning and better use of resources."]}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('df43bdc3-813f-4799-ac6d-0baffd577a10', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'State and explain the functions of Management Accounting.', 'Priority: Tier 3 | PYQ Connection: Not in supplied papers; syllabus item ("Functions").', 'Planning & forecasting: budgets, targets, projections.
Organising & coordinating: aligning departments and resources to plans.
Controlling: comparing actual with plan and correcting deviations.
Decision-making: supplying cost/benefit data on alternatives.
Interpreting & analysing data: turning figures into meaning (trend, ratios, comparisons).
Communicating & reporting: structured reports to the right level.
Motivating: responsibility centres and targets link people to results.
Evaluating performance: measuring departments/managers against standards.', NULL, NULL, NULL, 5, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'af42c8f2-f95c-4979-afba-54dc63cfec84', '{"blocks":[{"id":"amd-u1-c5-q-1","text":"State and explain the functions of Management Accounting.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c5-1","type":"bulletList","items":["Planning & forecasting: budgets, targets, projections.","Organising & coordinating: aligning departments and resources to plans.","Controlling: comparing actual with plan and correcting deviations.","Decision-making: supplying cost/benefit data on alternatives.","Interpreting & analysing data: turning figures into meaning (trend, ratios, comparisons).","Communicating & reporting: structured reports to the right level.","Motivating: responsibility centres and targets link people to results.","Evaluating performance: measuring departments/managers against standards."]}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('7506c135-3bea-4c9f-999e-979dba5cf1be', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Explain the role of Management Accounting in a business.', 'Priority: Tier 3 | PYQ Connection: Not in supplied papers; syllabus item ("Role").', 'Management accounting acts as:

Information provider: the "eyes" of management: relevant, timely data.
Decision-support partner: evaluates alternatives before management commits resources.
Performance evaluator: sets yardsticks and reviews results.
Controller and coordinator: links budgets, departments and targets.
Strategic advisor: informs pricing, expansion, product mix, capital investment.
Guardian of resources: supports internal control, cost discipline and risk awareness.
Bridge between accounting and management: translates technical accounting into managerial language.', NULL, NULL, NULL, 6, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'af42c8f2-f95c-4979-afba-54dc63cfec84', '{"blocks":[{"id":"amd-u1-c6-q-1","text":"Explain the role of Management Accounting in a business.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c6-1","text":"Management accounting acts as:","type":"text","style":"paragraph"},{"id":"amd-u1-c6-2","type":"numberList","items":["Information provider: the \"eyes\" of management: relevant, timely data.","Decision-support partner: evaluates alternatives before management commits resources.","Performance evaluator: sets yardsticks and reviews results.","Controller and coordinator: links budgets, departments and targets.","Strategic advisor: informs pricing, expansion, product mix, capital investment.","Guardian of resources: supports internal control, cost discipline and risk awareness.","Bridge between accounting and management: translates technical accounting into managerial language."]}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('41b421c1-a004-4a71-9925-fdc4f8960038', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Explain the framework of Management Accounting.', 'Priority: Tier 3 | PYQ Connection: Not in supplied papers; syllabus item.', 'Framework = how information moves from raw data to management decisions:

OBJECTIVES  →  INPUTS  →  PROCESSING (tools & techniques)  →  OUTPUTS  →  USERS  →  DECISIONS  →  FEEDBACK
help manage-   financial     budgeting · standard costing ·      reports,     top / middle   plan, control,   actual results
ment plan,     accounts,     marginal costing · analysis of      statements,  / lower        act              flow back to
control,       cost records, financial statements · MIS          analyses     management                      inputs
decide         budgets,
               external data

Explain each block in one or two lines. The framework is a continuous loop: results of decisions become new inputs.', NULL, NULL, NULL, 7, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'af42c8f2-f95c-4979-afba-54dc63cfec84', '{"blocks":[{"id":"amd-u1-c7-q-1","text":"Explain the framework of Management Accounting.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c7-1","type":"formula","expression":"Framework = how information moves from raw data to management decisions:"},{"id":"amd-u1-c7-2","type":"formula","expression":"OBJECTIVES  →  INPUTS  →  PROCESSING (tools & techniques)  →  OUTPUTS  →  USERS  →  DECISIONS  →  FEEDBACK\nhelp manage-   financial     budgeting · standard costing ·      reports,     top / middle   plan, control,   actual results\nment plan,     accounts,     marginal costing · analysis of      statements,  / lower        act              flow back to\ncontrol,       cost records, financial statements · MIS          analyses     management                      inputs\ndecide         budgets,\n               external data"},{"id":"amd-u1-c7-3","text":"Explain each block in one or two lines. The framework is a continuous loop: results of decisions become new inputs.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('89789e5f-f297-4acc-8306-e947a65560ab', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Explain the tools/techniques of Management Accounting.', 'Priority: Tier 2 (links Part A to the Part B numericals) | PYQ Connection: Not directly; Trend/Comparative/Common-size are themselves tools, so the 2025 numericals test tools in practice.', 'Tool | Purpose
Financial planning & forecasting | Set future targets
Budgeting & budgetary control | Plan and control expenditure/revenue
Standard costing & variance analysis | Measure efficiency, find causes of deviation
Marginal costing & CVP/break-even | Pricing, product-mix, profit planning
Financial statement analysis: comparative, common-size, trend, ratio, funds flow, cash flow | Interpret financial position and performance (Unit 1 Part B numericals)
Capital budgeting (payback, NPV, IRR) | Long-term investment decisions
Responsibility accounting | Evaluate managers by controllable results
Management Information System (MIS) & reports | Deliver information to decision-makers
Statistical & graphical techniques | Forecasting and presentation', NULL, NULL, NULL, 8, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'af42c8f2-f95c-4979-afba-54dc63cfec84', '{"blocks":[{"id":"amd-u1-c8-q-1","text":"Explain the tools/techniques of Management Accounting.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c8-1","rows":[["Tool","Purpose"],["Financial planning & forecasting","Set future targets"],["Budgeting & budgetary control","Plan and control expenditure/revenue"],["Standard costing & variance analysis","Measure efficiency, find causes of deviation"],["Marginal costing & CVP/break-even","Pricing, product-mix, profit planning"],["Financial statement analysis: comparative, common-size, trend, ratio, funds flow, cash flow","Interpret financial position and performance (Unit 1 Part B numericals)"],["Capital budgeting (payback, NPV, IRR)","Long-term investment decisions"],["Responsibility accounting","Evaluate managers by controllable results"],["Management Information System (MIS) & reports","Deliver information to decision-makers"],["Statistical & graphical techniques","Forecasting and presentation"]],"type":"table"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('574b3590-e281-4a0e-805f-486277da8638', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Distinguish between Management Accounting and Financial Accounting. (7.5–8 marks)', 'Priority: Tier 2 (highest-probability Part A question; not yet in supplied papers) | PYQ Connection: Not in 2022/2025 papers; a standard "Distinguish between" 7.5/8-mark question and explicitly listed in the syllabus.', 'Basis | Management Accounting | Financial Accounting
Objective | Help management plan, control and decide | Record transactions; report profit and financial position
Users | Internal: top, middle, lower management | Mainly external: shareholders, lenders, tax authorities, regulators (and management)
Nature of information | Quantitative and qualitative; financial and non-financial | Quantitative, expressed in money only
Time orientation | Future-oriented (budgets, forecasts) along with past | Historical, past transactions
Legal requirement | Not compulsory | Compulsory (Companies Act 2013, Income Tax Act etc.)
Rules / standards | No prescribed standards; flexible | Must follow accounting standards (Ind AS/AS) and GAAP
Format | No fixed format; tailored to need | Prescribed format (Schedule III for companies)
Focus / level of detail | Segments: products, departments, jobs, responsibility centres | Business as a whole
Reporting frequency | As often as needed (daily/weekly/monthly) | Periodic; usually annual (plus quarterly for listed companies)
Precision | Estimates acceptable if timely | Accuracy and objectivity essential
Audit | Not subject to statutory audit | Statutory audit for companies
Publication | Confidential, internal | Published/filed with RoC (and stock exchange if listed)
Role in decisions | Directly supports decisions | Indirect; provides base data
Dependence | Draws on financial accounting data | Independent record of transactions', NULL, NULL, NULL, 9, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'af42c8f2-f95c-4979-afba-54dc63cfec84', '{"blocks":[{"id":"amd-u1-c9-q-1","text":"Distinguish between Management Accounting and Financial Accounting. (7.5–8 marks)","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c9-1","rows":[["Basis","Management Accounting","Financial Accounting"],["Objective","Help management plan, control and decide","Record transactions; report profit and financial position"],["Users","Internal: top, middle, lower management","Mainly external: shareholders, lenders, tax authorities, regulators (and management)"],["Nature of information","Quantitative and qualitative; financial and non-financial","Quantitative, expressed in money only"],["Time orientation","Future-oriented (budgets, forecasts) along with past","Historical, past transactions"],["Legal requirement","Not compulsory","Compulsory (Companies Act 2013, Income Tax Act etc.)"],["Rules / standards","No prescribed standards; flexible","Must follow accounting standards (Ind AS/AS) and GAAP"],["Format","No fixed format; tailored to need","Prescribed format (Schedule III for companies)"],["Focus / level of detail","Segments: products, departments, jobs, responsibility centres","Business as a whole"],["Reporting frequency","As often as needed (daily/weekly/monthly)","Periodic; usually annual (plus quarterly for listed companies)"],["Precision","Estimates acceptable if timely","Accuracy and objectivity essential"],["Audit","Not subject to statutory audit","Statutory audit for companies"],["Publication","Confidential, internal","Published/filed with RoC (and stock exchange if listed)"],["Role in decisions","Directly supports decisions","Indirect; provides base data"],["Dependence","Draws on financial accounting data","Independent record of transactions"]],"type":"table"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('d954e652-b440-4df8-aa4e-cdf11dd02e56', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'State the limitations of Management Accounting.', 'Priority: Tier 4 (supporting; commonly asked as "Advantages and limitations") | PYQ Connection: None in supplied papers.', 'Depends on financial and cost accounting data: poor-quality data gives poor analysis.
Based on estimates and forecasts, so subject to error.
Not a substitute for management judgement: it only supports decisions.
Costly to install and run, especially for small firms.
No standard rules, so results may vary between analysts.
Resistance to change from managers and staff.
Needs skilled personnel and wide knowledge of many disciplines.
Is still evolving; not an exact science.', NULL, NULL, NULL, 10, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'af42c8f2-f95c-4979-afba-54dc63cfec84', '{"blocks":[{"id":"amd-u1-c10-q-1","text":"State the limitations of Management Accounting.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c10-1","type":"numberList","items":["Depends on financial and cost accounting data: poor-quality data gives poor analysis.","Based on estimates and forecasts, so subject to error.","Not a substitute for management judgement: it only supports decisions.","Costly to install and run, especially for small firms.","No standard rules, so results may vary between analysts.","Resistance to change from managers and staff.","Needs skilled personnel and wide knowledge of many disciplines.","Is still evolving; not an exact science."]}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('d8a15534-2520-4fb1-bc49-1f34237bc9dd', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What are financial statements? (Oct 2022 Q1B, 7 marks, together with users; see B3)', 'Priority: Tier 1 | PYQ Connection: Oct 2022 Q1B (7 marks); direct hit.', 'Meaning: Financial statements are the formal, summarised end-products of the accounting process, prepared at the end of an accounting period to show the financial position and financial performance of a business.
Components (Companies Act 2013, s.2(40)):

Balance Sheet: assets, liabilities and equity at a date (*position*).
Statement of Profit & Loss: revenue, expenses and profit for a period (*performance*).
Cash Flow Statement: inflows/outflows of cash from operating, investing and financing activities.
Statement of Changes in Equity (where applicable).
Notes/explanatory statements annexed.

Purpose: communicate results to owners, lenders, government and others; support decisions; discharge accountability of management.', NULL, NULL, NULL, 11, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'b781caf3-ec2b-468d-9f77-f7e164d35065', '{"blocks":[{"id":"amd-u1-c11-q-1","text":"What are financial statements? (Oct 2022 Q1B, 7 marks, together with users; see B3)","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c11-1","type":"bulletList","items":["Meaning: Financial statements are the formal, summarised end-products of the accounting process, prepared at the end of an accounting period to show the financial position and financial performance of a business.","Components (Companies Act 2013, s.2(40)):"]},{"id":"amd-u1-c11-2","type":"numberList","items":["Balance Sheet: assets, liabilities and equity at a date (*position*).","Statement of Profit & Loss: revenue, expenses and profit for a period (*performance*).","Cash Flow Statement: inflows/outflows of cash from operating, investing and financing activities.","Statement of Changes in Equity (where applicable).","Notes/explanatory statements annexed."]},{"id":"amd-u1-c11-3","type":"bulletList","items":["Purpose: communicate results to owners, lenders, government and others; support decisions; discharge accountability of management."]}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('752acb39-4023-446d-b521-588382c3768f', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Explain the nature of financial statements.', 'Priority: Tier 2 | PYQ Connection: Syllabus item "Nature of financial statements"; supports the Oct 2022 Q1B theory answer.', 'They are:

Historical: record past transactions at cost.
Summarised: thousands of entries condensed into a few heads.
Expressed in money: non-monetary facts (staff morale, brand) are left out.
Based on accounting concepts and conventions: going concern, accrual, consistency, conservatism.
Influenced by personal judgement: depreciation method, stock valuation, provisions.
Interrelated: profit from the P&L flows to reserves in the Balance Sheet.
General purpose: made for many users, not one.

Limitations that follow

ignore price-level changes; can be window-dressed; not fully precise; compare only if policies are consistent. (These become the limitations of analysis in X2.)', NULL, NULL, NULL, 12, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'b781caf3-ec2b-468d-9f77-f7e164d35065', '{"blocks":[{"id":"amd-u1-c12-q-1","text":"Explain the nature of financial statements.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c12-1","text":"They are:","type":"text","style":"paragraph"},{"id":"amd-u1-c12-2","type":"numberList","items":["Historical: record past transactions at cost.","Summarised: thousands of entries condensed into a few heads.","Expressed in money: non-monetary facts (staff morale, brand) are left out.","Based on accounting concepts and conventions: going concern, accrual, consistency, conservatism.","Influenced by personal judgement: depreciation method, stock valuation, provisions.","Interrelated: profit from the P&L flows to reserves in the Balance Sheet.","General purpose: made for many users, not one."]},{"id":"amd-u1-c12-3","bold":true,"text":"Limitations that follow","type":"text","style":"heading"},{"id":"amd-u1-c12-4","text":"ignore price-level changes; can be window-dressed; not fully precise; compare only if policies are consistent. (These become the limitations of analysis in X2.)","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('7dabf984-33fa-4829-84df-05bbf8b8e95e', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'List the different types of users of financial statements and what each wants. (Oct 2022 Q1B)', 'Priority: Tier 1 | PYQ Connection: Oct 2022 Q1B (7 marks); direct hit.', 'Group | User | Interest
Internal | Owners/shareholders | Profitability, dividends, safety of investment
 | Management | Performance, planning, control, decisions
 | Employees/trade unions | Job security, bonus, wage bargaining
External | Investors (potential) | Whether to invest; risk and return
 | Lenders (banks, debenture holders) | Ability to pay interest and repay principal
 | Suppliers/creditors | Liquidity; ability to pay on time
 | Customers | Continuity of supply and service
 | Government/tax authorities | Taxable profit, compliance, statistics
 | Regulators (SEBI, RoC, stock exchanges) | Legal and disclosure compliance
 | Public, researchers, analysts | Trends, contribution to economy, industry comparison', NULL, NULL, NULL, 13, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'b781caf3-ec2b-468d-9f77-f7e164d35065', '{"blocks":[{"id":"amd-u1-c13-q-1","text":"List the different types of users of financial statements and what each wants. (Oct 2022 Q1B)","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c13-1","rows":[["Group","User","Interest"],["Internal","Owners/shareholders","Profitability, dividends, safety of investment"],["","Management","Performance, planning, control, decisions"],["","Employees/trade unions","Job security, bonus, wage bargaining"],["External","Investors (potential)","Whether to invest; risk and return"],["","Lenders (banks, debenture holders)","Ability to pay interest and repay principal"],["","Suppliers/creditors","Liquidity; ability to pay on time"],["","Customers","Continuity of supply and service"],["","Government/tax authorities","Taxable profit, compliance, statistics"],["","Regulators (SEBI, RoC, stock exchanges)","Legal and disclosure compliance"],["","Public, researchers, analysts","Trends, contribution to economy, industry comparison"]],"type":"table"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('b5206fa5-d0d9-4871-8384-5955d004e934', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Differentiate between Owner''s Fund and Owed Fund. (Oct 2022 Q1Q, 7 marks)', 'Priority: Tier 3 (borderline: not named in current syllabus but explains the structure of the vertical Balance Sheet) | PYQ Connection: Oct 2022 Q1Q. Historical: confirm with your teacher whether it is still asked.', 'Basis | Owner''s Fund (Shareholders''/Proprietors'' funds) | Owed Fund (Outsiders''/Borrowed funds)
Meaning | Capital brought in by owners plus profits retained | Money borrowed from outsiders
Examples | Equity and preference share capital, general reserve, P&L (credit) balance | Debentures, term loans, public deposits, creditors, bills payable, bank overdraft
Ownership/control | Gives ownership; equity carries voting rights | Gives no ownership or voting right
Return | Dividend (depends on profit; not compulsory) | Interest (fixed; compulsory)
Repayment | Not repayable during life of company (except redemption of preference) | Repayable on due date
Risk | Bears business risk; paid last | Lower risk; paid before shareholders
Security | No charge on assets | May be secured on assets
Tax treatment | Dividend is not tax-deductible | Interest is tax-deductible
Balance sheet position | Sources of funds: shareholders'' funds | Non-current and current liabilities', NULL, NULL, NULL, 14, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'b781caf3-ec2b-468d-9f77-f7e164d35065', '{"blocks":[{"id":"amd-u1-c14-q-1","text":"Differentiate between Owner''s Fund and Owed Fund. (Oct 2022 Q1Q, 7 marks)","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c14-1","rows":[["Basis","Owner''s Fund (Shareholders''/Proprietors'' funds)","Owed Fund (Outsiders''/Borrowed funds)"],["Meaning","Capital brought in by owners plus profits retained","Money borrowed from outsiders"],["Examples","Equity and preference share capital, general reserve, P&L (credit) balance","Debentures, term loans, public deposits, creditors, bills payable, bank overdraft"],["Ownership/control","Gives ownership; equity carries voting rights","Gives no ownership or voting right"],["Return","Dividend (depends on profit; not compulsory)","Interest (fixed; compulsory)"],["Repayment","Not repayable during life of company (except redemption of preference)","Repayable on due date"],["Risk","Bears business risk; paid last","Lower risk; paid before shareholders"],["Security","No charge on assets","May be secured on assets"],["Tax treatment","Dividend is not tax-deductible","Interest is tax-deductible"],["Balance sheet position","Sources of funds: shareholders'' funds","Non-current and current liabilities"]],"type":"table"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('4ab069c0-9950-4f82-907d-a40804c32e4b', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'State the forms of Balance Sheet. Which is suitable for analysis and why?', 'Priority: Tier 1 (needed for every Balance Sheet numerical) | PYQ Connection: Oct 2022 Q1A, Q1P; Oct 2025 Q1.1 (all require vertical form).', 'Horizontal (T-form / account form): liabilities on the left, assets on the right; good for recording, poor for multi-year comparison.
Vertical (report form): one column downward, with years across as columns; the analysis form.
Why vertical suits analysis: (i) years sit side by side; (ii) items are classified into groups so totals of fixed assets, current assets, shareholders'' funds and current liabilities are visible; (iii) % columns and change columns can be added directly; (iv) working capital and capital structure are obvious.

Vertical Balance Sheet template (Schedule III style)

I.  EQUITY AND LIABILITIES  (Sources of funds)
    1. Shareholders'' funds
         (a) Share capital        — equity, preference
         (b) Reserves & surplus   — general reserve, P&L credit balance
    2. Non-current liabilities    — debentures, term loans, public deposits*
    3. Current liabilities        — creditors, bills payable, outstanding expenses,
                                    bank overdraft, unpaid dividend, provision for tax
                                                         TOTAL
II. ASSETS  (Application of funds)
    1. Non-current assets         — fixed assets (tangible/intangible), investments
    2. Current assets             — inventories, debtors, bills receivable, cash & bank,
                                    advances, prepaid expenses, other current assets
    3. Miscellaneous expenditure  — preliminary expenses / debit balance of P&L (not written off)
                                                         TOTAL

*Treat as long-term unless the question says repayable within a year.', NULL, NULL, NULL, 15, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'b781caf3-ec2b-468d-9f77-f7e164d35065', '{"blocks":[{"id":"amd-u1-c15-q-1","text":"State the forms of Balance Sheet. Which is suitable for analysis and why?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c15-1","type":"bulletList","items":["Horizontal (T-form / account form): liabilities on the left, assets on the right; good for recording, poor for multi-year comparison.","Vertical (report form): one column downward, with years across as columns; the analysis form.","Why vertical suits analysis: (i) years sit side by side; (ii) items are classified into groups so totals of fixed assets, current assets, shareholders'' funds and current liabilities are visible; (iii) % columns and change columns can be added directly; (iv) working capital and capital structure are obvious."]},{"id":"amd-u1-c15-2","text":"Vertical Balance Sheet template (Schedule III style)","type":"text","style":"paragraph"},{"id":"amd-u1-c15-3","type":"formula","expression":"I.  EQUITY AND LIABILITIES  (Sources of funds)\n    1. Shareholders'' funds\n         (a) Share capital        — equity, preference\n         (b) Reserves & surplus   — general reserve, P&L credit balance\n    2. Non-current liabilities    — debentures, term loans, public deposits*\n    3. Current liabilities        — creditors, bills payable, outstanding expenses,\n                                    bank overdraft, unpaid dividend, provision for tax\n                                                         TOTAL\nII. ASSETS  (Application of funds)\n    1. Non-current assets         — fixed assets (tangible/intangible), investments\n    2. Current assets             — inventories, debtors, bills receivable, cash & bank,\n                                    advances, prepaid expenses, other current assets\n    3. Miscellaneous expenditure  — preliminary expenses / debit balance of P&L (not written off)\n                                                         TOTAL"},{"id":"amd-u1-c15-4","text":"*Treat as long-term unless the question says repayable within a year.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('0ac26228-da01-4f2a-8738-9d2140134db7', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'State the forms of P&L Account. Which is suitable for analysis?', 'Priority: Tier 1 | PYQ Connection: Oct 2025 Q1.2, Q1.3 (vertical statements given); Oct 2025 Q2.1 (horizontal → vertical conversion; see XN1).', 'Traditional (horizontal, T-form): Trading Account + P&L Account with debit/credit sides.
Statement of P&L / Income Statement (vertical): a single downward statement showing profit at each stage (gross profit → operating profit → PBT → PAT). This is the form for analysis, because each stage can be compared over years and expressed as % of sales.

Vertical P&L template (for analysis)

Revenue from operations (Net Sales)
Less: Cost of goods sold  [Opening stock + Purchases + Direct/Carriage inward − Closing stock]
GROSS PROFIT
Less: Operating expenses  [Office & administration, Selling & distribution, Depreciation]
OPERATING PROFIT
Add:  Non-operating income     [interest/dividend received, profit on sale of assets]
Less: Non-operating expenses   [interest paid, loss on sale of assets]
PROFIT BEFORE TAX (PBT)
Less: Income tax
PROFIT AFTER TAX (PAT)
Less: Dividend
RETAINED EARNINGS

Note

When the exam paper already gives a vertical statement (as in Oct 2025 Q1.2 and Q1.3, with Gross Margin → Total Expenses → Net Profit before Depreciation & Taxation → PBT → PAT), follow the paper''s own line sequence and do not re-arrange it.', NULL, NULL, NULL, 16, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'b781caf3-ec2b-468d-9f77-f7e164d35065', '{"blocks":[{"id":"amd-u1-c16-q-1","text":"State the forms of P&L Account. Which is suitable for analysis?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c16-1","type":"bulletList","items":["Traditional (horizontal, T-form): Trading Account + P&L Account with debit/credit sides.","Statement of P&L / Income Statement (vertical): a single downward statement showing profit at each stage (gross profit → operating profit → PBT → PAT). This is the form for analysis, because each stage can be compared over years and expressed as % of sales."]},{"id":"amd-u1-c16-2","text":"Vertical P&L template (for analysis)","type":"text","style":"paragraph"},{"id":"amd-u1-c16-3","type":"formula","expression":"Revenue from operations (Net Sales)\nLess: Cost of goods sold  [Opening stock + Purchases + Direct/Carriage inward − Closing stock]\nGROSS PROFIT\nLess: Operating expenses  [Office & administration, Selling & distribution, Depreciation]\nOPERATING PROFIT\nAdd:  Non-operating income     [interest/dividend received, profit on sale of assets]\nLess: Non-operating expenses   [interest paid, loss on sale of assets]\nPROFIT BEFORE TAX (PBT)\nLess: Income tax\nPROFIT AFTER TAX (PAT)\nLess: Dividend\nRETAINED EARNINGS"},{"id":"amd-u1-c16-4","bold":true,"text":"Note","type":"text","style":"heading"},{"id":"amd-u1-c16-5","text":"When the exam paper already gives a vertical statement (as in Oct 2025 Q1.2 and Q1.3, with Gross Margin → Total Expenses → Net Profit before Depreciation & Taxation → PBT → PAT), follow the paper''s own line sequence and do not re-arrange it.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('76a93dc3-728e-4385-b0c6-7e9f3b4c4fa6', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Classify the following items when arranging a vertical Balance Sheet: Bills receivable, Bills payable, Outstanding expenses, Prepaid expenses, Advances, Bank overdraft, Provision for tax, Unpaid dividend, Preference capital, P&L (Cr), P&L (Dr), Preliminary expenses, Goodwill, Investments.', 'Priority: Tier 1 (the 2025 Ambani question gave an unarranged list, so this skill was directly tested) | PYQ Connection: Oct 2025 Q1.1 (prepaid expenses, misc current assets, bills payable, O/s expenses, 6% preference capital); Oct 2022 Q1P (bills receivable/payable, preliminary expenses).', 'Item | Classification
Bills receivable | Current asset (trade receivable)
Bills payable | Current liability (trade payable)
Outstanding expenses | Current liability (other current liability)
Prepaid expenses | Current asset (short-term advances/other current assets)
Advances (given) | Current asset (short-term loans & advances)
Bank overdraft | Current liability (short-term borrowings)
Provision for tax | Current liability (short-term provision)
Unpaid/unclaimed dividend | Current liability (other current liability)
Debentures, term loans, public deposits | Non-current liability (long-term borrowings)
Equity and preference share capital | Shareholders'' funds (share capital)
General reserve, P&L credit balance | Shareholders'' funds (reserves & surplus)
P&L debit balance; Preliminary expenses | Miscellaneous expenditure / fictitious asset (or deducted from reserves; follow your teacher''s style)
Goodwill | Intangible fixed asset
Land & building, plant & machinery, furniture, motor car | Tangible fixed assets
Investments | Non-current investments (unless stated short-term)
Stock/inventories, debtors, cash, bank balance | Current assets', NULL, NULL, NULL, 17, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'b781caf3-ec2b-468d-9f77-f7e164d35065', '{"blocks":[{"id":"amd-u1-c17-q-1","text":"Classify the following items when arranging a vertical Balance Sheet: Bills receivable, Bills payable, Outstanding expenses, Prepaid expenses, Advances, Bank overdraft, Provision for tax, Unpaid dividend, Preference capital, P&L (Cr), P&L (Dr), Preliminary expenses, Goodwill, Investments.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c17-1","rows":[["Item","Classification"],["Bills receivable","Current asset (trade receivable)"],["Bills payable","Current liability (trade payable)"],["Outstanding expenses","Current liability (other current liability)"],["Prepaid expenses","Current asset (short-term advances/other current assets)"],["Advances (given)","Current asset (short-term loans & advances)"],["Bank overdraft","Current liability (short-term borrowings)"],["Provision for tax","Current liability (short-term provision)"],["Unpaid/unclaimed dividend","Current liability (other current liability)"],["Debentures, term loans, public deposits","Non-current liability (long-term borrowings)"],["Equity and preference share capital","Shareholders'' funds (share capital)"],["General reserve, P&L credit balance","Shareholders'' funds (reserves & surplus)"],["P&L debit balance; Preliminary expenses","Miscellaneous expenditure / fictitious asset (or deducted from reserves; follow your teacher''s style)"],["Goodwill","Intangible fixed asset"],["Land & building, plant & machinery, furniture, motor car","Tangible fixed assets"],["Investments","Non-current investments (unless stated short-term)"],["Stock/inventories, debtors, cash, bank balance","Current assets"]],"type":"table"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('39ec4f3a-9ae0-4a4b-aa57-d296cebfb842', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What is analysis and interpretation of financial statements? State its objectives and types.', 'Priority: Tier 2 | PYQ Connection: Framework for all Q1 numericals in 2022 and 2025.', 'Analysis: breaking financial statements into their components and arranging them so relationships become visible. Interpretation: explaining what the analysed figures mean and drawing conclusions.
Objectives: assess profitability, liquidity, solvency and operating efficiency; find trends; compare with past years, other firms and industry; support decisions and forecasting.
Types:
By direction: Horizontal analysis (across years: Comparative, Trend) and Vertical analysis (within one year: Common size).
By user: Internal (management, with full access) and External (investors, lenders, using published statements).
By period: short-term (liquidity) and long-term (solvency, growth).
Techniques: Comparative statements, common-size statements, trend analysis, ratio analysis, funds flow/cash flow analysis.', NULL, NULL, NULL, 18, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'b781caf3-ec2b-468d-9f77-f7e164d35065', '{"blocks":[{"id":"amd-u1-c18-q-1","text":"What is analysis and interpretation of financial statements? State its objectives and types.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c18-1","type":"bulletList","items":["Analysis: breaking financial statements into their components and arranging them so relationships become visible. Interpretation: explaining what the analysed figures mean and drawing conclusions.","Objectives: assess profitability, liquidity, solvency and operating efficiency; find trends; compare with past years, other firms and industry; support decisions and forecasting.","Types:","By direction: Horizontal analysis (across years: Comparative, Trend) and Vertical analysis (within one year: Common size).","By user: Internal (management, with full access) and External (investors, lenders, using published statements).","By period: short-term (liquidity) and long-term (solvency, growth).","Techniques: Comparative statements, common-size statements, trend analysis, ratio analysis, funds flow/cash flow analysis."]}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('4521a12c-a95b-4d5f-9e6e-a0c900b563e8', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Explain Trend Analysis. What is the base year concept?', 'Priority: Tier 1 | PYQ Connection: Oct 2022 Q1A (Trend Balance Sheet); Oct 2025 Q1.3 (Trend P&L).', 'Meaning: Trend analysis (trend percentages / index-number method) is a form of horizontal analysis over three or more years, in which each item''s figure in every year is expressed as a percentage of the same item''s figure in a chosen base year.
Base year: normally the earliest year, taken as 100. All later years are compared with the base year, not with the previous year. The base year should be a normal year (not abnormally good or bad).
Purpose: see the direction and speed of change of each item; compare growth of related items (sales vs cost vs profit); spot abnormal years; forecast; judge management performance.
Reading: trend % above 100 = increase; below 100 = decrease; increase % = trend % − 100.', NULL, NULL, NULL, 19, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', '02323f1c-d030-4025-b46c-93afd3ed4cb6', '{"blocks":[{"id":"amd-u1-c19-q-1","text":"Explain Trend Analysis. What is the base year concept?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c19-1","type":"bulletList","items":["Meaning: Trend analysis (trend percentages / index-number method) is a form of horizontal analysis over three or more years, in which each item''s figure in every year is expressed as a percentage of the same item''s figure in a chosen base year.","Base year: normally the earliest year, taken as 100. All later years are compared with the base year, not with the previous year. The base year should be a normal year (not abnormally good or bad).","Purpose: see the direction and speed of change of each item; compare growth of related items (sales vs cost vs profit); spot abnormal years; forecast; judge management performance.","Reading: trend % above 100 = increase; below 100 = decrease; increase % = trend % − 100."]}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('632a2af0-850d-4930-aa75-1e1be4cb0758', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'State the formula for trend percentages and the steps to prepare a Trend Statement.', 'Priority: Tier 1 | PYQ Connection: Oct 2022 Q1A, Oct 2025 Q1.3.', 'Formula

Trend % = (Item in current year ÷ Item in base year) × 100

Steps

Arrange the statement in vertical form, years across, oldest first.
Choose the base year (first year unless told otherwise).
Write 100 against every line in the base year column.
For each line and each later year: that year''s figure ÷ that line''s base-year figure × 100.
Calculate totals and sub-totals from their own rupee figures. Never add or average percentages.
Round consistently (two decimals, e.g. 116.67).
Check: base column = 100 everywhere; totals from rupee figures; recompute 2–3 lines.
Write a 3–4 line interpretation.

Layout

Particulars | Yr1 ₹ | Yr2 ₹ | Yr3 ₹ | Yr1 % | Yr2 % | Yr3 %', NULL, NULL, NULL, 20, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', '02323f1c-d030-4025-b46c-93afd3ed4cb6', '{"blocks":[{"id":"amd-u1-c20-q-1","text":"State the formula for trend percentages and the steps to prepare a Trend Statement.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c20-1","bold":true,"text":"Formula","type":"text","style":"heading"},{"id":"amd-u1-c20-2","type":"formula","expression":"Trend % = (Item in current year ÷ Item in base year) × 100"},{"id":"amd-u1-c20-3","bold":true,"text":"Steps","type":"text","style":"heading"},{"id":"amd-u1-c20-4","type":"numberList","items":["Arrange the statement in vertical form, years across, oldest first.","Choose the base year (first year unless told otherwise).","Write 100 against every line in the base year column.","For each line and each later year: that year''s figure ÷ that line''s base-year figure × 100.","Calculate totals and sub-totals from their own rupee figures. Never add or average percentages.","Round consistently (two decimals, e.g. 116.67).","Check: base column = 100 everywhere; totals from rupee figures; recompute 2–3 lines.","Write a 3–4 line interpretation."]},{"id":"amd-u1-c20-5","bold":true,"text":"Layout","type":"text","style":"heading"},{"id":"amd-u1-c20-6","text":"Particulars | Yr1 ₹ | Yr2 ₹ | Yr3 ₹ | Yr1 % | Yr2 % | Yr3 %","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('56b78485-ac7e-4d05-ae5d-226af9edbb65', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'How do you interpret a Trend Statement?', 'Priority: Tier 2 | PYQ Connection: Interpretation not explicitly asked in 2022/2025, but a 1–2 line comment secures easy marks and protects against a "comment" variant.', 'Income items: a rising trend is good (sales, profit).
Expense items: compare with sales trend. If cost trend < sales trend, margins widen (good); if cost trend > sales trend, margins shrink.
Profit trend > sales trend signals operating leverage (fixed costs spread over higher sales).
Balance Sheet: compare fixed-asset trend with long-term funds trend (are long-term assets financed by long-term funds?); current liabilities trend > current assets trend = liquidity pressure; falling share capital/debenture trend = repayment/buy-back.
Always conclude in words: what grew, what lagged, what it implies.', NULL, NULL, NULL, 21, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', '02323f1c-d030-4025-b46c-93afd3ed4cb6', '{"blocks":[{"id":"amd-u1-c21-q-1","text":"How do you interpret a Trend Statement?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c21-1","type":"bulletList","items":["Income items: a rising trend is good (sales, profit).","Expense items: compare with sales trend. If cost trend < sales trend, margins widen (good); if cost trend > sales trend, margins shrink.","Profit trend > sales trend signals operating leverage (fixed costs spread over higher sales).","Balance Sheet: compare fixed-asset trend with long-term funds trend (are long-term assets financed by long-term funds?); current liabilities trend > current assets trend = liquidity pressure; falling share capital/debenture trend = repayment/buy-back.","Always conclude in words: what grew, what lagged, what it implies."]}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('8d189677-b6e5-4ee4-82ed-0db41bf5c1c2', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'State the advantages and limitations of Trend Analysis.', 'Priority: Tier 3 | PYQ Connection: Not in supplied papers; likely "Explain/Comment" material.', 'Advantages: simple; shows direction and rate at a glance; makes unlike-sized items comparable; useful for forecasting; highlights abnormal movements.
Limitations: base-year distortion if the base year is abnormal; ignores inflation/price-level changes; % on a small base are misleading; only comparable for the same firm unless policies match; shows what changed, not why; percentages alone hide absolute size.', NULL, NULL, NULL, 22, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', '02323f1c-d030-4025-b46c-93afd3ed4cb6', '{"blocks":[{"id":"amd-u1-c22-q-1","text":"State the advantages and limitations of Trend Analysis.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c22-1","type":"bulletList","items":["Advantages: simple; shows direction and rate at a glance; makes unlike-sized items comparable; useful for forecasting; highlights abnormal movements.","Limitations: base-year distortion if the base year is abnormal; ignores inflation/price-level changes; % on a small base are misleading; only comparable for the same firm unless policies match; shows what changed, not why; percentages alone hide absolute size."]}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('379351ed-5f4a-42ec-8bc3-0b96e524400c', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What mistakes do students make in Trend problems, and how can the question be varied?', 'Priority: Tier 1 | PYQ Connection: Both papers; 2022 = Balance Sheet, 2025 = P&L, so the paper alternates statement type.', 'Mistakes: (1) dividing by the previous year instead of the base year; (2) forgetting to show base = 100; (3) adding percentages to get totals; (4) wrong year order; (5) only percentages, no rupee figures; (6) no comment; (7) confusing trend % (120) with % change (20%).
Variations: Trend on Balance Sheet (assets and liabilities) or P&L; base year given as a later year ("take 2022 as base"); 4–5 years; Trend of selected items only (sales, PAT); missing sub-totals that must be computed first; chain-base (year-on-year) if the question explicitly asks; a horizontal statement first needing conversion to vertical.', NULL, NULL, NULL, 23, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', '02323f1c-d030-4025-b46c-93afd3ed4cb6', '{"blocks":[{"id":"amd-u1-c23-q-1","text":"What mistakes do students make in Trend problems, and how can the question be varied?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c23-1","type":"bulletList","items":["Mistakes: (1) dividing by the previous year instead of the base year; (2) forgetting to show base = 100; (3) adding percentages to get totals; (4) wrong year order; (5) only percentages, no rupee figures; (6) no comment; (7) confusing trend % (120) with % change (20%).","Variations: Trend on Balance Sheet (assets and liabilities) or P&L; base year given as a later year (\"take 2022 as base\"); 4–5 years; Trend of selected items only (sales, PAT); missing sub-totals that must be computed first; chain-base (year-on-year) if the question explicitly asks; a horizontal statement first needing conversion to vertical."]}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('31a8a762-a48d-49ca-8841-14f3091103c9', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'The revenue statement for 2021–2023 is given below. Prepare a Trend Analysis. (7.5 marks)', 'Priority: Tier 1', 'Concept

Trend percentages with a fixed base year (P&L).

Formula

Trend % = (Current-year item ÷ Base-year item) × 100

Given

Three years of data; no base year stated, so 2021 (earliest) = 100. All figures in ₹. (Paper heading says "31st March 2025" but columns are 2021–2023; arithmetic is consistent.)

Solution

(each line uses its own base-year figure)

Particulars | 2021 ₹ | 2022 ₹ | 2023 ₹ | 2021 % | 2022 % | 2023 %
Sales | 50,00,000 | 60,00,000 | 75,00,000 | 100 | 120.00 | 150.00
Less: Cost of Sales | 30,00,000 | 35,00,000 | 40,00,000 | 100 | 116.67 | 133.33
Gross Margin | 20,00,000 | 25,00,000 | 35,00,000 | 100 | 125.00 | 175.00
Management Expense | 4,00,000 | 5,00,000 | 6,00,000 | 100 | 125.00 | 150.00
Sales Expense | 3,00,000 | 4,00,000 | 3,00,000 | 100 | 133.33 | 100.00
Interest on Borrowing | 2,00,000 | 1,00,000 | 2,00,000 | 100 | 50.00 | 100.00
Total Expenses | 9,00,000 | 10,00,000 | 11,00,000 | 100 | 111.11 | 122.22
NP before Dep. & Tax | 11,00,000 | 15,00,000 | 24,00,000 | 100 | 136.36 | 218.18
Depreciation | 4,00,000 | 5,00,000 | 7,00,000 | 100 | 125.00 | 175.00
Profit before Tax | 7,00,000 | 10,00,000 | 17,00,000 | 100 | 142.86 | 242.86
Income Tax | 3,50,000 | 5,00,000 | 6,00,000 | 100 | 142.86 | 171.43
Profit after Tax | 3,50,000 | 5,00,000 | 11,00,000 | 100 | 142.86 | 314.29

Sample workings: Sales 2022 = 60,00,000 ÷ 50,00,000 × 100 = 120.00 · COS 2022 = 35 ÷ 30 × 100 = 116.67 · NPBDT 2023 = 24 ÷ 11 × 100 = 218.18 · PAT 2023 = 11 ÷ 3.5 × 100 = 314.29.

Final Answer

Trend statement as tabulated (base 2021 = 100); Sales 150, Gross Margin 175, PBT 242.86, PAT 314.29 in 2023.

Interpretation

Sales grew 50% over the base year while cost of sales grew only 33.33%, so gross margin grew 75%.
Total expenses rose just 22.22%, so NP before dep. & tax more than doubled (218.18) and PAT more than tripled (314.29): classic operating leverage.
Sales expense fell back to 100 in 2023 despite 50% higher sales (better selling efficiency). Interest dipped to 50 in 2022 and returned to 100 (borrowings fluctuated).
Tax trend (171.43) grew slower than PBT (242.86): the tax burden per rupee of profit fell.

Exam Tip

Every percentage uses 2021 as the denominator, including 2023 (never 2022). Compute each sub-total''s trend from its own rupee figures. The check: 2021 column must show 100 for all twelve lines.', NULL, NULL, NULL, 24, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', '02323f1c-d030-4025-b46c-93afd3ed4cb6', '{"blocks":[{"id":"amd-u1-c24-q-1","text":"The revenue statement for 2021–2023 is given below. Prepare a Trend Analysis. (7.5 marks)","type":"text","style":"paragraph"},{"id":"amd-u1-c24-q-extra-1","rows":[["Particulars","2021","2022","2023"],["Sales","50,00,000","60,00,000","75,00,000"],["Less: Cost of Sales","30,00,000","35,00,000","40,00,000"],["Gross Margin","20,00,000","25,00,000","35,00,000"],["Management Expense","4,00,000","5,00,000","6,00,000"],["Sales Expense","3,00,000","4,00,000","3,00,000"],["Interest on Borrowing","2,00,000","1,00,000","2,00,000"],["Total Expenses","9,00,000","10,00,000","11,00,000"],["Net Profit before Depreciation & Taxation","11,00,000","15,00,000","24,00,000"],["Depreciation","4,00,000","5,00,000","7,00,000"],["Profit before Taxation","7,00,000","10,00,000","17,00,000"],["Income Tax","3,50,000","5,00,000","6,00,000"],["Profit after Tax","3,50,000","5,00,000","11,00,000"]],"type":"table"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c24-1","bold":true,"text":"Concept","type":"text","style":"heading"},{"id":"amd-u1-c24-2","text":"Trend percentages with a fixed base year (P&L).","type":"text","style":"paragraph"},{"id":"amd-u1-c24-3","bold":true,"text":"Formula","type":"text","style":"heading"},{"id":"amd-u1-c24-4","type":"formula","expression":"Trend % = (Current-year item ÷ Base-year item) × 100"},{"id":"amd-u1-c24-5","bold":true,"text":"Given","type":"text","style":"heading"},{"id":"amd-u1-c24-6","type":"formula","expression":"Three years of data; no base year stated, so 2021 (earliest) = 100. All figures in ₹. (Paper heading says \"31st March 2025\" but columns are 2021–2023; arithmetic is consistent.)"},{"id":"amd-u1-c24-7","bold":true,"text":"Solution","type":"text","style":"heading"},{"id":"amd-u1-c24-8","text":"(each line uses its own base-year figure)","type":"text","style":"paragraph"},{"id":"amd-u1-c24-9","rows":[["Particulars","2021 ₹","2022 ₹","2023 ₹","2021 %","2022 %","2023 %"],["Sales","50,00,000","60,00,000","75,00,000","100","120.00","150.00"],["Less: Cost of Sales","30,00,000","35,00,000","40,00,000","100","116.67","133.33"],["Gross Margin","20,00,000","25,00,000","35,00,000","100","125.00","175.00"],["Management Expense","4,00,000","5,00,000","6,00,000","100","125.00","150.00"],["Sales Expense","3,00,000","4,00,000","3,00,000","100","133.33","100.00"],["Interest on Borrowing","2,00,000","1,00,000","2,00,000","100","50.00","100.00"],["Total Expenses","9,00,000","10,00,000","11,00,000","100","111.11","122.22"],["NP before Dep. & Tax","11,00,000","15,00,000","24,00,000","100","136.36","218.18"],["Depreciation","4,00,000","5,00,000","7,00,000","100","125.00","175.00"],["Profit before Tax","7,00,000","10,00,000","17,00,000","100","142.86","242.86"],["Income Tax","3,50,000","5,00,000","6,00,000","100","142.86","171.43"],["Profit after Tax","3,50,000","5,00,000","11,00,000","100","142.86","314.29"]],"type":"table"},{"id":"amd-u1-c24-10","type":"formula","expression":"Sample workings: Sales 2022 = 60,00,000 ÷ 50,00,000 × 100 = 120.00 · COS 2022 = 35 ÷ 30 × 100 = 116.67 · NPBDT 2023 = 24 ÷ 11 × 100 = 218.18 · PAT 2023 = 11 ÷ 3.5 × 100 = 314.29."},{"id":"amd-u1-c24-11","bold":true,"text":"Final Answer","type":"text","style":"heading"},{"id":"amd-u1-c24-12","type":"formula","expression":"Trend statement as tabulated (base 2021 = 100); Sales 150, Gross Margin 175, PBT 242.86, PAT 314.29 in 2023."},{"id":"amd-u1-c24-13","bold":true,"text":"Interpretation","type":"text","style":"heading"},{"id":"amd-u1-c24-14","type":"bulletList","items":["Sales grew 50% over the base year while cost of sales grew only 33.33%, so gross margin grew 75%.","Total expenses rose just 22.22%, so NP before dep. & tax more than doubled (218.18) and PAT more than tripled (314.29): classic operating leverage.","Sales expense fell back to 100 in 2023 despite 50% higher sales (better selling efficiency). Interest dipped to 50 in 2022 and returned to 100 (borrowings fluctuated).","Tax trend (171.43) grew slower than PBT (242.86): the tax burden per rupee of profit fell."]},{"id":"amd-u1-c24-15","bold":true,"text":"Exam Tip","type":"text","style":"heading"},{"id":"amd-u1-c24-16","text":"Every percentage uses 2021 as the denominator, including 2023 (never 2022). Compute each sub-total''s trend from its own rupee figures. The check: 2021 column must show 100 for all twelve lines.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('b6875292-d55b-4bcf-b260-bc065d90c2e4', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'M/s John Ltd''s Balance Sheet as at 31st March 2020, 2021, 2022 is given. Prepare a Trend Balance Sheet in vertical form. (8 marks)', 'Priority: Tier 1', 'Concept

Trend percentages on a Balance Sheet; conversion to vertical form.

Formula

Trend % = (Item of the year ÷ Item of base year 2020) × 100

Given

Base year = 2020 = 100. Check: Assets 2020 = 60+26+54 = 1,40,000 ✔ · 2021 = 51+26+66.4 = 1,43,400 ✔ · 2022 = 87.6+36.8+37.8 = 1,62,200 ✔. Liabilities also agree.

Solution

Particulars | 2020 ₹ | 2021 ₹ | 2022 ₹ | 2020 % | 2021 % | 2022 %
I. Application of funds (Assets) |  |  |  |  |  | 
Fixed Assets | 60,000 | 51,000 | 87,600 | 100 | 85.00 | 146.00
Investment | 26,000 | 26,000 | 36,800 | 100 | 100.00 | 141.54
Current Assets | 54,000 | 66,400 | 37,800 | 100 | 122.96 | 70.00
Total Assets | 1,40,000 | 1,43,400 | 1,62,200 | 100 | 102.43 | 115.86
II. Sources of funds (Liabilities) |  |  |  |  |  | 
Share Capital | 66,000 | 62,700 | 82,000 | 100 | 95.00 | 124.24
Debentures | 54,000 | 56,700 | 19,000 | 100 | 105.00 | 35.19
Liabilities for expenses | 20,000 | 24,000 | 61,200 | 100 | 120.00 | 306.00
Total Liabilities | 1,40,000 | 1,43,400 | 1,62,200 | 100 | 102.43 | 115.86

Sample workings: FA 2021 = 51,000 ÷ 60,000 × 100 = 85.00 · Investment 2022 = 36,800 ÷ 26,000 × 100 = 141.54 · CA 2021 = 66,400 ÷ 54,000 × 100 = 122.96 · Debentures 2022 = 19,000 ÷ 54,000 × 100 = 35.19 · Total 2022 = 1,62,200 ÷ 1,40,000 × 100 = 115.86.

Final Answer

Trend Balance Sheet as above; total assets/liabilities index 102.43 (2021) and 115.86 (2022).

Interpretation

Fixed assets and investments rose sharply in 2022 (146 and 141.54), but current assets fell to 70.
Debentures were repaid (35.19) and share capital rose (124.24), so long-term funding shifted from debt to equity.
Liabilities for expenses tripled (306): the company leans on short-term unpaid liabilities while its current assets shrank, so there is liquidity strain (current liabilities 61,200 vs current assets 37,800 in 2022).

Exam Tip

The total assets and total liabilities trend must be identical (102.43, 115.86); this is your built-in check. Indian-format numbers: use ₹ figures exactly as given (no lakhs conversion).', NULL, NULL, NULL, 25, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', '02323f1c-d030-4025-b46c-93afd3ed4cb6', '{"blocks":[{"id":"amd-u1-c25-q-1","text":"M/s John Ltd''s Balance Sheet as at 31st March 2020, 2021, 2022 is given. Prepare a Trend Balance Sheet in vertical form. (8 marks)","type":"text","style":"paragraph"},{"id":"amd-u1-c25-q-extra-1","rows":[["Particulars","2020","2021","2022"],["Fixed Assets","60,000","51,000","87,600"],["Investment","26,000","26,000","36,800"],["Current Assets","54,000","66,400","37,800"],["Total","1,40,000","1,43,400","1,62,200"],["Share Capital","66,000","62,700","82,000"],["Debentures","54,000","56,700","19,000"],["Liabilities for expenses","20,000","24,000","61,200"],["Total","1,40,000","1,43,400","1,62,200"]],"type":"table"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c25-1","bold":true,"text":"Concept","type":"text","style":"heading"},{"id":"amd-u1-c25-2","text":"Trend percentages on a Balance Sheet; conversion to vertical form.","type":"text","style":"paragraph"},{"id":"amd-u1-c25-3","bold":true,"text":"Formula","type":"text","style":"heading"},{"id":"amd-u1-c25-4","type":"formula","expression":"Trend % = (Item of the year ÷ Item of base year 2020) × 100"},{"id":"amd-u1-c25-5","bold":true,"text":"Given","type":"text","style":"heading"},{"id":"amd-u1-c25-6","type":"formula","expression":"Base year = 2020 = 100. Check: Assets 2020 = 60+26+54 = 1,40,000 ✔ · 2021 = 51+26+66.4 = 1,43,400 ✔ · 2022 = 87.6+36.8+37.8 = 1,62,200 ✔. Liabilities also agree."},{"id":"amd-u1-c25-7","bold":true,"text":"Solution","type":"text","style":"heading"},{"id":"amd-u1-c25-8","rows":[["Particulars","2020 ₹","2021 ₹","2022 ₹","2020 %","2021 %","2022 %"],["I. Application of funds (Assets)","","","","","",""],["Fixed Assets","60,000","51,000","87,600","100","85.00","146.00"],["Investment","26,000","26,000","36,800","100","100.00","141.54"],["Current Assets","54,000","66,400","37,800","100","122.96","70.00"],["Total Assets","1,40,000","1,43,400","1,62,200","100","102.43","115.86"],["II. Sources of funds (Liabilities)","","","","","",""],["Share Capital","66,000","62,700","82,000","100","95.00","124.24"],["Debentures","54,000","56,700","19,000","100","105.00","35.19"],["Liabilities for expenses","20,000","24,000","61,200","100","120.00","306.00"],["Total Liabilities","1,40,000","1,43,400","1,62,200","100","102.43","115.86"]],"type":"table"},{"id":"amd-u1-c25-9","type":"formula","expression":"Sample workings: FA 2021 = 51,000 ÷ 60,000 × 100 = 85.00 · Investment 2022 = 36,800 ÷ 26,000 × 100 = 141.54 · CA 2021 = 66,400 ÷ 54,000 × 100 = 122.96 · Debentures 2022 = 19,000 ÷ 54,000 × 100 = 35.19 · Total 2022 = 1,62,200 ÷ 1,40,000 × 100 = 115.86."},{"id":"amd-u1-c25-10","bold":true,"text":"Final Answer","type":"text","style":"heading"},{"id":"amd-u1-c25-11","text":"Trend Balance Sheet as above; total assets/liabilities index 102.43 (2021) and 115.86 (2022).","type":"text","style":"paragraph"},{"id":"amd-u1-c25-12","bold":true,"text":"Interpretation","type":"text","style":"heading"},{"id":"amd-u1-c25-13","type":"bulletList","items":["Fixed assets and investments rose sharply in 2022 (146 and 141.54), but current assets fell to 70.","Debentures were repaid (35.19) and share capital rose (124.24), so long-term funding shifted from debt to equity.","Liabilities for expenses tripled (306): the company leans on short-term unpaid liabilities while its current assets shrank, so there is liquidity strain (current liabilities 61,200 vs current assets 37,800 in 2022)."]},{"id":"amd-u1-c25-14","bold":true,"text":"Exam Tip","type":"text","style":"heading"},{"id":"amd-u1-c25-15","text":"The total assets and total liabilities trend must be identical (102.43, 115.86); this is your built-in check. Indian-format numbers: use ₹ figures exactly as given (no lakhs conversion).","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('ed228e06-d8c6-4048-9755-3e74f15180da', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What is a Comparative Statement? State its purpose and structure.', 'Priority: Tier 1 | PYQ Connection: Oct 2025 Q1.2 (called "Comparative Size Statement", 7.5 marks). Comparative Balance Sheet not yet asked, so high probability.', 'Meaning: Financial statements of two or more successive periods placed side by side so that the changes in each item can be seen. It is horizontal analysis.
Purpose: show the absolute (₹) and relative (%) change in each item; judge whether position/performance improved or deteriorated; compare growth of related items; support forecasting and decisions.
Two forms: Comparative Balance Sheet and Comparative Income (P&L) Statement.
Structure:

Particulars | Year 1 (₹) | Year 2 (₹) | Absolute change (₹) | % change', NULL, NULL, NULL, 26, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', '9797ce7a-c8a8-4e38-9595-3c8839df157c', '{"blocks":[{"id":"amd-u1-c26-q-1","text":"What is a Comparative Statement? State its purpose and structure.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c26-1","type":"bulletList","items":["Meaning: Financial statements of two or more successive periods placed side by side so that the changes in each item can be seen. It is horizontal analysis.","Purpose: show the absolute (₹) and relative (%) change in each item; judge whether position/performance improved or deteriorated; compare growth of related items; support forecasting and decisions.","Two forms: Comparative Balance Sheet and Comparative Income (P&L) Statement.","Structure:"]},{"id":"amd-u1-c26-2","rows":[["Particulars","Year 1 (₹)","Year 2 (₹)","Absolute change (₹)","% change"]],"type":"table"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('64fdeb8a-5ae8-4ed7-aac7-6bdf290b32ab', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'State the formulas for absolute change and percentage change.', 'Priority: Tier 1 | PYQ Connection: Oct 2025 Q1.2.', 'Absolute change (₹) = Current-year figure − Previous-year figure
% change = (Absolute change ÷ Previous-year figure) × 100

Rules

The earlier year is always the base for the percentage.
Increase shown as +, decrease in brackets ( ).
If the earlier-year figure is nil or negative, % change is not meaningful, so write "N.A."
Calculate totals/sub-totals from their own figures; do not add up percentages.', NULL, NULL, NULL, 27, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', '9797ce7a-c8a8-4e38-9595-3c8839df157c', '{"blocks":[{"id":"amd-u1-c27-q-1","text":"State the formulas for absolute change and percentage change.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c27-1","type":"bulletList","items":["Absolute change (₹) = Current-year figure − Previous-year figure","% change = (Absolute change ÷ Previous-year figure) × 100"]},{"id":"amd-u1-c27-2","bold":true,"text":"Rules","type":"text","style":"heading"},{"id":"amd-u1-c27-3","type":"bulletList","items":["The earlier year is always the base for the percentage.","Increase shown as +, decrease in brackets ( ).","If the earlier-year figure is nil or negative, % change is not meaningful, so write \"N.A.\"","Calculate totals/sub-totals from their own figures; do not add up percentages."]}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('a3daa335-faa2-43ac-b94b-b868881af0c7', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'How do you prepare a Comparative Statement?', 'Priority: Tier 1 | PYQ Connection: Oct 2025 Q1.2.', 'Arrange in vertical form (classified: assets, liabilities; or sales → PAT).
Place earlier year first, later year second.
Absolute change column = later − earlier for every line.
% change = change ÷ earlier-year figure × 100 for every line.
Compute sub-totals (gross profit, total assets, working capital, etc.) from their own figures; do not add percentages.
Verify: total-asset change = total-liability change (Balance Sheet); sub-item changes add up to the total change.
Write a short interpretation (what grew fastest, what lagged, effect on profit or liquidity).', NULL, NULL, NULL, 28, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', '9797ce7a-c8a8-4e38-9595-3c8839df157c', '{"blocks":[{"id":"amd-u1-c28-q-1","text":"How do you prepare a Comparative Statement?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c28-1","type":"numberList","items":["Arrange in vertical form (classified: assets, liabilities; or sales → PAT).","Place earlier year first, later year second.","Absolute change column = later − earlier for every line.","% change = change ÷ earlier-year figure × 100 for every line.","Compute sub-totals (gross profit, total assets, working capital, etc.) from their own figures; do not add percentages.","Verify: total-asset change = total-liability change (Balance Sheet); sub-item changes add up to the total change.","Write a short interpretation (what grew fastest, what lagged, effect on profit or liquidity)."]}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('eb51aaa7-3485-4def-aa00-9f9d14ead82a', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What conclusions can be drawn from a Comparative Statement?', 'Priority: Tier 2 | PYQ Connection: Interpretation not explicitly required in 2025 Q1.2 but expected as good practice.', 'P&L: compare % growth of sales with % growth of cost of sales and expenses. If costs grow faster than sales, margins shrink. Look at the growth of PBT vs PAT (a tax jump can squeeze PAT).
Balance Sheet:
Growth in fixed assets: how financed (reserves, debentures, creditors)?
Current assets vs current liabilities: working capital rising or falling?
Fall in cash/bank balances: liquidity pressure.
Rise in reserves: profits are being retained.
Fall in debentures/loans: debt repayment; lower financial risk.', NULL, NULL, NULL, 29, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', '9797ce7a-c8a8-4e38-9595-3c8839df157c', '{"blocks":[{"id":"amd-u1-c29-q-1","text":"What conclusions can be drawn from a Comparative Statement?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c29-1","type":"bulletList","items":["P&L: compare % growth of sales with % growth of cost of sales and expenses. If costs grow faster than sales, margins shrink. Look at the growth of PBT vs PAT (a tax jump can squeeze PAT).","Balance Sheet:","Growth in fixed assets: how financed (reserves, debentures, creditors)?","Current assets vs current liabilities: working capital rising or falling?","Fall in cash/bank balances: liquidity pressure.","Rise in reserves: profits are being retained.","Fall in debentures/loans: debt repayment; lower financial risk."]}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('83002cf2-59ec-4316-b36b-57f0fad1e1a9', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What are common mistakes and possible variations in Comparative Statement problems?', 'Priority: Tier 1 | PYQ Connection: Oct 2025 Q1.2 (wording ambiguity).', 'Mistakes: (1) percentage on the later year (wrong base); (2) mixing up the two columns; (3) no sign for decrease; (4) adding percentages for totals; (5) blank-line "%" when the base is zero; (6) copying figures wrongly from the paper; (7) not verifying sub-totals.
Variations: Comparative Balance Sheet (never asked yet); three-year comparative (two change columns, each against the preceding year); comparative with working-capital rows added; horizontal → vertical conversion first; a comparative common-size statement (each year as % of sales); missing sub-totals that must be computed; a question that says "Comparative Size Statement" (see CN1/SN3 for both readings).', NULL, NULL, NULL, 30, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', '9797ce7a-c8a8-4e38-9595-3c8839df157c', '{"blocks":[{"id":"amd-u1-c30-q-1","text":"What are common mistakes and possible variations in Comparative Statement problems?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c30-1","type":"bulletList","items":["Mistakes: (1) percentage on the later year (wrong base); (2) mixing up the two columns; (3) no sign for decrease; (4) adding percentages for totals; (5) blank-line \"%\" when the base is zero; (6) copying figures wrongly from the paper; (7) not verifying sub-totals.","Variations: Comparative Balance Sheet (never asked yet); three-year comparative (two change columns, each against the preceding year); comparative with working-capital rows added; horizontal → vertical conversion first; a comparative common-size statement (each year as % of sales); missing sub-totals that must be computed; a question that says \"Comparative Size Statement\" (see CN1/SN3 for both readings)."]}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('85f98676-e3cf-4d1d-9884-c1abcf2e1906', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'The revenue statements for 2023 and 2024 are given. Prepare a Comparative Size Statement. (7.5 marks)', 'Priority: Tier 1', 'Concept

Comparative (horizontal) statement: absolute and % change, base = 2023.

Formula

Absolute change = 2024 − 2023 · % change = (Absolute change ÷ 2023 figure) × 100

Given

Base (earlier) year = 2023. Data note: 2023 PBT is printed as 1,95,000 although 4,90,000 − 3,00,000 = 1,90,000; PAT 1,00,000 agrees with the printed 1,95,000. Use the printed figures. All other rows are arithmetically consistent.

Solution

Particulars | 2023 (₹) | 2024 (₹) | Increase/(Decrease) (₹) | % Change
Sales | 36,00,000 | 43,20,000 | 7,20,000 | 20.00
Less: Cost of Sales | 23,00,000 | 28,00,000 | 5,00,000 | 21.74
Gross Margin | 13,00,000 | 15,20,000 | 2,20,000 | 16.92
Management Expense | 2,00,000 | 2,25,000 | 25,000 | 12.50
Sales Expense | 3,60,000 | 4,32,000 | 72,000 | 20.00
Interest on Borrowing | 2,50,000 | 3,00,000 | 50,000 | 20.00
Total Expenses | 8,10,000 | 9,57,000 | 1,47,000 | 18.15
NP before Dep. & Tax | 4,90,000 | 5,63,000 | 73,000 | 14.90
Depreciation | 3,00,000 | 3,25,000 | 25,000 | 8.33
Profit before Tax | 1,95,000 | 2,38,000 | 43,000 | 22.05
Income Tax | 95,000 | 1,28,000 | 33,000 | 34.74
Profit after Tax | 1,00,000 | 1,10,000 | 10,000 | 10.00

Sample workings: Sales: 43,20,000 − 36,00,000 = 7,20,000 → 7,20,000 ÷ 36,00,000 × 100 = 20.00% · COS: 5,00,000 ÷ 23,00,000 × 100 = 21.74% · GM: 2,20,000 ÷ 13,00,000 × 100 = 16.92% · Total exp: 1,47,000 ÷ 8,10,000 × 100 = 18.15% · Tax: 33,000 ÷ 95,000 × 100 = 34.74%.

Final Answer

Comparative statement as tabulated. Sales +20.00%, Gross Margin +16.92%, PBT +22.05%, PAT +10.00%.

Interpretation

Sales rose 20% but cost of sales rose faster (21.74%), so gross margin grew only 16.92%; the gross margin percentage slipped.
Management expense (+12.5%) and depreciation (+8.33%) grew slower than sales, while sales expense and interest grew in line (+20% each); net effect: PBT rose 22.05%, slightly faster than sales.
Income tax jumped 34.74%, faster than PBT, so PAT rose only 10%.

Exam Tip

Denominator is the 2023 figure, not 2024. If the examiner meant a comparative common-size statement, use SN3 as well: present both if the wording is unclear, and label each clearly.', NULL, NULL, NULL, 31, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', '9797ce7a-c8a8-4e38-9595-3c8839df157c', '{"blocks":[{"id":"amd-u1-c31-q-1","text":"The revenue statements for 2023 and 2024 are given. Prepare a Comparative Size Statement. (7.5 marks)","type":"text","style":"paragraph"},{"id":"amd-u1-c31-q-extra-1","rows":[["Particulars","2023","2024"],["Sales","36,00,000","43,20,000"],["Less: Cost of Sales","23,00,000","28,00,000"],["Gross Margin","13,00,000","15,20,000"],["Management Expense","2,00,000","2,25,000"],["Sales Expense","3,60,000","4,32,000"],["Interest on Borrowing","2,50,000","3,00,000"],["Total Expenses","8,10,000","9,57,000"],["Net Profit before Depreciation & Taxation","4,90,000","5,63,000"],["Depreciation","3,00,000","3,25,000"],["Profit before Taxation","1,95,000","2,38,000"],["Income Tax","95,000","1,28,000"],["Profit after Tax","1,00,000","1,10,000"]],"type":"table"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c31-1","bold":true,"text":"Concept","type":"text","style":"heading"},{"id":"amd-u1-c31-2","type":"formula","expression":"Comparative (horizontal) statement: absolute and % change, base = 2023."},{"id":"amd-u1-c31-3","bold":true,"text":"Formula","type":"text","style":"heading"},{"id":"amd-u1-c31-4","type":"formula","expression":"Absolute change = 2024 − 2023 · % change = (Absolute change ÷ 2023 figure) × 100"},{"id":"amd-u1-c31-5","bold":true,"text":"Given","type":"text","style":"heading"},{"id":"amd-u1-c31-6","type":"formula","expression":"Base (earlier) year = 2023. Data note: 2023 PBT is printed as 1,95,000 although 4,90,000 − 3,00,000 = 1,90,000; PAT 1,00,000 agrees with the printed 1,95,000. Use the printed figures. All other rows are arithmetically consistent."},{"id":"amd-u1-c31-7","bold":true,"text":"Solution","type":"text","style":"heading"},{"id":"amd-u1-c31-8","rows":[["Particulars","2023 (₹)","2024 (₹)","Increase/(Decrease) (₹)","% Change"],["Sales","36,00,000","43,20,000","7,20,000","20.00"],["Less: Cost of Sales","23,00,000","28,00,000","5,00,000","21.74"],["Gross Margin","13,00,000","15,20,000","2,20,000","16.92"],["Management Expense","2,00,000","2,25,000","25,000","12.50"],["Sales Expense","3,60,000","4,32,000","72,000","20.00"],["Interest on Borrowing","2,50,000","3,00,000","50,000","20.00"],["Total Expenses","8,10,000","9,57,000","1,47,000","18.15"],["NP before Dep. & Tax","4,90,000","5,63,000","73,000","14.90"],["Depreciation","3,00,000","3,25,000","25,000","8.33"],["Profit before Tax","1,95,000","2,38,000","43,000","22.05"],["Income Tax","95,000","1,28,000","33,000","34.74"],["Profit after Tax","1,00,000","1,10,000","10,000","10.00"]],"type":"table"},{"id":"amd-u1-c31-9","type":"formula","expression":"Sample workings: Sales: 43,20,000 − 36,00,000 = 7,20,000 → 7,20,000 ÷ 36,00,000 × 100 = 20.00% · COS: 5,00,000 ÷ 23,00,000 × 100 = 21.74% · GM: 2,20,000 ÷ 13,00,000 × 100 = 16.92% · Total exp: 1,47,000 ÷ 8,10,000 × 100 = 18.15% · Tax: 33,000 ÷ 95,000 × 100 = 34.74%."},{"id":"amd-u1-c31-10","bold":true,"text":"Final Answer","type":"text","style":"heading"},{"id":"amd-u1-c31-11","text":"Comparative statement as tabulated. Sales +20.00%, Gross Margin +16.92%, PBT +22.05%, PAT +10.00%.","type":"text","style":"paragraph"},{"id":"amd-u1-c31-12","bold":true,"text":"Interpretation","type":"text","style":"heading"},{"id":"amd-u1-c31-13","type":"bulletList","items":["Sales rose 20% but cost of sales rose faster (21.74%), so gross margin grew only 16.92%; the gross margin percentage slipped.","Management expense (+12.5%) and depreciation (+8.33%) grew slower than sales, while sales expense and interest grew in line (+20% each); net effect: PBT rose 22.05%, slightly faster than sales.","Income tax jumped 34.74%, faster than PBT, so PAT rose only 10%."]},{"id":"amd-u1-c31-14","bold":true,"text":"Exam Tip","type":"text","style":"heading"},{"id":"amd-u1-c31-15","text":"Denominator is the 2023 figure, not 2024. If the examiner meant a comparative common-size statement, use SN3 as well: present both if the wording is unclear, and label each clearly.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('575e5875-5f2f-4713-a49a-686e63abf064', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'From the following, prepare a Comparative Balance Sheet of Sun Ltd. as at 31st March 2024 and 2025, and comment on liquidity.', 'Priority: Tier 1 (unasked cell of the technique × statement matrix)', 'Concept

Comparative Balance Sheet in vertical form; change in working capital.

Formula

Change = 2025 − 2024 · % change = Change ÷ 2024 × 100 · Working capital = Current assets − Current liabilities

Given

Total assets 2024 = 5,00,000 + 1,00,000 + 1,20,000 + 80,000 + 1,00,000 = 9,00,000; 2025 = 6,00,000 + 80,000 + 1,50,000 + 1,00,000 + 70,000 = 10,00,000. Liabilities: 2024 = 4,00,000 + 1,50,000 + 2,00,000 + 1,50,000 = 9,00,000 ✔; 2025 = 4,00,000 + 2,10,000 + 1,50,000 + 2,40,000 = 10,00,000 ✔.

Solution

Particulars | 2024 (₹) | 2025 (₹) | Increase/(Decrease) (₹) | % Change
I. Assets |  |  |  | 
Fixed Assets | 5,00,000 | 6,00,000 | 1,00,000 | 20.00
Investments | 1,00,000 | 80,000 | (20,000) | (20.00)
Current Assets: |  |  |  | 
Inventories | 1,20,000 | 1,50,000 | 30,000 | 25.00
Debtors | 80,000 | 1,00,000 | 20,000 | 25.00
Cash & Bank | 1,00,000 | 70,000 | (30,000) | (30.00)
Total Current Assets | 3,00,000 | 3,20,000 | 20,000 | 6.67
Total Assets | 9,00,000 | 10,00,000 | 1,00,000 | 11.11
II. Equity & Liabilities |  |  |  | 
Equity Share Capital | 4,00,000 | 4,00,000 | Nil | Nil
Reserves | 1,50,000 | 2,10,000 | 60,000 | 40.00
Shareholders'' Funds | 5,50,000 | 6,10,000 | 60,000 | 10.91
Debentures | 2,00,000 | 1,50,000 | (50,000) | (25.00)
Current Liabilities (Creditors) | 1,50,000 | 2,40,000 | 90,000 | 60.00
Total Liabilities | 9,00,000 | 10,00,000 | 1,00,000 | 11.11
Working Capital (CA − CL) | 1,50,000 | 80,000 | (70,000) | (46.67)

Final Answer

Statement as above. Working capital fell from ₹1,50,000 to ₹80,000 (−46.67%).

Interpretation

Fixed assets grew by ₹1,00,000, funded mainly by retained profits (+60,000) and creditors (+90,000), while ₹50,000 of debentures were repaid.
Creditors rose 60% but current assets only 6.67%, so working capital nearly halved; cash fell 30%. Liquidity has weakened even though total assets grew 11.11%.

Exam Tip

Show Nil for unchanged items (not 0%). Check: change in total assets (1,00,000) = change in total liabilities (1,00,000). Adding a working-capital line earns interpretation marks.', NULL, NULL, NULL, 32, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', '9797ce7a-c8a8-4e38-9595-3c8839df157c', '{"blocks":[{"id":"amd-u1-c32-q-1","text":"From the following, prepare a Comparative Balance Sheet of Sun Ltd. as at 31st March 2024 and 2025, and comment on liquidity.","type":"text","style":"paragraph"},{"id":"amd-u1-c32-q-extra-1","rows":[["Particulars","2024","2025"],["Fixed Assets","5,00,000","6,00,000"],["Investments","1,00,000","80,000"],["Inventories","1,20,000","1,50,000"],["Debtors","80,000","1,00,000"],["Cash & Bank","1,00,000","70,000"],["Equity Share Capital","4,00,000","4,00,000"],["Reserves","1,50,000","2,10,000"],["Debentures","2,00,000","1,50,000"],["Creditors (current liabilities)","1,50,000","2,40,000"]],"type":"table"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c32-1","bold":true,"text":"Concept","type":"text","style":"heading"},{"id":"amd-u1-c32-2","text":"Comparative Balance Sheet in vertical form; change in working capital.","type":"text","style":"paragraph"},{"id":"amd-u1-c32-3","bold":true,"text":"Formula","type":"text","style":"heading"},{"id":"amd-u1-c32-4","type":"formula","expression":"Change = 2025 − 2024 · % change = Change ÷ 2024 × 100 · Working capital = Current assets − Current liabilities"},{"id":"amd-u1-c32-5","bold":true,"text":"Given","type":"text","style":"heading"},{"id":"amd-u1-c32-6","type":"formula","expression":"Total assets 2024 = 5,00,000 + 1,00,000 + 1,20,000 + 80,000 + 1,00,000 = 9,00,000; 2025 = 6,00,000 + 80,000 + 1,50,000 + 1,00,000 + 70,000 = 10,00,000. Liabilities: 2024 = 4,00,000 + 1,50,000 + 2,00,000 + 1,50,000 = 9,00,000 ✔; 2025 = 4,00,000 + 2,10,000 + 1,50,000 + 2,40,000 = 10,00,000 ✔."},{"id":"amd-u1-c32-7","bold":true,"text":"Solution","type":"text","style":"heading"},{"id":"amd-u1-c32-8","rows":[["Particulars","2024 (₹)","2025 (₹)","Increase/(Decrease) (₹)","% Change"],["I. Assets","","","",""],["Fixed Assets","5,00,000","6,00,000","1,00,000","20.00"],["Investments","1,00,000","80,000","(20,000)","(20.00)"],["Current Assets:","","","",""],["Inventories","1,20,000","1,50,000","30,000","25.00"],["Debtors","80,000","1,00,000","20,000","25.00"],["Cash & Bank","1,00,000","70,000","(30,000)","(30.00)"],["Total Current Assets","3,00,000","3,20,000","20,000","6.67"],["Total Assets","9,00,000","10,00,000","1,00,000","11.11"],["II. Equity & Liabilities","","","",""],["Equity Share Capital","4,00,000","4,00,000","Nil","Nil"],["Reserves","1,50,000","2,10,000","60,000","40.00"],["Shareholders'' Funds","5,50,000","6,10,000","60,000","10.91"],["Debentures","2,00,000","1,50,000","(50,000)","(25.00)"],["Current Liabilities (Creditors)","1,50,000","2,40,000","90,000","60.00"],["Total Liabilities","9,00,000","10,00,000","1,00,000","11.11"],["Working Capital (CA − CL)","1,50,000","80,000","(70,000)","(46.67)"]],"type":"table"},{"id":"amd-u1-c32-9","bold":true,"text":"Final Answer","type":"text","style":"heading"},{"id":"amd-u1-c32-10","text":"Statement as above. Working capital fell from ₹1,50,000 to ₹80,000 (−46.67%).","type":"text","style":"paragraph"},{"id":"amd-u1-c32-11","bold":true,"text":"Interpretation","type":"text","style":"heading"},{"id":"amd-u1-c32-12","type":"bulletList","items":["Fixed assets grew by ₹1,00,000, funded mainly by retained profits (+60,000) and creditors (+90,000), while ₹50,000 of debentures were repaid.","Creditors rose 60% but current assets only 6.67%, so working capital nearly halved; cash fell 30%. Liquidity has weakened even though total assets grew 11.11%."]},{"id":"amd-u1-c32-13","bold":true,"text":"Exam Tip","type":"text","style":"heading"},{"id":"amd-u1-c32-14","type":"formula","expression":"Show Nil for unchanged items (not 0%). Check: change in total assets (1,00,000) = change in total liabilities (1,00,000). Adding a working-capital line earns interpretation marks."}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('fb291169-da0a-4419-b7a8-7c6006671af3', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What is a Common Size Statement? State its purpose.', 'Priority: Tier 1 | PYQ Connection: Oct 2022 Q1P (Sachin Ltd) and Oct 2025 Q1.1 (Ambani Ltd); the only technique to appear in both papers.', 'Meaning: A statement in which every item is expressed as a percentage of one common base figure of the same year. It is vertical analysis (within one statement). Hence "common size": all items are put on a common 100 scale.
Purpose: show the structure (composition) of assets, funds and profit; compare firms of different size and years of the same firm; judge capital structure, asset mix, cost structure and profitability without being distorted by size.
Two forms: Common-size Balance Sheet and Common-size Income (P&L) Statement.', NULL, NULL, NULL, 33, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'ca0f7bfd-42a9-449a-b18a-f3bda005d1f9', '{"blocks":[{"id":"amd-u1-c33-q-1","text":"What is a Common Size Statement? State its purpose.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c33-1","type":"bulletList","items":["Meaning: A statement in which every item is expressed as a percentage of one common base figure of the same year. It is vertical analysis (within one statement). Hence \"common size\": all items are put on a common 100 scale.","Purpose: show the structure (composition) of assets, funds and profit; compare firms of different size and years of the same firm; judge capital structure, asset mix, cost structure and profitability without being distorted by size.","Two forms: Common-size Balance Sheet and Common-size Income (P&L) Statement."]}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('28552898-6d31-4559-9dd5-64d64d85b605', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'State the base for a Common-size Balance Sheet and P&L, and the formula.', 'Priority: Tier 1 | PYQ Connection: Both papers.', 'Formula: Common-size % = (Individual item ÷ Base figure) × 100
Balance Sheet base: Total assets = Total liabilities (equity + liabilities) = 100%.
P&L base: Net Sales (Revenue from operations) = 100%.
Sub-totals (fixed assets, current assets, shareholders'' funds, current liabilities, gross profit, PBT, PAT) are also % of the same base, calculated from their own ₹ figures.
Each side of the Balance Sheet separately adds to 100%.', NULL, NULL, NULL, 34, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'ca0f7bfd-42a9-449a-b18a-f3bda005d1f9', '{"blocks":[{"id":"amd-u1-c34-q-1","text":"State the base for a Common-size Balance Sheet and P&L, and the formula.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c34-1","type":"bulletList","items":["Formula: Common-size % = (Individual item ÷ Base figure) × 100","Balance Sheet base: Total assets = Total liabilities (equity + liabilities) = 100%.","P&L base: Net Sales (Revenue from operations) = 100%.","Sub-totals (fixed assets, current assets, shareholders'' funds, current liabilities, gross profit, PBT, PAT) are also % of the same base, calculated from their own ₹ figures.","Each side of the Balance Sheet separately adds to 100%."]}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('f6e862cf-6ec3-49e4-bdec-ee3ebec58f0a', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'How do you prepare a Common-size Balance Sheet from a raw balance sheet?', 'Priority: Tier 1 | PYQ Connection: Oct 2022 Q1P; Oct 2025 Q1.1.', 'Classify each item (see B7): shareholders'' funds, non-current liabilities, current liabilities; fixed assets, investments, current assets, miscellaneous expenditure.
Compute sub-totals and grand total; the two sides must match.
Take the grand total as 100%.
For each item: item ÷ grand total × 100 (2 decimals).
Add sub-total percentages from their ₹ sub-totals; check that liabilities and assets each sum to 100% (a ±0.01 rounding difference is acceptable).
Present in vertical form with columns: Particulars | ₹ | % of total.
Add 2–3 lines of interpretation.

Format (vertical Common-size Balance Sheet)

Particulars                 ₹        % of total
I.  SOURCES OF FUNDS
    Shareholders'' funds     ...      ...
    Non-current liabilities ...      ...
    Current liabilities     ...      ...
    TOTAL                   ...      100.00
II. APPLICATION OF FUNDS
    Fixed assets            ...      ...
    Investments             ...      ...
    Current assets          ...      ...
    Misc. expenditure       ...      ...
    TOTAL                   ...      100.00', NULL, NULL, NULL, 35, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'ca0f7bfd-42a9-449a-b18a-f3bda005d1f9', '{"blocks":[{"id":"amd-u1-c35-q-1","text":"How do you prepare a Common-size Balance Sheet from a raw balance sheet?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c35-1","type":"numberList","items":["Classify each item (see B7): shareholders'' funds, non-current liabilities, current liabilities; fixed assets, investments, current assets, miscellaneous expenditure.","Compute sub-totals and grand total; the two sides must match.","Take the grand total as 100%.","For each item: item ÷ grand total × 100 (2 decimals).","Add sub-total percentages from their ₹ sub-totals; check that liabilities and assets each sum to 100% (a ±0.01 rounding difference is acceptable).","Present in vertical form with columns: Particulars | ₹ | % of total.","Add 2–3 lines of interpretation."]},{"id":"amd-u1-c35-2","bold":true,"text":"Format (vertical Common-size Balance Sheet)","type":"text","style":"heading"},{"id":"amd-u1-c35-3","type":"formula","expression":"Particulars                 ₹        % of total\nI.  SOURCES OF FUNDS\n    Shareholders'' funds     ...      ...\n    Non-current liabilities ...      ...\n    Current liabilities     ...      ...\n    TOTAL                   ...      100.00\nII. APPLICATION OF FUNDS\n    Fixed assets            ...      ...\n    Investments             ...      ...\n    Current assets          ...      ...\n    Misc. expenditure       ...      ...\n    TOTAL                   ...      100.00"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('6d2a72ab-5682-4030-802e-d140e740404c', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What conclusions can be drawn from a Common-size Balance Sheet / P&L?', 'Priority: Tier 2 | PYQ Connection: Both papers (Balance Sheet); the P&L version is unasked.', 'Balance Sheet: owner''s funds % vs outside funds % (capital structure); fixed assets % vs current assets % (asset mix); current assets % vs current liabilities % (liquidity); cash/bank % (liquid reserves); reserves % (retained profit).
P&L: cost of sales % (margin pressure), each expense %, PBT % and PAT % (profitability).
Comparison over years or firms: shift in a % shows a change in structure even when ₹ amounts grow.', NULL, NULL, NULL, 36, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'ca0f7bfd-42a9-449a-b18a-f3bda005d1f9', '{"blocks":[{"id":"amd-u1-c36-q-1","text":"What conclusions can be drawn from a Common-size Balance Sheet / P&L?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c36-1","type":"bulletList","items":["Balance Sheet: owner''s funds % vs outside funds % (capital structure); fixed assets % vs current assets % (asset mix); current assets % vs current liabilities % (liquidity); cash/bank % (liquid reserves); reserves % (retained profit).","P&L: cost of sales % (margin pressure), each expense %, PBT % and PAT % (profitability).","Comparison over years or firms: shift in a % shows a change in structure even when ₹ amounts grow."]}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('d3d7ccc0-9300-4953-9785-18b03e53e461', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What mistakes are made in Common-size problems, and how can the question be varied?', 'Priority: Tier 1 | PYQ Connection: Oct 2025 Q1.1 (unarranged list), Oct 2022 Q1P (T-form).', 'Mistakes: (1) using assets side total only for one side and forgetting the other side is also 100%; (2) treating preference capital as a liability (it is shareholders'' funds); (3) not classifying (prepaid expenses, misc. current assets, bills payable placed wrongly); (4) not verifying the two totals are equal; (5) using sales as the base for a Balance Sheet; (6) forcing totals to 100.00 by "adjusting" a wrong item; (7) no vertical presentation; (8) percentages to 0/1 decimal inconsistently.
Variations: horizontal → vertical Balance Sheet (Sachin); unarranged list of balances (Ambani); Common-size P&L (never asked); comparative common-size (two years side by side, SN3); items given without a total (student computes it); a P&L in T-form to convert first (XN1).', NULL, NULL, NULL, 37, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'ca0f7bfd-42a9-449a-b18a-f3bda005d1f9', '{"blocks":[{"id":"amd-u1-c37-q-1","text":"What mistakes are made in Common-size problems, and how can the question be varied?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c37-1","type":"bulletList","items":["Mistakes: (1) using assets side total only for one side and forgetting the other side is also 100%; (2) treating preference capital as a liability (it is shareholders'' funds); (3) not classifying (prepaid expenses, misc. current assets, bills payable placed wrongly); (4) not verifying the two totals are equal; (5) using sales as the base for a Balance Sheet; (6) forcing totals to 100.00 by \"adjusting\" a wrong item; (7) no vertical presentation; (8) percentages to 0/1 decimal inconsistently.","Variations: horizontal → vertical Balance Sheet (Sachin); unarranged list of balances (Ambani); Common-size P&L (never asked); comparative common-size (two years side by side, SN3); items given without a total (student computes it); a P&L in T-form to convert first (XN1)."]}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('94b1d6bb-b2c5-4946-ae00-a1b5454326cf', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Prepare a Common-size Balance Sheet of Ambani Ltd in vertical form. Balances as on 31/3/2025: (7.5 marks)', 'Priority: Tier 1', 'Concept

Classification + vertical arrangement + Common-size % (base = Balance Sheet total).

Formula

Common-size % = (Item ÷ Total of Balance Sheet) × 100

Given

Total assets = 4,00,000 + 6,00,000 + 1,00,000 + 20,000 + 40,000 + 10,000 + 90,000 + 8,000 + 2,000 = 12,70,000.
Total liabilities = 5,00,000 + 3,00,000 + 1,60,000 + 2,00,000 + 85,000 + 15,000 + 10,000 = 12,70,000 ✔.
Base = 12,70,000 = 100%.

Solution

Particulars | ₹ | % of Total
I. SOURCES OF FUNDS |  | 
(1) Shareholders'' funds |  | 
Equity share capital | 5,00,000 | 39.37
6% Preference share capital | 3,00,000 | 23.62
Reserves & surplus: General reserves | 1,60,000 | 12.60
Reserves & surplus: P&L A/c (Cr) | 2,00,000 | 15.75
Total shareholders'' funds | 11,60,000 | 91.34
(2) Current liabilities |  | 
Creditors | 85,000 | 6.69
Bills payable | 15,000 | 1.18
Outstanding expenses | 10,000 | 0.79
Total current liabilities | 1,10,000 | 8.66
TOTAL (I) | 12,70,000 | 100.00
II. APPLICATION OF FUNDS |  | 
(1) Fixed assets |  | 
Land and building | 4,00,000 | 31.50
Plant and machinery | 6,00,000 | 47.24
Motor car | 1,00,000 | 7.87
Total fixed assets | 11,00,000 | 86.61
(2) Current assets |  | 
Inventories | 40,000 | 3.15
Debtors | 20,000 | 1.57
Cash | 10,000 | 0.79
Bank balance | 90,000 | 7.09
Prepaid expenses | 8,000 | 0.63
Misc. current assets | 2,000 | 0.16
Total current assets | 1,70,000 | 13.39
TOTAL (II) | 12,70,000 | 100.00

Sample workings: Equity = 5,00,000 ÷ 12,70,000 × 100 = 39.37 · P&L (Cr) = 2,00,000 ÷ 12,70,000 × 100 = 15.75 · Plant & machinery = 6,00,000 ÷ 12,70,000 × 100 = 47.24 · Bank = 90,000 ÷ 12,70,000 × 100 = 7.09.

Final Answer

Common-size Balance Sheet as above: shareholders'' funds 91.34%, current liabilities 8.66%; fixed assets 86.61%, current assets 13.39%.

Interpretation

91.34% of funds are owner''s funds and there is no long-term borrowing: a very low-risk capital structure.
86.61% is locked in fixed assets (machinery alone 47.24%); current assets are only 13.39% against current liabilities of 8.66%, so liquidity is adequate but not large. Cash + bank is about 7.9% of the total.
Reserves (28.35% in total) show a history of profit retention.

Exam Tip

The paper gave a jumbled list, so half the marks are in classification (6% preference capital is equity side, prepaid expenses and misc. current assets are current assets, P&L credit balance is reserves). Total both sides first; if they disagree, you have misclassified something.', NULL, NULL, NULL, 38, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'ca0f7bfd-42a9-449a-b18a-f3bda005d1f9', '{"blocks":[{"id":"amd-u1-c38-q-1","text":"Prepare a Common-size Balance Sheet of Ambani Ltd in vertical form. Balances as on 31/3/2025: (7.5 marks)","type":"text","style":"paragraph"},{"id":"amd-u1-c38-q-extra-1","rows":[["Particulars","₹","Particulars","₹"],["Land and building","4,00,000","Equity share capital","5,00,000"],["Plant and machinery","6,00,000","6% Preference share capital","3,00,000"],["Motor car","1,00,000","General reserves","1,60,000"],["Debtors","20,000","P&L A/c (credit balance)","2,00,000"],["Inventories","40,000","Creditors","85,000"],["Cash","10,000","Bills payable","15,000"],["Bank balance","90,000","O/s expenses","10,000"],["Prepaid expenses","8,000","",""],["Misc. current assets","2,000","",""]],"type":"table"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c38-1","bold":true,"text":"Concept","type":"text","style":"heading"},{"id":"amd-u1-c38-2","type":"formula","expression":"Classification + vertical arrangement + Common-size % (base = Balance Sheet total)."},{"id":"amd-u1-c38-3","bold":true,"text":"Formula","type":"text","style":"heading"},{"id":"amd-u1-c38-4","type":"formula","expression":"Common-size % = (Item ÷ Total of Balance Sheet) × 100"},{"id":"amd-u1-c38-5","bold":true,"text":"Given","type":"text","style":"heading"},{"id":"amd-u1-c38-6","type":"bulletList","items":["Total assets = 4,00,000 + 6,00,000 + 1,00,000 + 20,000 + 40,000 + 10,000 + 90,000 + 8,000 + 2,000 = 12,70,000.","Total liabilities = 5,00,000 + 3,00,000 + 1,60,000 + 2,00,000 + 85,000 + 15,000 + 10,000 = 12,70,000 ✔.","Base = 12,70,000 = 100%."]},{"id":"amd-u1-c38-7","bold":true,"text":"Solution","type":"text","style":"heading"},{"id":"amd-u1-c38-8","rows":[["Particulars","₹","% of Total"],["I. SOURCES OF FUNDS","",""],["(1) Shareholders'' funds","",""],["Equity share capital","5,00,000","39.37"],["6% Preference share capital","3,00,000","23.62"],["Reserves & surplus: General reserves","1,60,000","12.60"],["Reserves & surplus: P&L A/c (Cr)","2,00,000","15.75"],["Total shareholders'' funds","11,60,000","91.34"],["(2) Current liabilities","",""],["Creditors","85,000","6.69"],["Bills payable","15,000","1.18"],["Outstanding expenses","10,000","0.79"],["Total current liabilities","1,10,000","8.66"],["TOTAL (I)","12,70,000","100.00"],["II. APPLICATION OF FUNDS","",""],["(1) Fixed assets","",""],["Land and building","4,00,000","31.50"],["Plant and machinery","6,00,000","47.24"],["Motor car","1,00,000","7.87"],["Total fixed assets","11,00,000","86.61"],["(2) Current assets","",""],["Inventories","40,000","3.15"],["Debtors","20,000","1.57"],["Cash","10,000","0.79"],["Bank balance","90,000","7.09"],["Prepaid expenses","8,000","0.63"],["Misc. current assets","2,000","0.16"],["Total current assets","1,70,000","13.39"],["TOTAL (II)","12,70,000","100.00"]],"type":"table"},{"id":"amd-u1-c38-9","type":"formula","expression":"Sample workings: Equity = 5,00,000 ÷ 12,70,000 × 100 = 39.37 · P&L (Cr) = 2,00,000 ÷ 12,70,000 × 100 = 15.75 · Plant & machinery = 6,00,000 ÷ 12,70,000 × 100 = 47.24 · Bank = 90,000 ÷ 12,70,000 × 100 = 7.09."},{"id":"amd-u1-c38-10","bold":true,"text":"Final Answer","type":"text","style":"heading"},{"id":"amd-u1-c38-11","text":"Common-size Balance Sheet as above: shareholders'' funds 91.34%, current liabilities 8.66%; fixed assets 86.61%, current assets 13.39%.","type":"text","style":"paragraph"},{"id":"amd-u1-c38-12","bold":true,"text":"Interpretation","type":"text","style":"heading"},{"id":"amd-u1-c38-13","type":"bulletList","items":["91.34% of funds are owner''s funds and there is no long-term borrowing: a very low-risk capital structure.","86.61% is locked in fixed assets (machinery alone 47.24%); current assets are only 13.39% against current liabilities of 8.66%, so liquidity is adequate but not large. Cash + bank is about 7.9% of the total.","Reserves (28.35% in total) show a history of profit retention."]},{"id":"amd-u1-c38-14","bold":true,"text":"Exam Tip","type":"text","style":"heading"},{"id":"amd-u1-c38-15","text":"The paper gave a jumbled list, so half the marks are in classification (6% preference capital is equity side, prepaid expenses and misc. current assets are current assets, P&L credit balance is reserves). Total both sides first; if they disagree, you have misclassified something.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('b77c70a0-e3b3-4c66-a349-fd4b56a14aff', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'The Balance Sheet of M/s Sachin Ltd as on 31 March 2021 is given. Prepare a common-size Balance Sheet in vertical form. (8 marks)', 'Priority: Tier 1', 'Concept

Convert horizontal Balance Sheet to vertical; Common-size %.

Formula

Common-size % = (Item ÷ 9,00,000) × 100

Given

Base = Balance Sheet total 9,00,000 = 100%. Asset total check: 2,00,000 + 2,50,000 + 2,00,000 + 90,000 + 35,000 + 50,000 + 40,000 + 30,000 + 5,000 = 9,00,000 ✔.

Solution

Particulars | ₹ | % of Total
I. SOURCES OF FUNDS |  | 
Shareholders'' funds |  | 
Equity share capital | 2,50,000 | 27.78
10% Preference share capital | 1,50,000 | 16.67
General reserve | 2,00,000 | 22.22
Total shareholders'' funds | 6,00,000 | 66.67
Non-current liabilities |  | 
8% Debentures | 1,50,000 | 16.67
Current liabilities |  | 
Creditors | 1,00,000 | 11.11
Bills payable | 50,000 | 5.56
Total current liabilities | 1,50,000 | 16.67
TOTAL | 9,00,000 | 100.00*
II. APPLICATION OF FUNDS |  | 
Fixed assets |  | 
Land and building | 2,00,000 | 22.22
Machinery | 2,50,000 | 27.78
Furniture | 2,00,000 | 22.22
Total fixed assets | 6,50,000 | 72.22
Investments | 90,000 | 10.00
Current assets |  | 
Stock | 35,000 | 3.89
Debtors | 50,000 | 5.56
Bills receivable | 30,000 | 3.33
Cash | 40,000 | 4.44
Total current assets | 1,55,000 | 17.22
Miscellaneous expenditure |  | 
Preliminary expenses | 5,000 | 0.56
TOTAL | 9,00,000 | 100.00

*The three group percentages (66.67 + 16.67 + 16.67) add to 100.01 because of rounding; state "rounding difference" if asked.

Sample workings: 2,50,000 ÷ 9,00,000 × 100 = 27.78 · 1,50,000 ÷ 9,00,000 × 100 = 16.67 · 35,000 ÷ 9,00,000 × 100 = 3.89 · 5,000 ÷ 9,00,000 × 100 = 0.56.

Final Answer

Shareholders'' funds 66.67%, debentures 16.67%, current liabilities 16.67%; fixed assets 72.22%, investments 10.00%, current assets 17.22%, preliminary expenses 0.56%.

Interpretation

Two-thirds of funds are owner''s funds; one-third is outside funds (debentures + current liabilities); a balanced capital structure.
72.22% of the money is in fixed assets, mostly financed by long-term funds (shareholders'' funds 66.67% + debentures 16.67% ≈ 83.3%).
Liquidity is tight: current assets 17.22% barely exceed current liabilities 16.67% (about 1.03 : 1).

Exam Tip

With 9,00,000 the percentages are recurring decimals, so use 2 decimals consistently and expect a ±0.01 total difference. Preliminary expenses are fictitious: show them separately (last).', NULL, NULL, NULL, 39, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'ca0f7bfd-42a9-449a-b18a-f3bda005d1f9', '{"blocks":[{"id":"amd-u1-c39-q-1","text":"The Balance Sheet of M/s Sachin Ltd as on 31 March 2021 is given. Prepare a common-size Balance Sheet in vertical form. (8 marks)","type":"text","style":"paragraph"},{"id":"amd-u1-c39-q-extra-1","rows":[["Liabilities","₹","Assets","₹"],["Equity Share Capital","2,50,000","Land and Building","2,00,000"],["10% Preference Share Capital","1,50,000","Machinery","2,50,000"],["General Reserve","2,00,000","Furniture","2,00,000"],["8% Debentures","1,50,000","Investment","90,000"],["Creditors","1,00,000","Stock","35,000"],["Bills Payable","50,000","Debtors","50,000"],["","","Cash","40,000"],["","","Bills Receivable","30,000"],["","","Preliminary Expenses","5,000"],["Total","9,00,000","Total","9,00,000"]],"type":"table"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c39-1","bold":true,"text":"Concept","type":"text","style":"heading"},{"id":"amd-u1-c39-2","text":"Convert horizontal Balance Sheet to vertical; Common-size %.","type":"text","style":"paragraph"},{"id":"amd-u1-c39-3","bold":true,"text":"Formula","type":"text","style":"heading"},{"id":"amd-u1-c39-4","type":"formula","expression":"Common-size % = (Item ÷ 9,00,000) × 100"},{"id":"amd-u1-c39-5","bold":true,"text":"Given","type":"text","style":"heading"},{"id":"amd-u1-c39-6","type":"formula","expression":"Base = Balance Sheet total 9,00,000 = 100%. Asset total check: 2,00,000 + 2,50,000 + 2,00,000 + 90,000 + 35,000 + 50,000 + 40,000 + 30,000 + 5,000 = 9,00,000 ✔."},{"id":"amd-u1-c39-7","bold":true,"text":"Solution","type":"text","style":"heading"},{"id":"amd-u1-c39-8","rows":[["Particulars","₹","% of Total"],["I. SOURCES OF FUNDS","",""],["Shareholders'' funds","",""],["Equity share capital","2,50,000","27.78"],["10% Preference share capital","1,50,000","16.67"],["General reserve","2,00,000","22.22"],["Total shareholders'' funds","6,00,000","66.67"],["Non-current liabilities","",""],["8% Debentures","1,50,000","16.67"],["Current liabilities","",""],["Creditors","1,00,000","11.11"],["Bills payable","50,000","5.56"],["Total current liabilities","1,50,000","16.67"],["TOTAL","9,00,000","100.00*"],["II. APPLICATION OF FUNDS","",""],["Fixed assets","",""],["Land and building","2,00,000","22.22"],["Machinery","2,50,000","27.78"],["Furniture","2,00,000","22.22"],["Total fixed assets","6,50,000","72.22"],["Investments","90,000","10.00"],["Current assets","",""],["Stock","35,000","3.89"],["Debtors","50,000","5.56"],["Bills receivable","30,000","3.33"],["Cash","40,000","4.44"],["Total current assets","1,55,000","17.22"],["Miscellaneous expenditure","",""],["Preliminary expenses","5,000","0.56"],["TOTAL","9,00,000","100.00"]],"type":"table"},{"id":"amd-u1-c39-9","text":"*The three group percentages (66.67 + 16.67 + 16.67) add to 100.01 because of rounding; state \"rounding difference\" if asked.","type":"text","style":"paragraph"},{"id":"amd-u1-c39-10","type":"formula","expression":"Sample workings: 2,50,000 ÷ 9,00,000 × 100 = 27.78 · 1,50,000 ÷ 9,00,000 × 100 = 16.67 · 35,000 ÷ 9,00,000 × 100 = 3.89 · 5,000 ÷ 9,00,000 × 100 = 0.56."},{"id":"amd-u1-c39-11","bold":true,"text":"Final Answer","type":"text","style":"heading"},{"id":"amd-u1-c39-12","text":"Shareholders'' funds 66.67%, debentures 16.67%, current liabilities 16.67%; fixed assets 72.22%, investments 10.00%, current assets 17.22%, preliminary expenses 0.56%.","type":"text","style":"paragraph"},{"id":"amd-u1-c39-13","bold":true,"text":"Interpretation","type":"text","style":"heading"},{"id":"amd-u1-c39-14","type":"bulletList","items":["Two-thirds of funds are owner''s funds; one-third is outside funds (debentures + current liabilities); a balanced capital structure.","72.22% of the money is in fixed assets, mostly financed by long-term funds (shareholders'' funds 66.67% + debentures 16.67% ≈ 83.3%).","Liquidity is tight: current assets 17.22% barely exceed current liabilities 16.67% (about 1.03 : 1)."]},{"id":"amd-u1-c39-15","bold":true,"text":"Exam Tip","type":"text","style":"heading"},{"id":"amd-u1-c39-16","text":"With 9,00,000 the percentages are recurring decimals, so use 2 decimals consistently and expect a ±0.01 total difference. Preliminary expenses are fictitious: show them separately (last).","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('8d182f64-10c1-4951-9a84-b95dad1a7af8', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Using the Oct 2025 Q1.2 data (see CN1), prepare a common-size income statement for 2023 and 2024 (each item as % of sales) and comment.', 'Priority: Tier 2 (Common-size P&L is an unasked cell of the matrix)', 'Concept

Common-size P&L, base = Net Sales = 100%. Also the alternate reading of "Comparative Size Statement".

Formula

% of sales = (Item ÷ Sales of the same year) × 100

Given

Base 2023 = 36,00,000; base 2024 = 43,20,000. (Printed 2023 PBT 1,95,000 used as in the paper.)

Solution

Particulars | 2023 ₹ | 2023 % | 2024 ₹ | 2024 %
Sales | 36,00,000 | 100.00 | 43,20,000 | 100.00
Less: Cost of Sales | 23,00,000 | 63.89 | 28,00,000 | 64.81
Gross Margin | 13,00,000 | 36.11 | 15,20,000 | 35.19
Management Expense | 2,00,000 | 5.56 | 2,25,000 | 5.21
Sales Expense | 3,60,000 | 10.00 | 4,32,000 | 10.00
Interest on Borrowing | 2,50,000 | 6.94 | 3,00,000 | 6.94
Total Expenses | 8,10,000 | 22.50 | 9,57,000 | 22.15
NP before Dep. & Tax | 4,90,000 | 13.61 | 5,63,000 | 13.03
Depreciation | 3,00,000 | 8.33 | 3,25,000 | 7.52
Profit before Tax | 1,95,000 | 5.42 | 2,38,000 | 5.51
Income Tax | 95,000 | 2.64 | 1,28,000 | 2.96
Profit after Tax | 1,00,000 | 2.78 | 1,10,000 | 2.55

Sample workings: 23,00,000 ÷ 36,00,000 × 100 = 63.89 · 28,00,000 ÷ 43,20,000 × 100 = 64.81 · 2,38,000 ÷ 43,20,000 × 100 = 5.51 · 1,10,000 ÷ 43,20,000 × 100 = 2.55.

Final Answer

Common-size statement as tabulated. Gross margin 36.11% → 35.19%; PBT margin 5.42% → 5.51%; PAT margin 2.78% → 2.55%.

Interpretation

Cost of sales rose from 63.89% to 64.81% of sales (gross margin shrank ≈0.9 points). Overheads were absorbed better (total expenses 22.50% → 22.15%; depreciation 8.33% → 7.52%), so PBT margin edged up. Higher tax (2.64% → 2.96% of sales) pulled the PAT margin down.

Exam Tip

Each year uses its own sales as 100%, never one year''s sales for both.', NULL, NULL, NULL, 40, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'ca0f7bfd-42a9-449a-b18a-f3bda005d1f9', '{"blocks":[{"id":"amd-u1-c40-q-1","text":"Using the Oct 2025 Q1.2 data (see CN1), prepare a common-size income statement for 2023 and 2024 (each item as % of sales) and comment.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c40-1","bold":true,"text":"Concept","type":"text","style":"heading"},{"id":"amd-u1-c40-2","type":"formula","expression":"Common-size P&L, base = Net Sales = 100%. Also the alternate reading of \"Comparative Size Statement\"."},{"id":"amd-u1-c40-3","bold":true,"text":"Formula","type":"text","style":"heading"},{"id":"amd-u1-c40-4","type":"formula","expression":"% of sales = (Item ÷ Sales of the same year) × 100"},{"id":"amd-u1-c40-5","bold":true,"text":"Given","type":"text","style":"heading"},{"id":"amd-u1-c40-6","type":"formula","expression":"Base 2023 = 36,00,000; base 2024 = 43,20,000. (Printed 2023 PBT 1,95,000 used as in the paper.)"},{"id":"amd-u1-c40-7","bold":true,"text":"Solution","type":"text","style":"heading"},{"id":"amd-u1-c40-8","rows":[["Particulars","2023 ₹","2023 %","2024 ₹","2024 %"],["Sales","36,00,000","100.00","43,20,000","100.00"],["Less: Cost of Sales","23,00,000","63.89","28,00,000","64.81"],["Gross Margin","13,00,000","36.11","15,20,000","35.19"],["Management Expense","2,00,000","5.56","2,25,000","5.21"],["Sales Expense","3,60,000","10.00","4,32,000","10.00"],["Interest on Borrowing","2,50,000","6.94","3,00,000","6.94"],["Total Expenses","8,10,000","22.50","9,57,000","22.15"],["NP before Dep. & Tax","4,90,000","13.61","5,63,000","13.03"],["Depreciation","3,00,000","8.33","3,25,000","7.52"],["Profit before Tax","1,95,000","5.42","2,38,000","5.51"],["Income Tax","95,000","2.64","1,28,000","2.96"],["Profit after Tax","1,00,000","2.78","1,10,000","2.55"]],"type":"table"},{"id":"amd-u1-c40-9","type":"formula","expression":"Sample workings: 23,00,000 ÷ 36,00,000 × 100 = 63.89 · 28,00,000 ÷ 43,20,000 × 100 = 64.81 · 2,38,000 ÷ 43,20,000 × 100 = 5.51 · 1,10,000 ÷ 43,20,000 × 100 = 2.55."},{"id":"amd-u1-c40-10","bold":true,"text":"Final Answer","type":"text","style":"heading"},{"id":"amd-u1-c40-11","text":"Common-size statement as tabulated. Gross margin 36.11% → 35.19%; PBT margin 5.42% → 5.51%; PAT margin 2.78% → 2.55%.","type":"text","style":"paragraph"},{"id":"amd-u1-c40-12","bold":true,"text":"Interpretation","type":"text","style":"heading"},{"id":"amd-u1-c40-13","text":"Cost of sales rose from 63.89% to 64.81% of sales (gross margin shrank ≈0.9 points). Overheads were absorbed better (total expenses 22.50% → 22.15%; depreciation 8.33% → 7.52%), so PBT margin edged up. Higher tax (2.64% → 2.96% of sales) pulled the PAT margin down.","type":"text","style":"paragraph"},{"id":"amd-u1-c40-14","bold":true,"text":"Exam Tip","type":"text","style":"heading"},{"id":"amd-u1-c40-15","text":"Each year uses its own sales as 100%, never one year''s sales for both.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('9b351d93-97fd-4374-b83b-8a8c6eb91bba', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Distinguish between Trend Analysis, Comparative Statement and Common Size Statement. Which are horizontal and which vertical?', 'Priority: Tier 1 (a classic "Distinguish/Explain" question that combines all three) | PYQ Connection: Not asked verbatim, but each technique is tested individually in both papers.', 'Basis | Trend Analysis | Comparative Statement | Common Size Statement
Type | Horizontal | Horizontal | Vertical
Years used | 3 or more | 2 (or more, adjacent) | One (or several, each compared to its own base)
Base | One fixed base year = 100 | Previous year for each change | Total of the same year (Total assets / Net sales) = 100
Output | Trend % (index) | Absolute + % change | % of total/sales
Shows | Direction and rate of growth over time | Amount and rate of change year to year | Structure/composition of items
Best for | Long-term movement, forecasting | Year-to-year performance | Comparing firms of different size; asset/cost mix
PYQ evidence | 2022 (BS), 2025 (P&L) | 2025 (P&L) | 2022 (BS), 2025 (BS)', NULL, NULL, NULL, 41, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', '6736ba0e-5150-4445-b875-016e5190f110', '{"blocks":[{"id":"amd-u1-c41-q-1","text":"Distinguish between Trend Analysis, Comparative Statement and Common Size Statement. Which are horizontal and which vertical?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c41-1","rows":[["Basis","Trend Analysis","Comparative Statement","Common Size Statement"],["Type","Horizontal","Horizontal","Vertical"],["Years used","3 or more","2 (or more, adjacent)","One (or several, each compared to its own base)"],["Base","One fixed base year = 100","Previous year for each change","Total of the same year (Total assets / Net sales) = 100"],["Output","Trend % (index)","Absolute + % change","% of total/sales"],["Shows","Direction and rate of growth over time","Amount and rate of change year to year","Structure/composition of items"],["Best for","Long-term movement, forecasting","Year-to-year performance","Comparing firms of different size; asset/cost mix"],["PYQ evidence","2022 (BS), 2025 (P&L)","2025 (P&L)","2022 (BS), 2025 (BS)"]],"type":"table"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('32cd077f-990d-4cdf-9793-7d60ff578c26', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'State the limitations of analysis and interpretation of financial statements.', 'Priority: Tier 3 | PYQ Connection: Not in supplied papers; likely short-note material.', 'Based on historical cost and past data; may not predict the future.
Ignores inflation and price-level changes.
Accounting policies differ (depreciation, stock valuation), so inter-firm comparison misleads.
Window dressing can distort statements.
Ignores qualitative factors (management quality, morale, market conditions).
Percentages can mislead when the base is small or abnormal.
Analysis shows what changed, not why; interpretation depends on the analyst''s judgement.
No universal standard to judge whether a % is "good".', NULL, NULL, NULL, 42, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', '6736ba0e-5150-4445-b875-016e5190f110', '{"blocks":[{"id":"amd-u1-c42-q-1","text":"State the limitations of analysis and interpretation of financial statements.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c42-1","type":"numberList","items":["Based on historical cost and past data; may not predict the future.","Ignores inflation and price-level changes.","Accounting policies differ (depreciation, stock valuation), so inter-firm comparison misleads.","Window dressing can distort statements.","Ignores qualitative factors (management quality, morale, market conditions).","Percentages can mislead when the base is small or abnormal.","Analysis shows what changed, not why; interpretation depends on the analyst''s judgement.","No universal standard to judge whether a % is \"good\"."]}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('59c76ef9-04e9-44c9-a23d-bc0eba989a7a', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'How do you decide, from the wording of the question, which technique is required?', 'Priority: Tier 2 | PYQ Connection: 2025 Q1 offered all three in one question, so choosing correctly is itself the skill being tested.', 'Clue in the question | Technique
Three or more years; "trend", "base year", "index" | Trend Analysis
Two years; "comparative", "increase/decrease", "change" | Comparative Statement
One year; "common size", "as % of total/sales", "vertical" | Common Size Statement
"Comparative size" | Ambiguous: give the comparative statement and state the common-size % (see CN1 and SN3)
Horizontal T-form account given | First convert to vertical form, then apply the technique', NULL, NULL, NULL, 43, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', '6736ba0e-5150-4445-b875-016e5190f110', '{"blocks":[{"id":"amd-u1-c43-q-1","text":"How do you decide, from the wording of the question, which technique is required?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c43-1","rows":[["Clue in the question","Technique"],["Three or more years; \"trend\", \"base year\", \"index\"","Trend Analysis"],["Two years; \"comparative\", \"increase/decrease\", \"change\"","Comparative Statement"],["One year; \"common size\", \"as % of total/sales\", \"vertical\"","Common Size Statement"],["\"Comparative size\"","Ambiguous: give the comparative statement and state the common-size % (see CN1 and SN3)"],["Horizontal T-form account given","First convert to vertical form, then apply the technique"]],"type":"table"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('00774b71-aec6-4e77-a390-157d5ae91eeb', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What must a full-marks answer to a Unit 1 numerical contain?', 'Priority: Tier 2', 'Vertical form with proper classification (Sources/Application; Sales → PAT).
₹ figures and % side by side.
Formula written once at the top.
Base clearly stated (base year / total assets / net sales).
Totals cross-checked (two sides equal; sub-items add up).
2-decimal percentages, consistent.
Working notes for 2–3 representative lines.
2–4 line interpretation even if not asked.
Note any data discrepancy in the paper.', NULL, NULL, NULL, 44, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', '6736ba0e-5150-4445-b875-016e5190f110', '{"blocks":[{"id":"amd-u1-c44-q-1","text":"What must a full-marks answer to a Unit 1 numerical contain?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c44-1","type":"numberList","items":["Vertical form with proper classification (Sources/Application; Sales → PAT).","₹ figures and % side by side.","Formula written once at the top.","Base clearly stated (base year / total assets / net sales).","Totals cross-checked (two sides equal; sub-items add up).","2-decimal percentages, consistent.","Working notes for 2–3 representative lines.","2–4 line interpretation even if not asked.","Note any data discrepancy in the paper."]}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('d5203715-233c-426d-b5df-a06e9a88b70b', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Following is the revenue statement of Lavanya Enterprises. Convert it into an income statement (vertical form) and calculate: (1) Gross profit ratio (2) Operating ratio (3) Stock turnover ratio (4) Selling expense ratio (5) Net profit before tax ratio. (7.5 marks)', 'Priority: Tier 3 for the ratios (other unit); Tier 1 for the conversion skill', 'Concept

Re-arranging a T-form account into a vertical income statement (Unit 1 skill: "forms of P&L suitable for analysis"); ratios are from the Ratio Analysis unit and shown only to complete the question.

Formula

COGS = Opening stock + Purchases + Carriage inward − Closing stock · Gross profit = Sales − COGS · Operating profit = Gross profit − Operating expenses · PBT = Operating profit + Non-operating income − Non-operating expense

Given

Debit side total: 60,000 + 2,30,000 + 10,000 + 30,000 + 20,000 + 6,000 + 2,54,000 = 6,10,000 ✔.

Solution

Particulars | ₹ | % of Sales
Sales | 5,00,000 | 100.0
Less: Cost of goods sold: |  | 
Opening stock | 60,000 | 
Add: Purchases | 2,30,000 | 
Add: Carriage inward | 10,000 | 
 | 3,00,000 | 
Less: Closing stock | (1,00,000) | 
COGS | 2,00,000 | 40.0
Gross profit | 3,00,000 | 60.0
Less: Operating expenses: |  | 
Office expenses | 30,000 | 
Sales expenses | 20,000 | 
Total operating expenses | 50,000 | 10.0
Operating profit | 2,50,000 | 50.0
Add: Interest received on investments | 10,000 | 
Less: Loss on sale of fixed assets | (6,000) | 
Net profit before tax | 2,54,000 | 50.8

Ties to the account''s balancing figure ✔ (2,54,000).

Ratios

Gross profit ratio = 3,00,000 ÷ 5,00,000 × 100 = 60%
Operating ratio = (COGS + Operating expenses) ÷ Sales × 100 = (2,00,000 + 50,000) ÷ 5,00,000 × 100 = 50%
Stock turnover = COGS ÷ Average stock = 2,00,000 ÷ [(60,000 + 1,00,000) ÷ 2 = 80,000] = 2.5 times
Selling expense ratio = 20,000 ÷ 5,00,000 × 100 = 4%
Net profit before tax ratio = 2,54,000 ÷ 5,00,000 × 100 = 50.8%

Final Answer

Vertical income statement as above; ratios 60%, 50%, 2.5 times, 4%, 50.8%.

Interpretation

Half of every rupee of sales is left as operating profit; non-operating items (interest received, loss on sale of assets) barely change the result (net +4,000).

Exam Tip

Closing stock is deducted inside COGS (it sits on the credit side of a T-form account but is not "income"). Interest received and loss on sale of assets are non-operating and go after operating profit. Most students err by adding closing stock to sales.', NULL, NULL, NULL, 45, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'e202e5d6-0a84-492c-ac46-fd1c049534f1', '{"blocks":[{"id":"amd-u1-c45-q-1","text":"Following is the revenue statement of Lavanya Enterprises. Convert it into an income statement (vertical form) and calculate: (1) Gross profit ratio (2) Operating ratio (3) Stock turnover ratio (4) Selling expense ratio (5) Net profit before tax ratio. (7.5 marks)","type":"text","style":"paragraph"},{"id":"amd-u1-c45-q-extra-1","rows":[["Particulars","₹","Particulars","₹"],["To Opening Stock","60,000","By Sales","5,00,000"],["To Purchase","2,30,000","By Closing Stock","1,00,000"],["To Carriage Inward","10,000","By Interest received on investments","10,000"],["To Office Expenses","30,000","",""],["To Sales Expenses","20,000","",""],["To Loss on sale of Fixed Assets","6,000","",""],["To Net Profit c/d","2,54,000","",""],["Total","6,10,000","Total","6,10,000"]],"type":"table"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c45-1","bold":true,"text":"Concept","type":"text","style":"heading"},{"id":"amd-u1-c45-2","text":"Re-arranging a T-form account into a vertical income statement (Unit 1 skill: \"forms of P&L suitable for analysis\"); ratios are from the Ratio Analysis unit and shown only to complete the question.","type":"text","style":"paragraph"},{"id":"amd-u1-c45-3","bold":true,"text":"Formula","type":"text","style":"heading"},{"id":"amd-u1-c45-4","type":"formula","expression":"COGS = Opening stock + Purchases + Carriage inward − Closing stock · Gross profit = Sales − COGS · Operating profit = Gross profit − Operating expenses · PBT = Operating profit + Non-operating income − Non-operating expense"},{"id":"amd-u1-c45-5","bold":true,"text":"Given","type":"text","style":"heading"},{"id":"amd-u1-c45-6","type":"formula","expression":"Debit side total: 60,000 + 2,30,000 + 10,000 + 30,000 + 20,000 + 6,000 + 2,54,000 = 6,10,000 ✔."},{"id":"amd-u1-c45-7","bold":true,"text":"Solution","type":"text","style":"heading"},{"id":"amd-u1-c45-8","rows":[["Particulars","₹","% of Sales"],["Sales","5,00,000","100.0"],["Less: Cost of goods sold:","",""],["Opening stock","60,000",""],["Add: Purchases","2,30,000",""],["Add: Carriage inward","10,000",""],["","3,00,000",""],["Less: Closing stock","(1,00,000)",""],["COGS","2,00,000","40.0"],["Gross profit","3,00,000","60.0"],["Less: Operating expenses:","",""],["Office expenses","30,000",""],["Sales expenses","20,000",""],["Total operating expenses","50,000","10.0"],["Operating profit","2,50,000","50.0"],["Add: Interest received on investments","10,000",""],["Less: Loss on sale of fixed assets","(6,000)",""],["Net profit before tax","2,54,000","50.8"]],"type":"table"},{"id":"amd-u1-c45-9","text":"Ties to the account''s balancing figure ✔ (2,54,000).","type":"text","style":"paragraph"},{"id":"amd-u1-c45-10","bold":true,"text":"Ratios","type":"text","style":"heading"},{"id":"amd-u1-c45-11","type":"numberList","items":["Gross profit ratio = 3,00,000 ÷ 5,00,000 × 100 = 60%","Operating ratio = (COGS + Operating expenses) ÷ Sales × 100 = (2,00,000 + 50,000) ÷ 5,00,000 × 100 = 50%","Stock turnover = COGS ÷ Average stock = 2,00,000 ÷ [(60,000 + 1,00,000) ÷ 2 = 80,000] = 2.5 times","Selling expense ratio = 20,000 ÷ 5,00,000 × 100 = 4%","Net profit before tax ratio = 2,54,000 ÷ 5,00,000 × 100 = 50.8%"]},{"id":"amd-u1-c45-12","bold":true,"text":"Final Answer","type":"text","style":"heading"},{"id":"amd-u1-c45-13","text":"Vertical income statement as above; ratios 60%, 50%, 2.5 times, 4%, 50.8%.","type":"text","style":"paragraph"},{"id":"amd-u1-c45-14","bold":true,"text":"Interpretation","type":"text","style":"heading"},{"id":"amd-u1-c45-15","text":"Half of every rupee of sales is left as operating profit; non-operating items (interest received, loss on sale of assets) barely change the result (net +4,000).","type":"text","style":"paragraph"},{"id":"amd-u1-c45-16","bold":true,"text":"Exam Tip","type":"text","style":"heading"},{"id":"amd-u1-c45-17","text":"Closing stock is deducted inside COGS (it sits on the credit side of a T-form account but is not \"income\"). Interest received and loss on sale of assets are non-operating and go after operating profit. Most students err by adding closing stock to sales.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('bceb11aa-1f69-4a47-b6e8-9f01cfebea26', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Sales ₹8,00,000; Cost of goods sold ₹5,20,000; Operating expenses ₹1,20,000; Interest ₹40,000; Tax at 30% of PBT. Prepare a common-size income statement.', '', 'Solution

Particulars | ₹ | % of Sales
Sales | 8,00,000 | 100.00
Less: COGS | 5,20,000 | 65.00
Gross profit | 2,80,000 | 35.00
Less: Operating expenses | 1,20,000 | 15.00
Operating profit | 1,60,000 | 20.00
Less: Interest | 40,000 | 5.00
PBT | 1,20,000 | 15.00
Less: Tax (30% × 1,20,000) | 36,000 | 4.50
PAT | 84,000 | 10.50

Exam Tip

Compute tax on PBT (not on sales) before the % step.', NULL, NULL, NULL, 46, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'ba48ec7b-c5b7-4d37-82fb-86251293a65f', '{"blocks":[{"id":"amd-u1-c46-q-1","text":"Sales ₹8,00,000; Cost of goods sold ₹5,20,000; Operating expenses ₹1,20,000; Interest ₹40,000; Tax at 30% of PBT. Prepare a common-size income statement.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c46-1","bold":true,"text":"Solution","type":"text","style":"heading"},{"id":"amd-u1-c46-2","rows":[["Particulars","₹","% of Sales"],["Sales","8,00,000","100.00"],["Less: COGS","5,20,000","65.00"],["Gross profit","2,80,000","35.00"],["Less: Operating expenses","1,20,000","15.00"],["Operating profit","1,60,000","20.00"],["Less: Interest","40,000","5.00"],["PBT","1,20,000","15.00"],["Less: Tax (30% × 1,20,000)","36,000","4.50"],["PAT","84,000","10.50"]],"type":"table"},{"id":"amd-u1-c46-3","bold":true,"text":"Exam Tip","type":"text","style":"heading"},{"id":"amd-u1-c46-4","text":"Compute tax on PBT (not on sales) before the % step.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('e2a8ba14-6ee5-4b1e-ab40-3d611550f75c', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What is the formula for Current Ratio?', '', 'Current Ratio = Current Assets ÷ Current Liabilities

Expressed as: X : 1 (e.g., 2:1 means ₹2 of current assets for every ₹1 of current liabilities)

Ideal Standard: Traditionally 2:1 is considered satisfactory, though industry norms vary.', NULL, NULL, NULL, 11, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '3daef71f-b3d9-493c-8013-148426ceb854', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c11-q","text":"What is the formula for Current Ratio?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c11-1","type":"formula","expression":"Current Ratio = Current Assets ÷ Current Liabilities"},{"id":"amd-u2-c11-2","text":"Expressed as: X : 1 (e.g., 2:1 means ₹2 of current assets for every ₹1 of current liabilities)","type":"text","style":"paragraph"},{"id":"amd-u2-c11-3","text":"Ideal Standard: Traditionally 2:1 is considered satisfactory, though industry norms vary.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('1a6c5801-a39d-4ee7-9ce5-42dedee7a45e', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Sales: 2022 ₹10,00,000; 2023 ₹11,50,000; 2024 ₹9,00,000. Net profit: 2022 ₹1,00,000; 2023 ₹1,30,000; 2024 ₹60,000. Prepare trend percentages (base 2022) and comment.', '', 'Solution

Item | 2022 | 2023 | 2024
Sales trend % | 100 | 115.00 | 90.00
Net profit trend % | 100 | 130.00 | 60.00

Comment

In 2024 sales fell 10% below the base but profit fell 40%: profit falls faster than sales when costs are partly fixed (operating leverage works in reverse). A trend below 100 means a decline of (100 − trend)%.', NULL, NULL, NULL, 47, true, 'University Exam', NULL, NULL, NULL, '057b0b64-7c59-4c16-a414-1e45fe43d90f', 'ba48ec7b-c5b7-4d37-82fb-86251293a65f', '{"blocks":[{"id":"amd-u1-c47-q-1","text":"Sales: 2022 ₹10,00,000; 2023 ₹11,50,000; 2024 ₹9,00,000. Net profit: 2022 ₹1,00,000; 2023 ₹1,30,000; 2024 ₹60,000. Prepare trend percentages (base 2022) and comment.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u1-c47-1","bold":true,"text":"Solution","type":"text","style":"heading"},{"id":"amd-u1-c47-2","rows":[["Item","2022","2023","2024"],["Sales trend %","100","115.00","90.00"],["Net profit trend %","100","130.00","60.00"]],"type":"table"},{"id":"amd-u1-c47-3","bold":true,"text":"Comment","type":"text","style":"heading"},{"id":"amd-u1-c47-4","text":"In 2024 sales fell 10% below the base but profit fell 40%: profit falls faster than sales when costs are partly fixed (operating leverage works in reverse). A trend below 100 means a decline of (100 − trend)%.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:55:59.854879+00', '2026-09-21 16:55:59.854879+00'),
  ('b517d85f-ed53-4efd-9074-d2857fd8f7ad', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What is Financial Statement Analysis?', '', 'Financial Statement Analysis is the systematic process of examining, comparing, and interpreting financial statements (Balance Sheet, Revenue/Income Statement) to evaluate a

firm''s financial position, operational efficiency, profitability, and future prospects. Key Points:

It involves establishing meaningful relationships between various items of financial

statements

Primary objective: determining estimates and predictions about future conditions

Helps assess profitability, operational efficiency, and financial health

Enables users to make informed economic decisions', NULL, NULL, NULL, 1, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '6d55cb67-94d9-4576-8f71-8a7cd40fb53d', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c1-q","text":"What is Financial Statement Analysis?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c1-1","text":"Financial Statement Analysis is the systematic process of examining, comparing, and interpreting financial statements (Balance Sheet, Revenue/Income Statement) to evaluate a","type":"text","style":"paragraph"},{"id":"amd-u2-c1-2","text":"firm''s financial position, operational efficiency, profitability, and future prospects. Key Points:","type":"text","style":"paragraph"},{"id":"amd-u2-c1-3","text":"It involves establishing meaningful relationships between various items of financial","type":"text","style":"paragraph"},{"id":"amd-u2-c1-4","text":"statements","type":"text","style":"paragraph"},{"id":"amd-u2-c1-5","text":"Primary objective: determining estimates and predictions about future conditions","type":"text","style":"paragraph"},{"id":"amd-u2-c1-6","text":"Helps assess profitability, operational efficiency, and financial health","type":"text","style":"paragraph"},{"id":"amd-u2-c1-7","text":"Enables users to make informed economic decisions","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('f21b874a-7db7-4664-ac68-80aaaf59a7f6', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What are the steps involved in Financial Statement Analysis?', '', 'The systematic steps are:

Determination of Objective — Define the purpose (investment, credit, performance evaluation)

Study of Financial Statements — Examine Balance Sheet, Revenue Statement, Cash Flow Statement

Collection of Relevant Data — Extract pertinent figures from statements and notes

Rearrangement of Data — Reclassify items (current vs. non-current, operating vs. non operating)
Analysis Using Techniques — Apply tools like ratio analysis, comparative statements, trend analysis

Interpretation — Draw conclusions about financial position and performance 7. Reporting — Present findings in analytical report form for decision-making

Exam Tip: Remember the mnemonic: "Determine → Study → Collect → Rearrange → Analyze → Interpret → Report"', NULL, NULL, NULL, 2, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '6d55cb67-94d9-4576-8f71-8a7cd40fb53d', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c2-q","text":"What are the steps involved in Financial Statement Analysis?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c2-1","text":"The systematic steps are:","type":"text","style":"paragraph"},{"id":"amd-u2-c2-2","type":"numberList","items":["Determination of Objective — Define the purpose (investment, credit, performance evaluation)"]},{"id":"amd-u2-c2-3","type":"numberList","items":["Study of Financial Statements — Examine Balance Sheet, Revenue Statement, Cash Flow Statement"]},{"id":"amd-u2-c2-4","type":"numberList","items":["Collection of Relevant Data — Extract pertinent figures from statements and notes"]},{"id":"amd-u2-c2-5","type":"numberList","items":["Rearrangement of Data — Reclassify items (current vs. non-current, operating vs. non operating)","Analysis Using Techniques — Apply tools like ratio analysis, comparative statements, trend analysis"]},{"id":"amd-u2-c2-6","type":"numberList","items":["Interpretation — Draw conclusions about financial position and performance 7. Reporting — Present findings in analytical report form for decision-making"]},{"id":"amd-u2-c2-7","text":"Exam Tip: Remember the mnemonic: \"Determine → Study → Collect → Rearrange → Analyze → Interpret → Report\"","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('287f51de-3080-442e-a476-5fdf2d837b05', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What are the main objectives of Financial Statement Analysis?', '', 'Key objectives include:

Assess Profitability — Evaluate current and past profit performance

Measure Operational Efficiency — Judge how well resources are utilised Determine Financial Health — Assess solvency, liquidity, and stability Identify Trends — Detect changes in profitability/financial position over time Support Decision-Making — Aid investors, creditors, management in economic decisions Compare Performance — Benchmark against industry or competitors

Predict Future Prospects — Estimate future earnings and financial position User-Specific Objectives:

Investors: Return on investment, dividend prospects

Creditors: Ability to repay debts

Management: Operational efficiency, planning

Employees: Job security, bonus prospects', NULL, NULL, NULL, 3, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '6d55cb67-94d9-4576-8f71-8a7cd40fb53d', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c3-q","text":"What are the main objectives of Financial Statement Analysis?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c3-1","text":"Key objectives include:","type":"text","style":"paragraph"},{"id":"amd-u2-c3-2","text":"Assess Profitability — Evaluate current and past profit performance","type":"text","style":"paragraph"},{"id":"amd-u2-c3-3","text":"Measure Operational Efficiency — Judge how well resources are utilised Determine Financial Health — Assess solvency, liquidity, and stability Identify Trends — Detect changes in profitability/financial position over time Support Decision-Making — Aid investors, creditors, management in economic decisions Compare Performance — Benchmark against industry or competitors","type":"text","style":"paragraph"},{"id":"amd-u2-c3-4","text":"Predict Future Prospects — Estimate future earnings and financial position User-Specific Objectives:","type":"text","style":"paragraph"},{"id":"amd-u2-c3-5","text":"Investors: Return on investment, dividend prospects","type":"text","style":"paragraph"},{"id":"amd-u2-c3-6","text":"Creditors: Ability to repay debts","type":"text","style":"paragraph"},{"id":"amd-u2-c3-7","text":"Management: Operational efficiency, planning","type":"text","style":"paragraph"},{"id":"amd-u2-c3-8","text":"Employees: Job security, bonus prospects","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('43e65c70-01e1-46f1-90d1-728a5ef09e5d', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'How is Financial Statement Analysis classified?', '', 'Major classifications: 1. Based on Method:

Horizontal Analysis (Trend Analysis): Comparison across time periods (year-to-year) Vertical Analysis (Common-Size): Each item as % of base figure (sales/total assets) Ratio Analysis: Relationships between financial statement items

Based on Source of Data:

Internal Analysis: Using internal records (management)

External Analysis: Using published statements (investors, creditors)

Based on Purpose:

Liquidity Analysis: Short-term solvency

Profitability Analysis: Earning capacity

Solvency Analysis: Long-term stability

Activity/Efficiency Analysis: Asset utilisation

Based on Coverage:

Partial Analysis: Selected aspects

Complete Analysis: Comprehensive examination

SECTION B: RATIO ANALYSIS (Core Concepts)', NULL, NULL, NULL, 4, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '6d55cb67-94d9-4576-8f71-8a7cd40fb53d', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c4-q","text":"How is Financial Statement Analysis classified?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c4-1","text":"Major classifications: 1. Based on Method:","type":"text","style":"paragraph"},{"id":"amd-u2-c4-2","text":"Horizontal Analysis (Trend Analysis): Comparison across time periods (year-to-year) Vertical Analysis (Common-Size): Each item as % of base figure (sales/total assets) Ratio Analysis: Relationships between financial statement items","type":"text","style":"paragraph"},{"id":"amd-u2-c4-3","type":"numberList","items":["Based on Source of Data:"]},{"id":"amd-u2-c4-4","text":"Internal Analysis: Using internal records (management)","type":"text","style":"paragraph"},{"id":"amd-u2-c4-5","text":"External Analysis: Using published statements (investors, creditors)","type":"text","style":"paragraph"},{"id":"amd-u2-c4-6","type":"numberList","items":["Based on Purpose:"]},{"id":"amd-u2-c4-7","text":"Liquidity Analysis: Short-term solvency","type":"text","style":"paragraph"},{"id":"amd-u2-c4-8","text":"Profitability Analysis: Earning capacity","type":"text","style":"paragraph"},{"id":"amd-u2-c4-9","text":"Solvency Analysis: Long-term stability","type":"text","style":"paragraph"},{"id":"amd-u2-c4-10","text":"Activity/Efficiency Analysis: Asset utilisation","type":"text","style":"paragraph"},{"id":"amd-u2-c4-11","type":"numberList","items":["Based on Coverage:"]},{"id":"amd-u2-c4-12","text":"Partial Analysis: Selected aspects","type":"text","style":"paragraph"},{"id":"amd-u2-c4-13","text":"Complete Analysis: Comprehensive examination","type":"text","style":"paragraph"},{"id":"amd-u2-c4-14","text":"SECTION B: RATIO ANALYSIS (Core Concepts)","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('1bda806c-897d-4f5c-bd82-c27c6957264b', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What is Ratio Analysis?', '', 'Ratio Analysis is a quantitative technique that establishes meaningful relationships between various items of financial statements (Balance Sheet and Revenue Statement) to assess a firm''s

liquidity, profitability, solvency, and operational efficiency. Key Characteristics:

Expresses relationship between two financial figures

Can be expressed as percentage, fraction, or proportion Enables comparison across time periods or companies

Central tool in fundamental financial analysis', NULL, NULL, NULL, 5, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '1e9b673c-5335-4a3f-bdaf-ef0e7d1af22a', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c5-q","text":"What is Ratio Analysis?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c5-1","text":"Ratio Analysis is a quantitative technique that establishes meaningful relationships between various items of financial statements (Balance Sheet and Revenue Statement) to assess a firm''s","type":"text","style":"paragraph"},{"id":"amd-u2-c5-2","text":"liquidity, profitability, solvency, and operational efficiency. Key Characteristics:","type":"text","style":"paragraph"},{"id":"amd-u2-c5-3","text":"Expresses relationship between two financial figures","type":"text","style":"paragraph"},{"id":"amd-u2-c5-4","text":"Can be expressed as percentage, fraction, or proportion Enables comparison across time periods or companies","type":"text","style":"paragraph"},{"id":"amd-u2-c5-5","text":"Central tool in fundamental financial analysis","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('6c3994c7-9418-47ad-b5f7-557fc08a36e4', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'How are accounting ratios classified?', '', 'Three main classification approaches:

Traditional Classification (Based on Financial Statements):

Balance Sheet Ratios: Both figures from Balance Sheet (e.g., Current Ratio, Debt-Equity Ratio)

Revenue Statement Ratios: Both figures from Revenue Statement (e.g., Gross Profit Ratio, Net Profit Ratio)

Combined Ratios: One figure from each statement (e.g., ROCE, Stock Turnover) 2. Functional Classification (Based on Purpose):

Liquidity Ratios: Short-term solvency (Current Ratio, Quick Ratio)

Profitability Ratios: Earning capacity (Gross Profit Ratio, ROCE)

Solvency Ratios: Long-term stability (Debt-Equity, Proprietary Ratio) Activity/Turnover Ratios: Efficiency (Stock Turnover, Debtors Turnover) 3. User-Based Classification:

Management: Operational control

Investors: Return assessment

Creditors: Repayment capacity', NULL, NULL, NULL, 6, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '1e9b673c-5335-4a3f-bdaf-ef0e7d1af22a', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c6-q","text":"How are accounting ratios classified?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c6-1","text":"Three main classification approaches:","type":"text","style":"paragraph"},{"id":"amd-u2-c6-2","type":"numberList","items":["Traditional Classification (Based on Financial Statements):"]},{"id":"amd-u2-c6-3","text":"Balance Sheet Ratios: Both figures from Balance Sheet (e.g., Current Ratio, Debt-Equity Ratio)","type":"text","style":"paragraph"},{"id":"amd-u2-c6-4","text":"Revenue Statement Ratios: Both figures from Revenue Statement (e.g., Gross Profit Ratio, Net Profit Ratio)","type":"text","style":"paragraph"},{"id":"amd-u2-c6-5","text":"Combined Ratios: One figure from each statement (e.g., ROCE, Stock Turnover) 2. Functional Classification (Based on Purpose):","type":"text","style":"paragraph"},{"id":"amd-u2-c6-6","text":"Liquidity Ratios: Short-term solvency (Current Ratio, Quick Ratio)","type":"text","style":"paragraph"},{"id":"amd-u2-c6-7","text":"Profitability Ratios: Earning capacity (Gross Profit Ratio, ROCE)","type":"text","style":"paragraph"},{"id":"amd-u2-c6-8","text":"Solvency Ratios: Long-term stability (Debt-Equity, Proprietary Ratio) Activity/Turnover Ratios: Efficiency (Stock Turnover, Debtors Turnover) 3. User-Based Classification:","type":"text","style":"paragraph"},{"id":"amd-u2-c6-9","text":"Management: Operational control","type":"text","style":"paragraph"},{"id":"amd-u2-c6-10","text":"Investors: Return assessment","type":"text","style":"paragraph"},{"id":"amd-u2-c6-11","text":"Creditors: Repayment capacity","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('5f53f287-9213-4a8a-b799-04313d536931', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What is the Du Pont Chart and its purpose?', '', 'The Du Pont Chart is a graphical framework that decomposes Return on Assets (ROA) or Return on Equity (ROE) into component ratios to analyse the interrelationship between

profitability, asset utilisation, and financial leverage. Basic Structure (Simplified for BMS):

Return on Assets (ROA) = Net Profit Margin × Asset Turnover

Where:

Net Profit Margin = (Net Profit ÷ Sales) × 100

Asset Turnover = Sales ÷ Total Assets

Purpose:

Identifies whether profitability stems from margin improvement or asset efficiency Helps management pinpoint areas for performance improvement

Shows how changes in any resource/monetary activity affect overall profitability Management Benefits:

Diagnoses root causes of ROA changes

Guides strategic decisions (pricing vs. asset utilisation)

Facilitates comparative analysis across divisions', NULL, NULL, NULL, 7, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '1e9b673c-5335-4a3f-bdaf-ef0e7d1af22a', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c7-q","text":"What is the Du Pont Chart and its purpose?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c7-1","text":"The Du Pont Chart is a graphical framework that decomposes Return on Assets (ROA) or Return on Equity (ROE) into component ratios to analyse the interrelationship between","type":"text","style":"paragraph"},{"id":"amd-u2-c7-2","text":"profitability, asset utilisation, and financial leverage. Basic Structure (Simplified for BMS):","type":"text","style":"paragraph"},{"id":"amd-u2-c7-3","type":"formula","expression":"Return on Assets (ROA) = Net Profit Margin × Asset Turnover"},{"id":"amd-u2-c7-4","text":"Where:","type":"text","style":"paragraph"},{"id":"amd-u2-c7-5","type":"formula","expression":"Net Profit Margin = (Net Profit ÷ Sales) × 100"},{"id":"amd-u2-c7-6","type":"formula","expression":"Asset Turnover = Sales ÷ Total Assets"},{"id":"amd-u2-c7-7","text":"Purpose:","type":"text","style":"paragraph"},{"id":"amd-u2-c7-8","text":"Identifies whether profitability stems from margin improvement or asset efficiency Helps management pinpoint areas for performance improvement","type":"text","style":"paragraph"},{"id":"amd-u2-c7-9","text":"Shows how changes in any resource/monetary activity affect overall profitability Management Benefits:","type":"text","style":"paragraph"},{"id":"amd-u2-c7-10","text":"Diagnoses root causes of ROA changes","type":"text","style":"paragraph"},{"id":"amd-u2-c7-11","text":"Guides strategic decisions (pricing vs. asset utilisation)","type":"text","style":"paragraph"},{"id":"amd-u2-c7-12","text":"Facilitates comparative analysis across divisions","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('03a1a947-2c46-4e91-8f54-14a98197c142', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What are the advantages of Ratio Analysis?', '', 'Key advantages:

Simplifies Complex Data — Condenses large financial statements into understandable metrics

Facilitates Comparison — Enables inter-firm and intra-firm comparisons Identifies Trends — Highlights patterns over time periods

Assesses Financial Health — Evaluates liquidity, solvency, profitability simultaneously Aids Decision-Making — Supports investment, credit, and operational decisions Highlights Strengths & Weaknesses — Pinpoints areas needing attention Budgeting & Planning — Provides basis for future projections

Performance Evaluation — Measures managerial efficiency', NULL, NULL, NULL, 8, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '1e9b673c-5335-4a3f-bdaf-ef0e7d1af22a', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c8-q","text":"What are the advantages of Ratio Analysis?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c8-1","text":"Key advantages:","type":"text","style":"paragraph"},{"id":"amd-u2-c8-2","text":"Simplifies Complex Data — Condenses large financial statements into understandable metrics","type":"text","style":"paragraph"},{"id":"amd-u2-c8-3","text":"Facilitates Comparison — Enables inter-firm and intra-firm comparisons Identifies Trends — Highlights patterns over time periods","type":"text","style":"paragraph"},{"id":"amd-u2-c8-4","text":"Assesses Financial Health — Evaluates liquidity, solvency, profitability simultaneously Aids Decision-Making — Supports investment, credit, and operational decisions Highlights Strengths & Weaknesses — Pinpoints areas needing attention Budgeting & Planning — Provides basis for future projections","type":"text","style":"paragraph"},{"id":"amd-u2-c8-5","text":"Performance Evaluation — Measures managerial efficiency","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('fd2dd4f4-2e03-40d0-85bf-b82d5b210cf2', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What are the limitations of Ratio Analysis?', '', 'Important limitations:

Historical Data — Based on past figures, may not predict future accurately Ignores Qualitative Factors — Does not consider management quality, market conditions

Accounting Policy Differences — Comparisons affected by different depreciation, inventory methods

Price Level Changes — Inflation distorts comparisons across periods

Window Dressing — Financial statements may be manipulated

No Standard Benchmarks — Ideal ratios vary by industry

Isolated Analysis Misleading — Single ratio without context can be deceptive Personal Bias — Interpretation depends on analyst''s judgement

Exam Caution: Always mention that ratios should be used in combination, not isolation.

SECTION C: BALANCE SHEET RATIOS

Tier 1: Extremely High Priority (Strong PYQ Evidence)

CURRENT RATIO', NULL, NULL, NULL, 9, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '1e9b673c-5335-4a3f-bdaf-ef0e7d1af22a', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c9-q","text":"What are the limitations of Ratio Analysis?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c9-1","text":"Important limitations:","type":"text","style":"paragraph"},{"id":"amd-u2-c9-2","text":"Historical Data — Based on past figures, may not predict future accurately Ignores Qualitative Factors — Does not consider management quality, market conditions","type":"text","style":"paragraph"},{"id":"amd-u2-c9-3","text":"Accounting Policy Differences — Comparisons affected by different depreciation, inventory methods","type":"text","style":"paragraph"},{"id":"amd-u2-c9-4","text":"Price Level Changes — Inflation distorts comparisons across periods","type":"text","style":"paragraph"},{"id":"amd-u2-c9-5","text":"Window Dressing — Financial statements may be manipulated","type":"text","style":"paragraph"},{"id":"amd-u2-c9-6","text":"No Standard Benchmarks — Ideal ratios vary by industry","type":"text","style":"paragraph"},{"id":"amd-u2-c9-7","text":"Isolated Analysis Misleading — Single ratio without context can be deceptive Personal Bias — Interpretation depends on analyst''s judgement","type":"text","style":"paragraph"},{"id":"amd-u2-c9-8","text":"Exam Caution: Always mention that ratios should be used in combination, not isolation.","type":"text","style":"paragraph"},{"id":"amd-u2-c9-9","text":"SECTION C: BALANCE SHEET RATIOS","type":"text","style":"paragraph"},{"id":"amd-u2-c9-10","text":"Tier 1: Extremely High Priority (Strong PYQ Evidence)","type":"text","style":"paragraph"},{"id":"amd-u2-c9-11","type":"numberList","items":["CURRENT RATIO"]}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('9b64bc8b-ad40-4f57-b394-923f748dd830', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What do Current Assets and Current Liabilities include?', '', 'Current Assets (convertible to cash within 12 months):

Cash in Hand & Bank

Debtors (less provision for doubtful debts)

Bills Receivable

Stock (Inventory)

Prepaid Expenses

Accrued Income

Short-term Investments

Advances (if recoverable within year)

Current Liabilities (payable within 12 months):

Creditors (Trade Payables)

Bills Payable

Bank Overdraft

Outstanding Expenses

Provision for Tax

Unclaimed Dividend

Short-term Borrowings

Current portion of Long-term Debt

Exam Tip: Exclude fictitious assets (Preliminary Expenses, P&L debit balance) from Current Assets.', NULL, NULL, NULL, 12, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '3daef71f-b3d9-493c-8013-148426ceb854', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c12-q","text":"What do Current Assets and Current Liabilities include?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c12-1","text":"Current Assets (convertible to cash within 12 months):","type":"text","style":"paragraph"},{"id":"amd-u2-c12-2","text":"Cash in Hand & Bank","type":"text","style":"paragraph"},{"id":"amd-u2-c12-3","text":"Debtors (less provision for doubtful debts)","type":"text","style":"paragraph"},{"id":"amd-u2-c12-4","text":"Bills Receivable","type":"text","style":"paragraph"},{"id":"amd-u2-c12-5","text":"Stock (Inventory)","type":"text","style":"paragraph"},{"id":"amd-u2-c12-6","text":"Prepaid Expenses","type":"text","style":"paragraph"},{"id":"amd-u2-c12-7","text":"Accrued Income","type":"text","style":"paragraph"},{"id":"amd-u2-c12-8","text":"Short-term Investments","type":"text","style":"paragraph"},{"id":"amd-u2-c12-9","text":"Advances (if recoverable within year)","type":"text","style":"paragraph"},{"id":"amd-u2-c12-10","text":"Current Liabilities (payable within 12 months):","type":"text","style":"paragraph"},{"id":"amd-u2-c12-11","text":"Creditors (Trade Payables)","type":"text","style":"paragraph"},{"id":"amd-u2-c12-12","text":"Bills Payable","type":"text","style":"paragraph"},{"id":"amd-u2-c12-13","text":"Bank Overdraft","type":"text","style":"paragraph"},{"id":"amd-u2-c12-14","text":"Outstanding Expenses","type":"text","style":"paragraph"},{"id":"amd-u2-c12-15","text":"Provision for Tax","type":"text","style":"paragraph"},{"id":"amd-u2-c12-16","text":"Unclaimed Dividend","type":"text","style":"paragraph"},{"id":"amd-u2-c12-17","text":"Short-term Borrowings","type":"text","style":"paragraph"},{"id":"amd-u2-c12-18","text":"Current portion of Long-term Debt","type":"text","style":"paragraph"},{"id":"amd-u2-c12-19","text":"Exam Tip: Exclude fictitious assets (Preliminary Expenses, P&L debit balance) from Current Assets.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('03de1a05-d4a5-4c52-9991-ad9e7173da2e', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'How is Current Ratio calculated from financial statements?', '', 'Step-by-Step:

Identify Current Assets from the asset side of Balance Sheet

Sum all Current Assets (exclude non-current and fictitious assets) 3. Identify Current Liabilities from the liabilities side

Sum all Current Liabilities (exclude long-term items)

Apply Formula: Current Assets ÷ Current Liabilities

Example Structure:

Current Assets:

Stock: ₹60,000

Debtors: ₹45,000

Cash: ₹30,000

Total Current Assets: ₹1,35,000

Current Liabilities:

Creditors: ₹24,000

Bank Overdraft: ₹70,000

Outstanding Expenses: ₹10,000

Total Current Liabilities: ₹1,04,000

Current Ratio = 1,35,000 ÷ 1,04,000 = 1.30 : 1', NULL, NULL, NULL, 13, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '3daef71f-b3d9-493c-8013-148426ceb854', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c13-q","text":"How is Current Ratio calculated from financial statements?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c13-1","text":"Step-by-Step:","type":"text","style":"paragraph"},{"id":"amd-u2-c13-2","type":"numberList","items":["Identify Current Assets from the asset side of Balance Sheet"]},{"id":"amd-u2-c13-3","type":"numberList","items":["Sum all Current Assets (exclude non-current and fictitious assets) 3. Identify Current Liabilities from the liabilities side"]},{"id":"amd-u2-c13-4","type":"numberList","items":["Sum all Current Liabilities (exclude long-term items)"]},{"id":"amd-u2-c13-5","type":"numberList","items":["Apply Formula: Current Assets ÷ Current Liabilities"]},{"id":"amd-u2-c13-6","text":"Example Structure:","type":"text","style":"paragraph"},{"id":"amd-u2-c13-7","text":"Current Assets:","type":"text","style":"paragraph"},{"id":"amd-u2-c13-8","text":"Stock: ₹60,000","type":"text","style":"paragraph"},{"id":"amd-u2-c13-9","text":"Debtors: ₹45,000","type":"text","style":"paragraph"},{"id":"amd-u2-c13-10","text":"Cash: ₹30,000","type":"text","style":"paragraph"},{"id":"amd-u2-c13-11","text":"Total Current Assets: ₹1,35,000","type":"text","style":"paragraph"},{"id":"amd-u2-c13-12","text":"Current Liabilities:","type":"text","style":"paragraph"},{"id":"amd-u2-c13-13","text":"Creditors: ₹24,000","type":"text","style":"paragraph"},{"id":"amd-u2-c13-14","text":"Bank Overdraft: ₹70,000","type":"text","style":"paragraph"},{"id":"amd-u2-c13-15","text":"Outstanding Expenses: ₹10,000","type":"text","style":"paragraph"},{"id":"amd-u2-c13-16","text":"Total Current Liabilities: ₹1,04,000","type":"text","style":"paragraph"},{"id":"amd-u2-c13-17","type":"formula","expression":"Current Ratio = 1,35,000 ÷ 1,04,000 = 1.30 : 1"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('6c60c706-2150-4503-9a48-616ae9ead0cc', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'How should the Current Ratio be interpreted?', '', 'High Ratio (\>2:1):

Positive: Strong liquidity, comfortable short-term solvency

Negative: Excess idle current assets, poor working capital management, overstocking Low Ratio (\<2:1):

Positive: Efficient asset utilisation

Negative: Liquidity risk, difficulty meeting short-term obligations

Standard Interpretation:

2:1 — Satisfactory (traditional benchmark)

Below 1:1 — Dangerous (current liabilities exceed current assets)

Industry Context: Retail may operate at lower ratios; manufacturing typically higher 2025 PYQ Pattern: Calculate and comment on Current Ratio — always provide interpretation.', NULL, NULL, NULL, 14, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '3daef71f-b3d9-493c-8013-148426ceb854', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c14-q","text":"How should the Current Ratio be interpreted?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c14-1","text":"High Ratio (\\>2:1):","type":"text","style":"paragraph"},{"id":"amd-u2-c14-2","text":"Positive: Strong liquidity, comfortable short-term solvency","type":"text","style":"paragraph"},{"id":"amd-u2-c14-3","text":"Negative: Excess idle current assets, poor working capital management, overstocking Low Ratio (\\<2:1):","type":"text","style":"paragraph"},{"id":"amd-u2-c14-4","text":"Positive: Efficient asset utilisation","type":"text","style":"paragraph"},{"id":"amd-u2-c14-5","text":"Negative: Liquidity risk, difficulty meeting short-term obligations","type":"text","style":"paragraph"},{"id":"amd-u2-c14-6","text":"Standard Interpretation:","type":"text","style":"paragraph"},{"id":"amd-u2-c14-7","text":"2:1 — Satisfactory (traditional benchmark)","type":"text","style":"paragraph"},{"id":"amd-u2-c14-8","text":"Below 1:1 — Dangerous (current liabilities exceed current assets)","type":"text","style":"paragraph"},{"id":"amd-u2-c14-9","text":"Industry Context: Retail may operate at lower ratios; manufacturing typically higher 2025 PYQ Pattern: Calculate and comment on Current Ratio — always provide interpretation.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('1aa8cd26-26db-4901-8727-8530de2c082a', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Calculate Current Ratio from the following Balance Sheet of XYZ Ltd as on 31st March 2025: Liabilities: Equity Share Capital: ₹5,00,000 10% Debentures: ₹2,00,000 Creditors: ₹80,000 Bills Payable: ₹40,000 Outstanding Expenses: ₹30,000 Bank Overdraft: ₹50,000 Assets: Land & Building: ₹4,00,000 Machinery: ₹3,00,000 Stock: ₹1,20,000 Debtors: ₹90,000 Cash: ₹60,000 Bills Receivable: ₹30,000 Prepaid Expenses: ₹20,000', '', 'Solution:

Step 1: Identify Current Assets

Stock: ₹1,20,000

Debtors: ₹90,000

Cash: ₹60,000

Bills Receivable: ₹30,000

Prepaid Expenses: ₹20,000

Total Current Assets = ₹3,20,000

Step 2: Identify Current Liabilities

Creditors: ₹80,000

Bills Payable: ₹40,000

Outstanding Expenses: ₹30,000

Bank Overdraft: ₹50,000

Total Current Liabilities = ₹2,00,000

Step 3: Apply Formula

Interpretation: The ratio of 1.6:1 is below the ideal 2:1, indicating moderate liquidity. The company can meet short-term obligations but has limited margin of safety.', NULL, NULL, NULL, 15, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '3daef71f-b3d9-493c-8013-148426ceb854', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c15-q","text":"Calculate Current Ratio from the following Balance Sheet of XYZ Ltd as on 31st March 2025: Liabilities: Equity Share Capital: ₹5,00,000 10% Debentures: ₹2,00,000 Creditors: ₹80,000 Bills Payable: ₹40,000 Outstanding Expenses: ₹30,000 Bank Overdraft: ₹50,000 Assets: Land & Building: ₹4,00,000 Machinery: ₹3,00,000 Stock: ₹1,20,000 Debtors: ₹90,000 Cash: ₹60,000 Bills Receivable: ₹30,000 Prepaid Expenses: ₹20,000","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c15-1","text":"Solution:","type":"text","style":"paragraph"},{"id":"amd-u2-c15-2","text":"Step 1: Identify Current Assets","type":"text","style":"paragraph"},{"id":"amd-u2-c15-3","text":"Stock: ₹1,20,000","type":"text","style":"paragraph"},{"id":"amd-u2-c15-4","text":"Debtors: ₹90,000","type":"text","style":"paragraph"},{"id":"amd-u2-c15-5","text":"Cash: ₹60,000","type":"text","style":"paragraph"},{"id":"amd-u2-c15-6","text":"Bills Receivable: ₹30,000","type":"text","style":"paragraph"},{"id":"amd-u2-c15-7","text":"Prepaid Expenses: ₹20,000","type":"text","style":"paragraph"},{"id":"amd-u2-c15-8","type":"formula","expression":"Total Current Assets = ₹3,20,000"},{"id":"amd-u2-c15-9","text":"Step 2: Identify Current Liabilities","type":"text","style":"paragraph"},{"id":"amd-u2-c15-10","text":"Creditors: ₹80,000","type":"text","style":"paragraph"},{"id":"amd-u2-c15-11","text":"Bills Payable: ₹40,000","type":"text","style":"paragraph"},{"id":"amd-u2-c15-12","text":"Outstanding Expenses: ₹30,000","type":"text","style":"paragraph"},{"id":"amd-u2-c15-13","text":"Bank Overdraft: ₹50,000","type":"text","style":"paragraph"},{"id":"amd-u2-c15-14","type":"formula","expression":"Total Current Liabilities = ₹2,00,000"},{"id":"amd-u2-c15-15","text":"Step 3: Apply Formula","type":"text","style":"paragraph"},{"id":"amd-u2-c15-16","text":"Interpretation: The ratio of 1.6:1 is below the ideal 2:1, indicating moderate liquidity. The company can meet short-term obligations but has limited margin of safety.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('ebf76a5f-b8c3-4820-88bf-aa8825d71ba9', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What errors do students commonly make in Current Ratio calculations?', '', 'Frequent Errors:

Including Non-Current Assets — Adding Fixed Assets, Investments by mistake

Including Fictitious Assets — Counting Preliminary Expenses, P&L (debit) as Current Assets

Missing Current Liabilities — Forgetting Bank Overdraft, Provision for Tax, Unclaimed Dividend

Wrong Classification — Treating Long-term Borrowings as Current Liabilities

Not Netting Provisions — Using gross Debtors instead of Debtors less Provision for Doubtful Debts

Arithmetic Errors — Incorrect summation of components

Exam Tip: Always create a working note listing each Current Asset and Current Liability separately before calculation.', NULL, NULL, NULL, 16, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '3daef71f-b3d9-493c-8013-148426ceb854', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c16-q","text":"What errors do students commonly make in Current Ratio calculations?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c16-1","text":"Frequent Errors:","type":"text","style":"paragraph"},{"id":"amd-u2-c16-2","type":"numberList","items":["Including Non-Current Assets — Adding Fixed Assets, Investments by mistake"]},{"id":"amd-u2-c16-3","type":"numberList","items":["Including Fictitious Assets — Counting Preliminary Expenses, P&L (debit) as Current Assets"]},{"id":"amd-u2-c16-4","type":"numberList","items":["Missing Current Liabilities — Forgetting Bank Overdraft, Provision for Tax, Unclaimed Dividend"]},{"id":"amd-u2-c16-5","type":"numberList","items":["Wrong Classification — Treating Long-term Borrowings as Current Liabilities"]},{"id":"amd-u2-c16-6","type":"numberList","items":["Not Netting Provisions — Using gross Debtors instead of Debtors less Provision for Doubtful Debts"]},{"id":"amd-u2-c16-7","type":"numberList","items":["Arithmetic Errors — Incorrect summation of components"]},{"id":"amd-u2-c16-8","text":"Exam Tip: Always create a working note listing each Current Asset and Current Liability separately before calculation.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('6c876af2-1cce-4d05-b1a3-0a20cf278c66', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'How could the examiner modify the Current Ratio problem?', '', 'Possible Variations:

Adjustment Required: "Debtors include ₹10,000 bad debts to be written off" — must deduct before calculation

Hidden Current Liability: "Proposed Dividend" — treat as Current Liability

Bank Overdraft: May be shown under Assets (negative cash) — must reclassify to Current Liabilities

Combined Ratio Question: Calculate Current Ratio along with Quick Ratio, Proprietary Ratio from same Balance Sheet
Comment Required: "Calculate and comment" — must provide interpretation, not just number

Missing Figure: "If Current Ratio is 2:1 and Current Liabilities are ₹1,50,000, find Current Assets"

LIQUID RATIO (QUICK RATIO / ACID TEST RATIO)', NULL, NULL, NULL, 17, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '3daef71f-b3d9-493c-8013-148426ceb854', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c17-q","text":"How could the examiner modify the Current Ratio problem?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c17-1","text":"Possible Variations:","type":"text","style":"paragraph"},{"id":"amd-u2-c17-2","type":"numberList","items":["Adjustment Required: \"Debtors include ₹10,000 bad debts to be written off\" — must deduct before calculation"]},{"id":"amd-u2-c17-3","type":"numberList","items":["Hidden Current Liability: \"Proposed Dividend\" — treat as Current Liability"]},{"id":"amd-u2-c17-4","type":"numberList","items":["Bank Overdraft: May be shown under Assets (negative cash) — must reclassify to Current Liabilities"]},{"id":"amd-u2-c17-5","type":"numberList","items":["Combined Ratio Question: Calculate Current Ratio along with Quick Ratio, Proprietary Ratio from same Balance Sheet","Comment Required: \"Calculate and comment\" — must provide interpretation, not just number"]},{"id":"amd-u2-c17-6","type":"numberList","items":["Missing Figure: \"If Current Ratio is 2:1 and Current Liabilities are ₹1,50,000, find Current Assets\""]},{"id":"amd-u2-c17-7","type":"numberList","items":["LIQUID RATIO (QUICK RATIO / ACID TEST RATIO)"]}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('0cca7095-305b-4d68-9d48-82a9bf6af64c', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What is the Liquid/Quick Ratio?', '', 'The Liquid Ratio (also called Quick Ratio or Acid Test Ratio) measures a company''s ability to meet short-term obligations using its most liquid assets (excluding stock and prepaid

expenses). It is a more stringent test of liquidity than Current Ratio.

Purpose: Assess immediate short-term solvency without relying on stock realisation.', NULL, NULL, NULL, 18, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '3a3ee761-b733-4d89-b33b-17fb78b5fc0d', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c18-q","text":"What is the Liquid/Quick Ratio?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c18-1","text":"The Liquid Ratio (also called Quick Ratio or Acid Test Ratio) measures a company''s ability to meet short-term obligations using its most liquid assets (excluding stock and prepaid","type":"text","style":"paragraph"},{"id":"amd-u2-c18-2","text":"expenses). It is a more stringent test of liquidity than Current Ratio.","type":"text","style":"paragraph"},{"id":"amd-u2-c18-3","text":"Purpose: Assess immediate short-term solvency without relying on stock realisation.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('8231607e-2fef-4e6b-a4d0-8dd26cb15368', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What is the formula for Liquid Ratio?', '', 'Liquid Ratio = Liquid Assets ÷ Current Liabilities

Alternative Formula:

Expressed as: X : 1

Ideal Standard: Traditionally 1:1 is considered satisfactory.', NULL, NULL, NULL, 19, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '3a3ee761-b733-4d89-b33b-17fb78b5fc0d', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c19-q","text":"What is the formula for Liquid Ratio?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c19-1","type":"formula","expression":"Liquid Ratio = Liquid Assets ÷ Current Liabilities"},{"id":"amd-u2-c19-2","text":"Alternative Formula:","type":"text","style":"paragraph"},{"id":"amd-u2-c19-3","text":"Expressed as: X : 1","type":"text","style":"paragraph"},{"id":"amd-u2-c19-4","text":"Ideal Standard: Traditionally 1:1 is considered satisfactory.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('4f1ddfef-16bf-41da-adb8-6e86bd4f8e55', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What are Liquid Assets and what is excluded?', '', 'Liquid Assets (Quick Assets):

Cash in Hand & Bank

Debtors (less provision)

Bills Receivable

Short-term Marketable Investments

Accrued Income

Exclusions from Current Assets:

Stock (Inventory) — May take time to sell and convert to cash

Prepaid Expenses — Not convertible to cash (already paid)

Accrued Income (sometimes excluded if collection uncertain)

Current Liabilities: Same as Current Ratio calculation

Key Distinction: Liquid Ratio excludes Stock and Prepaid Expenses; Current Ratio includes them.', NULL, NULL, NULL, 20, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '3a3ee761-b733-4d89-b33b-17fb78b5fc0d', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c20-q","text":"What are Liquid Assets and what is excluded?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c20-1","text":"Liquid Assets (Quick Assets):","type":"text","style":"paragraph"},{"id":"amd-u2-c20-2","text":"Cash in Hand & Bank","type":"text","style":"paragraph"},{"id":"amd-u2-c20-3","text":"Debtors (less provision)","type":"text","style":"paragraph"},{"id":"amd-u2-c20-4","text":"Bills Receivable","type":"text","style":"paragraph"},{"id":"amd-u2-c20-5","text":"Short-term Marketable Investments","type":"text","style":"paragraph"},{"id":"amd-u2-c20-6","text":"Accrued Income","type":"text","style":"paragraph"},{"id":"amd-u2-c20-7","text":"Exclusions from Current Assets:","type":"text","style":"paragraph"},{"id":"amd-u2-c20-8","text":"Stock (Inventory) — May take time to sell and convert to cash","type":"text","style":"paragraph"},{"id":"amd-u2-c20-9","text":"Prepaid Expenses — Not convertible to cash (already paid)","type":"text","style":"paragraph"},{"id":"amd-u2-c20-10","text":"Accrued Income (sometimes excluded if collection uncertain)","type":"text","style":"paragraph"},{"id":"amd-u2-c20-11","text":"Current Liabilities: Same as Current Ratio calculation","type":"text","style":"paragraph"},{"id":"amd-u2-c20-12","text":"Key Distinction: Liquid Ratio excludes Stock and Prepaid Expenses; Current Ratio includes them.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('aa54780d-f21c-468a-814e-f537d15b1db5', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'How is Liquid Ratio calculated?', '', 'Method 1 (Direct):

Identify Liquid Assets directly from Balance Sheet

Sum: Cash + Bank + Debtors + Bills Receivable + Short-term Investments 3. Divide by Current Liabilities

Method 2 (Deduction from Current Assets):

Calculate Total Current Assets

Deduct: Stock + Prepaid Expenses

Result = Liquid Assets

Divide by Current Liabilities

Example:

Current Assets: ₹3,20,000

Less: Stock: ₹1,20,000

Less: Prepaid Expenses: ₹20,000

Liquid Assets: ₹1,80,000

Current Liabilities: ₹2,00,000

Liquid Ratio = 1,80,000 ÷ 2,00,000 = 0.9 : 1', NULL, NULL, NULL, 21, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '3a3ee761-b733-4d89-b33b-17fb78b5fc0d', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c21-q","text":"How is Liquid Ratio calculated?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c21-1","text":"Method 1 (Direct):","type":"text","style":"paragraph"},{"id":"amd-u2-c21-2","type":"numberList","items":["Identify Liquid Assets directly from Balance Sheet"]},{"id":"amd-u2-c21-3","type":"numberList","items":["Sum: Cash + Bank + Debtors + Bills Receivable + Short-term Investments 3. Divide by Current Liabilities"]},{"id":"amd-u2-c21-4","text":"Method 2 (Deduction from Current Assets):","type":"text","style":"paragraph"},{"id":"amd-u2-c21-5","type":"numberList","items":["Calculate Total Current Assets"]},{"id":"amd-u2-c21-6","type":"numberList","items":["Deduct: Stock + Prepaid Expenses"]},{"id":"amd-u2-c21-7","type":"numberList","items":["Result = Liquid Assets"]},{"id":"amd-u2-c21-8","type":"numberList","items":["Divide by Current Liabilities"]},{"id":"amd-u2-c21-9","text":"Example:","type":"text","style":"paragraph"},{"id":"amd-u2-c21-10","text":"Current Assets: ₹3,20,000","type":"text","style":"paragraph"},{"id":"amd-u2-c21-11","text":"Less: Stock: ₹1,20,000","type":"text","style":"paragraph"},{"id":"amd-u2-c21-12","text":"Less: Prepaid Expenses: ₹20,000","type":"text","style":"paragraph"},{"id":"amd-u2-c21-13","text":"Liquid Assets: ₹1,80,000","type":"text","style":"paragraph"},{"id":"amd-u2-c21-14","text":"Current Liabilities: ₹2,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c21-15","type":"formula","expression":"Liquid Ratio = 1,80,000 ÷ 2,00,000 = 0.9 : 1"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('f6f28ad4-87d1-46bc-a535-de3b50f2d6aa', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'How should Liquid Ratio be interpreted?', '', 'High Ratio (\>1:1):

Positive: Strong immediate liquidity

Negative: Excess idle liquid assets, poor investment of surplus cash Low Ratio (\<1:1):

Positive: Efficient cash management

Negative: Risk in meeting immediate obligations without selling stock Standard Interpretation:

1:1 — Satisfactory (traditional benchmark)

Below 0.5:1 — Concerning (may struggle with immediate payments) Comparison with Current Ratio:

If Current Ratio is high but Liquid Ratio is low → Heavy investment in stock If both ratios are low → Serious liquidity problem

2022 & 2025 PYQ: Acid Test/Quick Ratio frequently tested with interpretation.', NULL, NULL, NULL, 22, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '3a3ee761-b733-4d89-b33b-17fb78b5fc0d', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c22-q","text":"How should Liquid Ratio be interpreted?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c22-1","text":"High Ratio (\\>1:1):","type":"text","style":"paragraph"},{"id":"amd-u2-c22-2","text":"Positive: Strong immediate liquidity","type":"text","style":"paragraph"},{"id":"amd-u2-c22-3","text":"Negative: Excess idle liquid assets, poor investment of surplus cash Low Ratio (\\<1:1):","type":"text","style":"paragraph"},{"id":"amd-u2-c22-4","text":"Positive: Efficient cash management","type":"text","style":"paragraph"},{"id":"amd-u2-c22-5","text":"Negative: Risk in meeting immediate obligations without selling stock Standard Interpretation:","type":"text","style":"paragraph"},{"id":"amd-u2-c22-6","text":"1:1 — Satisfactory (traditional benchmark)","type":"text","style":"paragraph"},{"id":"amd-u2-c22-7","text":"Below 0.5:1 — Concerning (may struggle with immediate payments) Comparison with Current Ratio:","type":"text","style":"paragraph"},{"id":"amd-u2-c22-8","text":"If Current Ratio is high but Liquid Ratio is low → Heavy investment in stock If both ratios are low → Serious liquidity problem","type":"text","style":"paragraph"},{"id":"amd-u2-c22-9","text":"2022 & 2025 PYQ: Acid Test/Quick Ratio frequently tested with interpretation.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('9fe54917-3c8a-428e-b03c-4a3a531560c3', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Calculate Liquid Ratio from the following data: Current Assets: Stock: ₹1,00,000 Debtors: ₹80,000 Cash: ₹40,000 Bills Receivable: ₹20,000 Prepaid Expenses: ₹10,000 Current Liabilities: Creditors: ₹70,000 Bank Overdraft: ₹30,000 Outstanding Expenses: ₹20,000', '', 'Solution:

Step 1: Calculate Liquid Assets

Method 1 (Direct):

Debtors: ₹80,000

Cash: ₹40,000

Bills Receivable: ₹20,000

Total Liquid Assets: ₹1,40,000

Method 2 (Deduction):

Total Current Assets: ₹2,50,000

Less: Stock: ₹1,00,000

Less: Prepaid Expenses: ₹10,000

Liquid Assets: ₹1,40,000

Step 2: Calculate Current Liabilities

Creditors: ₹70,000

Bank Overdraft: ₹30,000

Outstanding Expenses: ₹20,000

Total: ₹1,20,000

Step 3: Apply Formula

Interpretation: The ratio of 1.17:1 is above the ideal 1:1, indicating good immediate liquidity. The company can meet short-term obligations comfortably without relying on stock sales.', NULL, NULL, NULL, 23, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '3a3ee761-b733-4d89-b33b-17fb78b5fc0d', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c23-q","text":"Calculate Liquid Ratio from the following data: Current Assets: Stock: ₹1,00,000 Debtors: ₹80,000 Cash: ₹40,000 Bills Receivable: ₹20,000 Prepaid Expenses: ₹10,000 Current Liabilities: Creditors: ₹70,000 Bank Overdraft: ₹30,000 Outstanding Expenses: ₹20,000","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c23-1","text":"Solution:","type":"text","style":"paragraph"},{"id":"amd-u2-c23-2","text":"Step 1: Calculate Liquid Assets","type":"text","style":"paragraph"},{"id":"amd-u2-c23-3","text":"Method 1 (Direct):","type":"text","style":"paragraph"},{"id":"amd-u2-c23-4","text":"Debtors: ₹80,000","type":"text","style":"paragraph"},{"id":"amd-u2-c23-5","text":"Cash: ₹40,000","type":"text","style":"paragraph"},{"id":"amd-u2-c23-6","text":"Bills Receivable: ₹20,000","type":"text","style":"paragraph"},{"id":"amd-u2-c23-7","text":"Total Liquid Assets: ₹1,40,000","type":"text","style":"paragraph"},{"id":"amd-u2-c23-8","text":"Method 2 (Deduction):","type":"text","style":"paragraph"},{"id":"amd-u2-c23-9","text":"Total Current Assets: ₹2,50,000","type":"text","style":"paragraph"},{"id":"amd-u2-c23-10","text":"Less: Stock: ₹1,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c23-11","text":"Less: Prepaid Expenses: ₹10,000","type":"text","style":"paragraph"},{"id":"amd-u2-c23-12","text":"Liquid Assets: ₹1,40,000","type":"text","style":"paragraph"},{"id":"amd-u2-c23-13","text":"Step 2: Calculate Current Liabilities","type":"text","style":"paragraph"},{"id":"amd-u2-c23-14","text":"Creditors: ₹70,000","type":"text","style":"paragraph"},{"id":"amd-u2-c23-15","text":"Bank Overdraft: ₹30,000","type":"text","style":"paragraph"},{"id":"amd-u2-c23-16","text":"Outstanding Expenses: ₹20,000","type":"text","style":"paragraph"},{"id":"amd-u2-c23-17","text":"Total: ₹1,20,000","type":"text","style":"paragraph"},{"id":"amd-u2-c23-18","text":"Step 3: Apply Formula","type":"text","style":"paragraph"},{"id":"amd-u2-c23-19","text":"Interpretation: The ratio of 1.17:1 is above the ideal 1:1, indicating good immediate liquidity. The company can meet short-term obligations comfortably without relying on stock sales.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('c747460e-0a74-4316-a940-355e4dee39bc', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What errors occur in Liquid Ratio calculations?', '', 'Common Errors:

Including Stock — Forgetting to exclude inventory from Liquid Assets 2. Including Prepaid Expenses — Not deducting prepaid items

Wrong Current Liabilities — Same mistakes as Current Ratio

Confusing with Current Ratio — Using Current Assets instead of Liquid Assets

Double Counting — Adding Cash twice (in hand and at bank separately counted incorrectly)

Key Distinction to Remember:

Current Ratio = Includes Stock + Prepaid Expenses

Liquid Ratio = Excludes Stock + Prepaid Expenses', NULL, NULL, NULL, 24, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '3a3ee761-b733-4d89-b33b-17fb78b5fc0d', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c24-q","text":"What errors occur in Liquid Ratio calculations?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c24-1","text":"Common Errors:","type":"text","style":"paragraph"},{"id":"amd-u2-c24-2","type":"numberList","items":["Including Stock — Forgetting to exclude inventory from Liquid Assets 2. Including Prepaid Expenses — Not deducting prepaid items"]},{"id":"amd-u2-c24-3","type":"numberList","items":["Wrong Current Liabilities — Same mistakes as Current Ratio"]},{"id":"amd-u2-c24-4","type":"numberList","items":["Confusing with Current Ratio — Using Current Assets instead of Liquid Assets"]},{"id":"amd-u2-c24-5","type":"numberList","items":["Double Counting — Adding Cash twice (in hand and at bank separately counted incorrectly)"]},{"id":"amd-u2-c24-6","text":"Key Distinction to Remember:","type":"text","style":"paragraph"},{"id":"amd-u2-c24-7","type":"formula","expression":"Current Ratio = Includes Stock + Prepaid Expenses"},{"id":"amd-u2-c24-8","type":"formula","expression":"Liquid Ratio = Excludes Stock + Prepaid Expenses"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('afff529a-81d1-4a5a-baeb-7b13ed14c2ad', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What is the formula for Proprietary Ratio?', '', 'Proprietary Ratio = (Proprietors'' Fund ÷ Total Assets) × 100

Alternative Formula:

Expressed as: Percentage (%)

Note: Total Assets = Total Liabilities (in Balance Sheet), so either denominator is acceptable.', NULL, NULL, NULL, 34, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '98330bc2-c527-4a18-9fbe-af3504cb6b63', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c34-q","text":"What is the formula for Proprietary Ratio?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c34-1","type":"formula","expression":"Proprietary Ratio = (Proprietors'' Fund ÷ Total Assets) × 100"},{"id":"amd-u2-c34-2","text":"Alternative Formula:","type":"text","style":"paragraph"},{"id":"amd-u2-c34-3","text":"Expressed as: Percentage (%)","type":"text","style":"paragraph"},{"id":"amd-u2-c34-4","type":"formula","expression":"Note: Total Assets = Total Liabilities (in Balance Sheet), so either denominator is acceptable."}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('8eae9c6f-9906-4305-9948-22ff13f119d2', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'How might the examiner test Liquid Ratio differently?', '', 'Variations:

Missing Figure: "Liquid Ratio is 1:1, Current Liabilities ₹2,00,000, Stock ₹80,000. Find Current Assets"

Combined Question: Calculate both Current Ratio and Liquid Ratio, then explain the difference

Adjustment: "Stock includes ₹20,000 obsolete inventory" — affects Current Ratio but not Liquid Ratio

Interpretation Focus: "Comment on the difference between Current Ratio and Quick Ratio"

Bank Overdraft Treatment: Shown under Assets — must reclassify to Current Liabilities for both ratios

STOCK WORKING CAPITAL RATIO', NULL, NULL, NULL, 25, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '3a3ee761-b733-4d89-b33b-17fb78b5fc0d', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c25-q","text":"How might the examiner test Liquid Ratio differently?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c25-1","text":"Variations:","type":"text","style":"paragraph"},{"id":"amd-u2-c25-2","type":"numberList","items":["Missing Figure: \"Liquid Ratio is 1:1, Current Liabilities ₹2,00,000, Stock ₹80,000. Find Current Assets\""]},{"id":"amd-u2-c25-3","type":"numberList","items":["Combined Question: Calculate both Current Ratio and Liquid Ratio, then explain the difference"]},{"id":"amd-u2-c25-4","type":"numberList","items":["Adjustment: \"Stock includes ₹20,000 obsolete inventory\" — affects Current Ratio but not Liquid Ratio"]},{"id":"amd-u2-c25-5","type":"numberList","items":["Interpretation Focus: \"Comment on the difference between Current Ratio and Quick Ratio\""]},{"id":"amd-u2-c25-6","type":"numberList","items":["Bank Overdraft Treatment: Shown under Assets — must reclassify to Current Liabilities for both ratios"]},{"id":"amd-u2-c25-7","type":"numberList","items":["STOCK WORKING CAPITAL RATIO"]}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('52848e6c-9921-400a-a929-0afb2f9d1520', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What is the Stock Working Capital Ratio?', '', 'The Stock Working Capital Ratio (also called Stock to Working Capital Ratio) measures the proportion of working capital invested in stock (inventory). It indicates whether the company

is over-stocked or under-stocked relative to its working capital.

Purpose: Assess inventory management efficiency and working capital composition.', NULL, NULL, NULL, 26, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', 'ed5d445a-5f11-46b9-9987-56e5ed713091', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c26-q","text":"What is the Stock Working Capital Ratio?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c26-1","text":"The Stock Working Capital Ratio (also called Stock to Working Capital Ratio) measures the proportion of working capital invested in stock (inventory). It indicates whether the company","type":"text","style":"paragraph"},{"id":"amd-u2-c26-2","text":"is over-stocked or under-stocked relative to its working capital.","type":"text","style":"paragraph"},{"id":"amd-u2-c26-3","text":"Purpose: Assess inventory management efficiency and working capital composition.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('d31dac0e-427a-4eca-bdde-e83cb016d757', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What is the formula for Stock Working Capital Ratio?', '', 'Stock Working Capital Ratio = (Stock ÷ Working Capital) × 100

Where:

Expressed as: Percentage (%)

Note: Some texts express it as a proportion (Stock : Working Capital), but percentage form is

more common in Mumbai University. Flashcard SW-C: Components

Q: What do Stock and Working Capital represent? A:

Stock (Inventory):

Raw Materials

Work-in-Progress (WIP)

Finished Goods

Stock-in-Trade

Exclude: Stock of supplies/consumables (if separately shown) Working Capital:

Net Working Capital = Current Assets − Current Liabilities Represents funds available for day-to-day operations

Also called "Net Current Assets"

Interpretation Basis:

Shows what % of working capital is locked in inventory

High % → Excessive stock, potential overstocking

Low % → Lean inventory, possible stockouts', NULL, NULL, NULL, 27, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', 'ed5d445a-5f11-46b9-9987-56e5ed713091', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c27-q","text":"What is the formula for Stock Working Capital Ratio?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c27-1","type":"formula","expression":"Stock Working Capital Ratio = (Stock ÷ Working Capital) × 100"},{"id":"amd-u2-c27-2","text":"Where:","type":"text","style":"paragraph"},{"id":"amd-u2-c27-3","text":"Expressed as: Percentage (%)","type":"text","style":"paragraph"},{"id":"amd-u2-c27-4","text":"Note: Some texts express it as a proportion (Stock : Working Capital), but percentage form is","type":"text","style":"paragraph"},{"id":"amd-u2-c27-5","text":"more common in Mumbai University. Flashcard SW-C: Components","type":"text","style":"paragraph"},{"id":"amd-u2-c27-6","text":"Q: What do Stock and Working Capital represent? A:","type":"text","style":"paragraph"},{"id":"amd-u2-c27-7","text":"Stock (Inventory):","type":"text","style":"paragraph"},{"id":"amd-u2-c27-8","text":"Raw Materials","type":"text","style":"paragraph"},{"id":"amd-u2-c27-9","text":"Work-in-Progress (WIP)","type":"text","style":"paragraph"},{"id":"amd-u2-c27-10","text":"Finished Goods","type":"text","style":"paragraph"},{"id":"amd-u2-c27-11","text":"Stock-in-Trade","type":"text","style":"paragraph"},{"id":"amd-u2-c27-12","text":"Exclude: Stock of supplies/consumables (if separately shown) Working Capital:","type":"text","style":"paragraph"},{"id":"amd-u2-c27-13","type":"formula","expression":"Net Working Capital = Current Assets − Current Liabilities Represents funds available for day-to-day operations"},{"id":"amd-u2-c27-14","text":"Also called \"Net Current Assets\"","type":"text","style":"paragraph"},{"id":"amd-u2-c27-15","text":"Interpretation Basis:","type":"text","style":"paragraph"},{"id":"amd-u2-c27-16","text":"Shows what % of working capital is locked in inventory","type":"text","style":"paragraph"},{"id":"amd-u2-c27-17","text":"High % → Excessive stock, potential overstocking","type":"text","style":"paragraph"},{"id":"amd-u2-c27-18","text":"Low % → Lean inventory, possible stockouts","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('57d5aac3-9abb-4906-b30a-c547c81bb429', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'How is Stock Working Capital Ratio calculated?', '', 'Steps:

Identify Stock from Current Assets

Calculate Total Current Assets

Calculate Total Current Liabilities

Compute Working Capital = Current Assets − Current Liabilities 5. Apply Formula = (Stock ÷ Working Capital) × 100

Example:

Stock: ₹1,00,000

Current Assets: ₹3,00,000

Current Liabilities: ₹1,50,000

Working Capital: ₹1,50,000

Stock Working Capital Ratio = (1,00,000 ÷ 1,50,000) × 100 = 66.67%', NULL, NULL, NULL, 28, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', 'ed5d445a-5f11-46b9-9987-56e5ed713091', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c28-q","text":"How is Stock Working Capital Ratio calculated?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c28-1","text":"Steps:","type":"text","style":"paragraph"},{"id":"amd-u2-c28-2","type":"numberList","items":["Identify Stock from Current Assets"]},{"id":"amd-u2-c28-3","type":"numberList","items":["Calculate Total Current Assets"]},{"id":"amd-u2-c28-4","type":"numberList","items":["Calculate Total Current Liabilities"]},{"id":"amd-u2-c28-5","type":"numberList","items":["Compute Working Capital = Current Assets − Current Liabilities 5. Apply Formula = (Stock ÷ Working Capital) × 100"]},{"id":"amd-u2-c28-6","text":"Example:","type":"text","style":"paragraph"},{"id":"amd-u2-c28-7","text":"Stock: ₹1,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c28-8","text":"Current Assets: ₹3,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c28-9","text":"Current Liabilities: ₹1,50,000","type":"text","style":"paragraph"},{"id":"amd-u2-c28-10","text":"Working Capital: ₹1,50,000","type":"text","style":"paragraph"},{"id":"amd-u2-c28-11","type":"formula","expression":"Stock Working Capital Ratio = (1,00,000 ÷ 1,50,000) × 100 = 66.67%"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('edc39bbc-7d52-40fa-9808-843d620f651a', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'How should Stock Working Capital Ratio be interpreted?', '', 'High Ratio (\>60-70%):

Negative: Excessive investment in stock, overstocking

Risk: Obsolescence, storage costs, blocked working capital Action: Reduce inventory levels, improve stock turnover

Low Ratio (\<40-50%):

Positive: Efficient inventory management

Risk: Possible stockouts, lost sales if too low

Action: Ensure adequate stock for smooth operations

Industry Context:

Manufacturing: Typically higher (raw materials + WIP + finished goods) Retail/Trading: Moderate levels

Service: Very low or nil

2022 PYQ: Stock to Working Capital Ratio tested explicitly.', NULL, NULL, NULL, 29, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', 'ed5d445a-5f11-46b9-9987-56e5ed713091', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c29-q","text":"How should Stock Working Capital Ratio be interpreted?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c29-1","text":"High Ratio (\\>60-70%):","type":"text","style":"paragraph"},{"id":"amd-u2-c29-2","text":"Negative: Excessive investment in stock, overstocking","type":"text","style":"paragraph"},{"id":"amd-u2-c29-3","text":"Risk: Obsolescence, storage costs, blocked working capital Action: Reduce inventory levels, improve stock turnover","type":"text","style":"paragraph"},{"id":"amd-u2-c29-4","text":"Low Ratio (\\<40-50%):","type":"text","style":"paragraph"},{"id":"amd-u2-c29-5","text":"Positive: Efficient inventory management","type":"text","style":"paragraph"},{"id":"amd-u2-c29-6","text":"Risk: Possible stockouts, lost sales if too low","type":"text","style":"paragraph"},{"id":"amd-u2-c29-7","text":"Action: Ensure adequate stock for smooth operations","type":"text","style":"paragraph"},{"id":"amd-u2-c29-8","text":"Industry Context:","type":"text","style":"paragraph"},{"id":"amd-u2-c29-9","text":"Manufacturing: Typically higher (raw materials + WIP + finished goods) Retail/Trading: Moderate levels","type":"text","style":"paragraph"},{"id":"amd-u2-c29-10","text":"Service: Very low or nil","type":"text","style":"paragraph"},{"id":"amd-u2-c29-11","text":"2022 PYQ: Stock to Working Capital Ratio tested explicitly.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('aaf0593e-4416-4599-8027-8cd62dd4aa6f', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Calculate Stock Working Capital Ratio: Current Assets: Stock: ₹1,50,000 Debtors: ₹1,00,000 Cash: ₹50,000 Current Liabilities: Creditors: ₹80,000 Outstanding Expenses: ₹20,000', '', 'Solution:

Step 1: Calculate Working Capital

Current Assets:

Stock: ₹1,50,000

Debtors: ₹1,00,000

Cash: ₹50,000

Total: ₹3,00,000

Current Liabilities:

Creditors: ₹80,000

Outstanding Expenses: ₹20,000

Total: ₹1,00,000

Working Capital = ₹3,00,000 - ₹1,00,000 = ₹2,00,000

Step 2: Apply Formula

Interpretation: 75% of working capital is invested in stock, indicating heavy inventory investment. This may suggest overstocking or slow-moving inventory. Management should review stock levels to free up working capital.', NULL, NULL, NULL, 30, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', 'ed5d445a-5f11-46b9-9987-56e5ed713091', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c30-q","text":"Calculate Stock Working Capital Ratio: Current Assets: Stock: ₹1,50,000 Debtors: ₹1,00,000 Cash: ₹50,000 Current Liabilities: Creditors: ₹80,000 Outstanding Expenses: ₹20,000","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c30-1","text":"Solution:","type":"text","style":"paragraph"},{"id":"amd-u2-c30-2","text":"Step 1: Calculate Working Capital","type":"text","style":"paragraph"},{"id":"amd-u2-c30-3","text":"Current Assets:","type":"text","style":"paragraph"},{"id":"amd-u2-c30-4","text":"Stock: ₹1,50,000","type":"text","style":"paragraph"},{"id":"amd-u2-c30-5","text":"Debtors: ₹1,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c30-6","text":"Cash: ₹50,000","type":"text","style":"paragraph"},{"id":"amd-u2-c30-7","text":"Total: ₹3,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c30-8","text":"Current Liabilities:","type":"text","style":"paragraph"},{"id":"amd-u2-c30-9","text":"Creditors: ₹80,000","type":"text","style":"paragraph"},{"id":"amd-u2-c30-10","text":"Outstanding Expenses: ₹20,000","type":"text","style":"paragraph"},{"id":"amd-u2-c30-11","text":"Total: ₹1,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c30-12","type":"formula","expression":"Working Capital = ₹3,00,000 - ₹1,00,000 = ₹2,00,000"},{"id":"amd-u2-c30-13","text":"Step 2: Apply Formula","type":"text","style":"paragraph"},{"id":"amd-u2-c30-14","text":"Interpretation: 75% of working capital is invested in stock, indicating heavy inventory investment. This may suggest overstocking or slow-moving inventory. Management should review stock levels to free up working capital.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('99f81f4e-f518-438c-86e3-569b5a54a650', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What errors occur in Stock Working Capital Ratio?', '', 'Common Errors:

Using Gross Working Capital — Using Current Assets instead of Net Working Capital 2. Wrong Stock Figure — Including non-inventory items in Stock

Forgetting to Multiply by 100 — Reporting as decimal instead of percentage

Negative Working Capital — If Current Liabilities \> Current Assets, ratio becomes negative (indicates serious problem)

Confusing with Stock Turnover — Different ratio measuring stock movement speed Critical Point: Working Capital must be positive for meaningful interpretation.', NULL, NULL, NULL, 31, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', 'ed5d445a-5f11-46b9-9987-56e5ed713091', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c31-q","text":"What errors occur in Stock Working Capital Ratio?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c31-1","text":"Common Errors:","type":"text","style":"paragraph"},{"id":"amd-u2-c31-2","type":"numberList","items":["Using Gross Working Capital — Using Current Assets instead of Net Working Capital 2. Wrong Stock Figure — Including non-inventory items in Stock"]},{"id":"amd-u2-c31-3","type":"numberList","items":["Forgetting to Multiply by 100 — Reporting as decimal instead of percentage"]},{"id":"amd-u2-c31-4","type":"numberList","items":["Negative Working Capital — If Current Liabilities \\> Current Assets, ratio becomes negative (indicates serious problem)"]},{"id":"amd-u2-c31-5","type":"numberList","items":["Confusing with Stock Turnover — Different ratio measuring stock movement speed Critical Point: Working Capital must be positive for meaningful interpretation."]}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('e5fbffec-a3ff-4593-8258-dbb5b289dc0f', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'How could this ratio be tested differently?', '', 'Variations:

Reverse Calculation: "Stock Working Capital Ratio is 60%, Working Capital ₹2,00,000. Find Stock"

Combined with Other Ratios: Calculate along with Current Ratio, Stock Turnover 3. Comment Required: "Calculate and comment on inventory management"
Multiple Years: Calculate for 2-3 years and identify trend (increasing/decreasing stock investment)

Adjustment: "Stock includes ₹30,000 obsolete items" — discuss impact on ratio interpretation

PROPRIETARY RATIO', NULL, NULL, NULL, 32, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', 'ed5d445a-5f11-46b9-9987-56e5ed713091', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c32-q","text":"How could this ratio be tested differently?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c32-1","text":"Variations:","type":"text","style":"paragraph"},{"id":"amd-u2-c32-2","type":"numberList","items":["Reverse Calculation: \"Stock Working Capital Ratio is 60%, Working Capital ₹2,00,000. Find Stock\""]},{"id":"amd-u2-c32-3","type":"numberList","items":["Combined with Other Ratios: Calculate along with Current Ratio, Stock Turnover 3. Comment Required: \"Calculate and comment on inventory management\"","Multiple Years: Calculate for 2-3 years and identify trend (increasing/decreasing stock investment)"]},{"id":"amd-u2-c32-4","type":"numberList","items":["Adjustment: \"Stock includes ₹30,000 obsolete items\" — discuss impact on ratio interpretation"]},{"id":"amd-u2-c32-5","type":"numberList","items":["PROPRIETARY RATIO"]}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('1057969c-87b3-41e1-9eee-a63322a77451', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What is the Proprietary Ratio?', '', 'The Proprietary Ratio (also called Proprietors'' Fund Ratio) measures the proportion of total assets financed by owners'' funds (shareholders'' funds). It indicates the long-term solvency and

financial independence of the company.

Purpose: Assess the extent of owner''s contribution vs. external borrowing in asset financing.', NULL, NULL, NULL, 33, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '98330bc2-c527-4a18-9fbe-af3504cb6b63', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c33-q","text":"What is the Proprietary Ratio?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c33-1","text":"The Proprietary Ratio (also called Proprietors'' Fund Ratio) measures the proportion of total assets financed by owners'' funds (shareholders'' funds). It indicates the long-term solvency and","type":"text","style":"paragraph"},{"id":"amd-u2-c33-2","text":"financial independence of the company.","type":"text","style":"paragraph"},{"id":"amd-u2-c33-3","text":"Purpose: Assess the extent of owner''s contribution vs. external borrowing in asset financing.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('cb051e0a-6e4c-4378-a461-3581cf9df5f3', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What comprises Proprietors'' Fund and Total Assets?', '', 'Proprietors'' Fund (Shareholders'' Fund):

Equity Share Capital (paid-up)

Preference Share Capital

Reserves & Surplus (General Reserve, Capital Reserve, Securities Premium) Retained Earnings (P&L Credit Balance)

Less: Fictitious Assets (Preliminary Expenses, P&L Debit Balance, Discount on Issue of Shares)

Less: Accumulated Losses (if any)

Total Assets:

Fixed Assets (after depreciation)

Investments

Current Assets

Exclude: Fictitious Assets (already deducted from Proprietors'' Fund)

Net Assets Approach:

Net Assets = Total Assets − Fictitious Assets

Ensures consistency between numerator and denominator', NULL, NULL, NULL, 35, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '98330bc2-c527-4a18-9fbe-af3504cb6b63', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c35-q","text":"What comprises Proprietors'' Fund and Total Assets?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c35-1","text":"Proprietors'' Fund (Shareholders'' Fund):","type":"text","style":"paragraph"},{"id":"amd-u2-c35-2","text":"Equity Share Capital (paid-up)","type":"text","style":"paragraph"},{"id":"amd-u2-c35-3","text":"Preference Share Capital","type":"text","style":"paragraph"},{"id":"amd-u2-c35-4","text":"Reserves & Surplus (General Reserve, Capital Reserve, Securities Premium) Retained Earnings (P&L Credit Balance)","type":"text","style":"paragraph"},{"id":"amd-u2-c35-5","text":"Less: Fictitious Assets (Preliminary Expenses, P&L Debit Balance, Discount on Issue of Shares)","type":"text","style":"paragraph"},{"id":"amd-u2-c35-6","text":"Less: Accumulated Losses (if any)","type":"text","style":"paragraph"},{"id":"amd-u2-c35-7","text":"Total Assets:","type":"text","style":"paragraph"},{"id":"amd-u2-c35-8","text":"Fixed Assets (after depreciation)","type":"text","style":"paragraph"},{"id":"amd-u2-c35-9","text":"Investments","type":"text","style":"paragraph"},{"id":"amd-u2-c35-10","text":"Current Assets","type":"text","style":"paragraph"},{"id":"amd-u2-c35-11","text":"Exclude: Fictitious Assets (already deducted from Proprietors'' Fund)","type":"text","style":"paragraph"},{"id":"amd-u2-c35-12","text":"Net Assets Approach:","type":"text","style":"paragraph"},{"id":"amd-u2-c35-13","type":"formula","expression":"Net Assets = Total Assets − Fictitious Assets"},{"id":"amd-u2-c35-14","text":"Ensures consistency between numerator and denominator","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('448b5e76-2445-46f3-95fa-9dea04f91e48', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'How is Proprietary Ratio calculated?', '', 'Steps:

Identify Share Capital (Equity + Preference)

Add Reserves & Surplus (all credit balance reserves)

Add Retained Earnings (P&L credit balance)

Deduct Fictitious Assets (Preliminary Expenses, P&L debit)

Result = Proprietors'' Fund

Identify Total Assets (excluding fictitious assets)

Apply Formula = (Proprietors'' Fund ÷ Total Assets) × 100

Example:

Equity Share Capital: ₹5,00,000

Preference Share Capital: ₹2,00,000

General Reserve: ₹1,50,000

P&L (Credit): ₹1,00,000

Preliminary Expenses: ₹50,000 (deduct)

Proprietors'' Fund = 5,00,000 + 2,00,000 + 1,50,000 + 1,00,000 - 50,000 = ₹9,00,000 Total Assets (excluding fictitious): ₹15,00,000

Proprietary Ratio = (9,00,000 ÷ 15,00,000) × 100 = 60%', NULL, NULL, NULL, 36, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '98330bc2-c527-4a18-9fbe-af3504cb6b63', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c36-q","text":"How is Proprietary Ratio calculated?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c36-1","text":"Steps:","type":"text","style":"paragraph"},{"id":"amd-u2-c36-2","type":"numberList","items":["Identify Share Capital (Equity + Preference)"]},{"id":"amd-u2-c36-3","type":"numberList","items":["Add Reserves & Surplus (all credit balance reserves)"]},{"id":"amd-u2-c36-4","type":"numberList","items":["Add Retained Earnings (P&L credit balance)"]},{"id":"amd-u2-c36-5","type":"numberList","items":["Deduct Fictitious Assets (Preliminary Expenses, P&L debit)"]},{"id":"amd-u2-c36-6","type":"numberList","items":["Result = Proprietors'' Fund"]},{"id":"amd-u2-c36-7","type":"numberList","items":["Identify Total Assets (excluding fictitious assets)"]},{"id":"amd-u2-c36-8","type":"numberList","items":["Apply Formula = (Proprietors'' Fund ÷ Total Assets) × 100"]},{"id":"amd-u2-c36-9","text":"Example:","type":"text","style":"paragraph"},{"id":"amd-u2-c36-10","text":"Equity Share Capital: ₹5,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c36-11","text":"Preference Share Capital: ₹2,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c36-12","text":"General Reserve: ₹1,50,000","type":"text","style":"paragraph"},{"id":"amd-u2-c36-13","text":"P&L (Credit): ₹1,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c36-14","text":"Preliminary Expenses: ₹50,000 (deduct)","type":"text","style":"paragraph"},{"id":"amd-u2-c36-15","type":"formula","expression":"Proprietors'' Fund = 5,00,000 + 2,00,000 + 1,50,000 + 1,00,000 - 50,000 = ₹9,00,000 Total Assets (excluding fictitious): ₹15,00,000"},{"id":"amd-u2-c36-16","type":"formula","expression":"Proprietary Ratio = (9,00,000 ÷ 15,00,000) × 100 = 60%"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('2f3cb960-204c-4547-ae62-6231db997ca7', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'How should Proprietary Ratio be interpreted?', '', 'High Ratio (\>60-70%):

Positive: High financial independence, low reliance on external debt Positive: Lower financial risk, better solvency

Negative: May indicate under-utilisation of debt financing (trading on equity) Low Ratio (\<40-50%):

Positive: Aggressive use of debt for growth (if profitable)

Negative: High financial risk, dependent on external creditors Negative: May face difficulty in raising additional loans

Standard Interpretation:

Higher ratio → Greater long-term stability

Lower ratio → Higher leverage, higher risk

2025 PYQ: Proprietary Ratio explicitly tested.', NULL, NULL, NULL, 37, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '98330bc2-c527-4a18-9fbe-af3504cb6b63', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c37-q","text":"How should Proprietary Ratio be interpreted?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c37-1","text":"High Ratio (\\>60-70%):","type":"text","style":"paragraph"},{"id":"amd-u2-c37-2","text":"Positive: High financial independence, low reliance on external debt Positive: Lower financial risk, better solvency","type":"text","style":"paragraph"},{"id":"amd-u2-c37-3","text":"Negative: May indicate under-utilisation of debt financing (trading on equity) Low Ratio (\\<40-50%):","type":"text","style":"paragraph"},{"id":"amd-u2-c37-4","text":"Positive: Aggressive use of debt for growth (if profitable)","type":"text","style":"paragraph"},{"id":"amd-u2-c37-5","text":"Negative: High financial risk, dependent on external creditors Negative: May face difficulty in raising additional loans","type":"text","style":"paragraph"},{"id":"amd-u2-c37-6","text":"Standard Interpretation:","type":"text","style":"paragraph"},{"id":"amd-u2-c37-7","text":"Higher ratio → Greater long-term stability","type":"text","style":"paragraph"},{"id":"amd-u2-c37-8","text":"Lower ratio → Higher leverage, higher risk","type":"text","style":"paragraph"},{"id":"amd-u2-c37-9","text":"2025 PYQ: Proprietary Ratio explicitly tested.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('b5015651-e84c-47e1-8216-e9c3e1892bfd', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Calculate Proprietary Ratio: Liabilities: Equity Share Capital: ₹4,00,000 Preference Share Capital: ₹2,00,000 General Reserve: ₹1,00,000 P&L Account (Credit): ₹50,000 10% Debentures: ₹3,00,000 Creditors: ₹1,50,000 Assets: Fixed Assets: ₹8,00,000 Investments: ₹1,00,000 Current Assets: ₹3,00,000 Preliminary Expenses: ₹50,000', '', 'Solution:

Step 1: Calculate Proprietors'' Fund

Equity Share Capital: ₹4,00,000

Preference Share Capital: ₹2,00,000

General Reserve: ₹1,00,000

P&L (Credit): ₹50,000

Total: ₹7,50,000

Less: Preliminary Expenses: ₹50,000

Proprietors'' Fund: ₹7,00,000

Step 2: Calculate Total Assets (excluding fictitious)

Fixed Assets: ₹8,00,000

Investments: ₹1,00,000

Current Assets: ₹3,00,000

Total Assets: ₹12,00,000

(Note: Preliminary Expenses excluded)

Step 3: Apply Formula

Interpretation: 58.33% of assets are financed by owners'' funds, indicating moderate financial independence. The company uses balanced mix of equity and debt financing.', NULL, NULL, NULL, 38, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '98330bc2-c527-4a18-9fbe-af3504cb6b63', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c38-q","text":"Calculate Proprietary Ratio: Liabilities: Equity Share Capital: ₹4,00,000 Preference Share Capital: ₹2,00,000 General Reserve: ₹1,00,000 P&L Account (Credit): ₹50,000 10% Debentures: ₹3,00,000 Creditors: ₹1,50,000 Assets: Fixed Assets: ₹8,00,000 Investments: ₹1,00,000 Current Assets: ₹3,00,000 Preliminary Expenses: ₹50,000","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c38-1","text":"Solution:","type":"text","style":"paragraph"},{"id":"amd-u2-c38-2","text":"Step 1: Calculate Proprietors'' Fund","type":"text","style":"paragraph"},{"id":"amd-u2-c38-3","text":"Equity Share Capital: ₹4,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c38-4","text":"Preference Share Capital: ₹2,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c38-5","text":"General Reserve: ₹1,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c38-6","text":"P&L (Credit): ₹50,000","type":"text","style":"paragraph"},{"id":"amd-u2-c38-7","text":"Total: ₹7,50,000","type":"text","style":"paragraph"},{"id":"amd-u2-c38-8","text":"Less: Preliminary Expenses: ₹50,000","type":"text","style":"paragraph"},{"id":"amd-u2-c38-9","text":"Proprietors'' Fund: ₹7,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c38-10","text":"Step 2: Calculate Total Assets (excluding fictitious)","type":"text","style":"paragraph"},{"id":"amd-u2-c38-11","text":"Fixed Assets: ₹8,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c38-12","text":"Investments: ₹1,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c38-13","text":"Current Assets: ₹3,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c38-14","text":"Total Assets: ₹12,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c38-15","text":"(Note: Preliminary Expenses excluded)","type":"text","style":"paragraph"},{"id":"amd-u2-c38-16","text":"Step 3: Apply Formula","type":"text","style":"paragraph"},{"id":"amd-u2-c38-17","text":"Interpretation: 58.33% of assets are financed by owners'' funds, indicating moderate financial independence. The company uses balanced mix of equity and debt financing.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('fc2d29b4-1655-413a-8494-497eeb62faed', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What errors occur in Proprietary Ratio?', '', 'Common Errors:

Not Deducting Fictitious Assets — Including Preliminary Expenses in both numerator and denominator

Missing Reserves — Forgetting General Reserve, Securities Premium 3. Including P&L Debit — Not deducting accumulated losses

Wrong Denominator — Using only Fixed Assets instead of Total Assets 5. Confusing with Debt-Equity Ratio — Different ratio measuring debt vs. equity Critical Check: Proprietors'' Fund must exclude fictitious assets for accurate ratio.', NULL, NULL, NULL, 39, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '98330bc2-c527-4a18-9fbe-af3504cb6b63', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c39-q","text":"What errors occur in Proprietary Ratio?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c39-1","text":"Common Errors:","type":"text","style":"paragraph"},{"id":"amd-u2-c39-2","type":"numberList","items":["Not Deducting Fictitious Assets — Including Preliminary Expenses in both numerator and denominator"]},{"id":"amd-u2-c39-3","type":"numberList","items":["Missing Reserves — Forgetting General Reserve, Securities Premium 3. Including P&L Debit — Not deducting accumulated losses"]},{"id":"amd-u2-c39-4","type":"numberList","items":["Wrong Denominator — Using only Fixed Assets instead of Total Assets 5. Confusing with Debt-Equity Ratio — Different ratio measuring debt vs. equity Critical Check: Proprietors'' Fund must exclude fictitious assets for accurate ratio."]}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('cfcf3d1d-1806-4ecc-b56d-319b9beb5588', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'How might Proprietary Ratio be tested?', '', 'Variations:

Missing Figure: "Proprietary Ratio is 50%, Total Assets ₹20,00,000. Find Shareholders'' Fund" 2. Combined Question: Calculate with Debt-Equity Ratio, Capital Gearing Ratio 3. Interpretation: "Comment on the company''s financial independence"

Fictitious Assets: P&L (Debit) given — must deduct from Proprietors'' Fund 5. Trend Analysis: Calculate for 2-3 years to show changing financial structure

DEBT EQUITY RATIO', NULL, NULL, NULL, 40, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '98330bc2-c527-4a18-9fbe-af3504cb6b63', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c40-q","text":"How might Proprietary Ratio be tested?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c40-1","text":"Variations:","type":"text","style":"paragraph"},{"id":"amd-u2-c40-2","type":"numberList","items":["Missing Figure: \"Proprietary Ratio is 50%, Total Assets ₹20,00,000. Find Shareholders'' Fund\" 2. Combined Question: Calculate with Debt-Equity Ratio, Capital Gearing Ratio 3. Interpretation: \"Comment on the company''s financial independence\""]},{"id":"amd-u2-c40-3","type":"numberList","items":["Fictitious Assets: P&L (Debit) given — must deduct from Proprietors'' Fund 5. Trend Analysis: Calculate for 2-3 years to show changing financial structure"]},{"id":"amd-u2-c40-4","type":"numberList","items":["DEBT EQUITY RATIO"]}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('478f7cbf-6c24-4e79-9343-8ab4990ef8f8', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What is the Debt-Equity Ratio?', '', 'The Debt-Equity Ratio measures the relationship between long-term debt (external borrowings) and shareholders'' equity (owners'' funds). It indicates the company''s financial

leverage and long-term solvency risk.

Purpose: Assess the proportion of debt financing relative to equity financing.', NULL, NULL, NULL, 41, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', 'c10634a5-f4d9-4f99-84b8-dad820699d59', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c41-q","text":"What is the Debt-Equity Ratio?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c41-1","text":"The Debt-Equity Ratio measures the relationship between long-term debt (external borrowings) and shareholders'' equity (owners'' funds). It indicates the company''s financial","type":"text","style":"paragraph"},{"id":"amd-u2-c41-2","text":"leverage and long-term solvency risk.","type":"text","style":"paragraph"},{"id":"amd-u2-c41-3","text":"Purpose: Assess the proportion of debt financing relative to equity financing.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('18d961a5-49af-4c96-9712-ba2f675a7910', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What is the formula for Debt-Equity Ratio?', '', 'Debt-Equity Ratio = Long-term Debt ÷ Shareholders'' Equity

Expressed as: X : 1 (e.g., 0.5:1 means ₹0.50 debt for every ₹1 equity)

Ideal Standard: Traditionally 2:1 (debt:equity) or 1:2 (equity:debt) depending on convention.

Mumbai University typically uses Debt : Equity format. Flashcard DE-C: Components

Q: What comprises Long-term Debt and Shareholders'' Equity? A:

Long-term Debt (External Equities):

Debentures (all types)

Long-term Bank Loans

Public Deposits (long-term)

Deferred Payment Liabilities

Long-term portion of borrowings

Exclude: Current Liabilities (Creditors, Bank Overdraft, Outstanding Expenses) Shareholders'' Equity (Owners'' Funds):

Equity Share Capital (paid-up)

Preference Share Capital

Reserves & Surplus (General Reserve, Capital Reserve, Securities Premium) Retained Earnings (P&L Credit Balance)

Less: Fictitious Assets (Preliminary Expenses, P&L Debit Balance) Less: Accumulated Losses

Critical Classification:

Long-term vs. Short-term: Only long-term debt in numerator

Fictitious Assets: Must deduct from equity', NULL, NULL, NULL, 42, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', 'c10634a5-f4d9-4f99-84b8-dad820699d59', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c42-q","text":"What is the formula for Debt-Equity Ratio?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c42-1","type":"formula","expression":"Debt-Equity Ratio = Long-term Debt ÷ Shareholders'' Equity"},{"id":"amd-u2-c42-2","text":"Expressed as: X : 1 (e.g., 0.5:1 means ₹0.50 debt for every ₹1 equity)","type":"text","style":"paragraph"},{"id":"amd-u2-c42-3","text":"Ideal Standard: Traditionally 2:1 (debt:equity) or 1:2 (equity:debt) depending on convention.","type":"text","style":"paragraph"},{"id":"amd-u2-c42-4","text":"Mumbai University typically uses Debt : Equity format. Flashcard DE-C: Components","type":"text","style":"paragraph"},{"id":"amd-u2-c42-5","text":"Q: What comprises Long-term Debt and Shareholders'' Equity? A:","type":"text","style":"paragraph"},{"id":"amd-u2-c42-6","text":"Long-term Debt (External Equities):","type":"text","style":"paragraph"},{"id":"amd-u2-c42-7","text":"Debentures (all types)","type":"text","style":"paragraph"},{"id":"amd-u2-c42-8","text":"Long-term Bank Loans","type":"text","style":"paragraph"},{"id":"amd-u2-c42-9","text":"Public Deposits (long-term)","type":"text","style":"paragraph"},{"id":"amd-u2-c42-10","text":"Deferred Payment Liabilities","type":"text","style":"paragraph"},{"id":"amd-u2-c42-11","text":"Long-term portion of borrowings","type":"text","style":"paragraph"},{"id":"amd-u2-c42-12","text":"Exclude: Current Liabilities (Creditors, Bank Overdraft, Outstanding Expenses) Shareholders'' Equity (Owners'' Funds):","type":"text","style":"paragraph"},{"id":"amd-u2-c42-13","text":"Equity Share Capital (paid-up)","type":"text","style":"paragraph"},{"id":"amd-u2-c42-14","text":"Preference Share Capital","type":"text","style":"paragraph"},{"id":"amd-u2-c42-15","text":"Reserves & Surplus (General Reserve, Capital Reserve, Securities Premium) Retained Earnings (P&L Credit Balance)","type":"text","style":"paragraph"},{"id":"amd-u2-c42-16","text":"Less: Fictitious Assets (Preliminary Expenses, P&L Debit Balance) Less: Accumulated Losses","type":"text","style":"paragraph"},{"id":"amd-u2-c42-17","text":"Critical Classification:","type":"text","style":"paragraph"},{"id":"amd-u2-c42-18","text":"Long-term vs. Short-term: Only long-term debt in numerator","type":"text","style":"paragraph"},{"id":"amd-u2-c42-19","text":"Fictitious Assets: Must deduct from equity","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('d12d1719-4e60-4922-9bbe-f950e5e7a21b', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'How is Debt-Equity Ratio calculated?', '', 'Steps:

Identify Long-term Debt (Debentures, Long-term Loans)

Sum all Long-term Borrowings

Calculate Shareholders'' Equity (Share Capital + Reserves − Fictitious Assets) 4. Apply Formula = Long-term Debt ÷ Shareholders'' Equity

Example:

Long-term Debt:

10% Debentures: ₹3,00,000

Long-term Bank Loan: ₹2,00,000

Total Debt: ₹5,00,000

Shareholders'' Equity:

Equity Share Capital: ₹6,00,000

Preference Share Capital: ₹2,00,000

General Reserve: ₹1,50,000

P&L (Credit): ₹1,00,000

Total Equity: ₹10,00,000

Debt-Equity Ratio = 5,00,000 ÷ 10,00,000 = 0.5 : 1', NULL, NULL, NULL, 43, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', 'c10634a5-f4d9-4f99-84b8-dad820699d59', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c43-q","text":"How is Debt-Equity Ratio calculated?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c43-1","text":"Steps:","type":"text","style":"paragraph"},{"id":"amd-u2-c43-2","type":"numberList","items":["Identify Long-term Debt (Debentures, Long-term Loans)"]},{"id":"amd-u2-c43-3","type":"numberList","items":["Sum all Long-term Borrowings"]},{"id":"amd-u2-c43-4","type":"numberList","items":["Calculate Shareholders'' Equity (Share Capital + Reserves − Fictitious Assets) 4. Apply Formula = Long-term Debt ÷ Shareholders'' Equity"]},{"id":"amd-u2-c43-5","text":"Example:","type":"text","style":"paragraph"},{"id":"amd-u2-c43-6","text":"Long-term Debt:","type":"text","style":"paragraph"},{"id":"amd-u2-c43-7","text":"10% Debentures: ₹3,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c43-8","text":"Long-term Bank Loan: ₹2,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c43-9","text":"Total Debt: ₹5,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c43-10","text":"Shareholders'' Equity:","type":"text","style":"paragraph"},{"id":"amd-u2-c43-11","text":"Equity Share Capital: ₹6,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c43-12","text":"Preference Share Capital: ₹2,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c43-13","text":"General Reserve: ₹1,50,000","type":"text","style":"paragraph"},{"id":"amd-u2-c43-14","text":"P&L (Credit): ₹1,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c43-15","text":"Total Equity: ₹10,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c43-16","type":"formula","expression":"Debt-Equity Ratio = 5,00,000 ÷ 10,00,000 = 0.5 : 1"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('a07e6375-a8fa-4bcd-bbbd-35d856177e32', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'How should Debt-Equity Ratio be interpreted?', '', 'High Ratio (\>1:1 or \>2:1 depending on standard):

Positive: Aggressive growth using debt (if profitable) Negative: High financial risk, heavy interest burden Negative: Difficulty in raising additional loans

Low Ratio (\<0.5:1):

Positive: Conservative financing, low financial risk Negative: Under-utilisation of debt (missing tax shield benefit) Negative: Lower return on equity (no trading on equity) Standard Interpretation:

2:1 (Debt:Equity) — Traditional acceptable limit

1:1 or lower — Conservative, low risk

Above 2:1 — High risk, may face borrowing restrictions 2025 PYQ: Debt-Equity Ratio explicitly tested.', NULL, NULL, NULL, 44, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', 'c10634a5-f4d9-4f99-84b8-dad820699d59', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c44-q","text":"How should Debt-Equity Ratio be interpreted?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c44-1","text":"High Ratio (\\>1:1 or \\>2:1 depending on standard):","type":"text","style":"paragraph"},{"id":"amd-u2-c44-2","text":"Positive: Aggressive growth using debt (if profitable) Negative: High financial risk, heavy interest burden Negative: Difficulty in raising additional loans","type":"text","style":"paragraph"},{"id":"amd-u2-c44-3","text":"Low Ratio (\\<0.5:1):","type":"text","style":"paragraph"},{"id":"amd-u2-c44-4","text":"Positive: Conservative financing, low financial risk Negative: Under-utilisation of debt (missing tax shield benefit) Negative: Lower return on equity (no trading on equity) Standard Interpretation:","type":"text","style":"paragraph"},{"id":"amd-u2-c44-5","text":"2:1 (Debt:Equity) — Traditional acceptable limit","type":"text","style":"paragraph"},{"id":"amd-u2-c44-6","text":"1:1 or lower — Conservative, low risk","type":"text","style":"paragraph"},{"id":"amd-u2-c44-7","text":"Above 2:1 — High risk, may face borrowing restrictions 2025 PYQ: Debt-Equity Ratio explicitly tested.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('1f7969e3-9997-4bd4-8a6e-de6753074dee', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'Calculate Debt-Equity Ratio: Liabilities: Equity Share Capital: ₹8,00,000 Preference Share Capital: ₹3,00,000 General Reserve: ₹2,00,000 P&L (Credit): ₹1,00,000 12% Debentures: ₹5,00,000 Long-term Bank Loan: ₹3,00,000 Creditors: ₹2,00,000 Outstanding Expenses: ₹50,000', '', 'Solution:

Step 1: Calculate Long-term Debt

12% Debentures: ₹5,00,000

Long-term Bank Loan: ₹3,00,000

Total Long-term Debt: ₹8,00,000

(Exclude Creditors, Outstanding Expenses - these are Current Liabilities) Step 2: Calculate Shareholders'' Equity

Equity Share Capital: ₹8,00,000

Preference Share Capital: ₹3,00,000

General Reserve: ₹2,00,000

P&L (Credit): ₹1,00,000

Total Equity: ₹14,00,000

Step 3: Apply Formula

Interpretation: The ratio of 0.57:1 indicates conservative financing. For every ₹1 of equity, the company has only ₹0.57 of long-term debt. This suggests low financial risk but possible under utilisation of debt financing.', NULL, NULL, NULL, 45, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', 'c10634a5-f4d9-4f99-84b8-dad820699d59', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c45-q","text":"Calculate Debt-Equity Ratio: Liabilities: Equity Share Capital: ₹8,00,000 Preference Share Capital: ₹3,00,000 General Reserve: ₹2,00,000 P&L (Credit): ₹1,00,000 12% Debentures: ₹5,00,000 Long-term Bank Loan: ₹3,00,000 Creditors: ₹2,00,000 Outstanding Expenses: ₹50,000","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c45-1","text":"Solution:","type":"text","style":"paragraph"},{"id":"amd-u2-c45-2","text":"Step 1: Calculate Long-term Debt","type":"text","style":"paragraph"},{"id":"amd-u2-c45-3","text":"12% Debentures: ₹5,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c45-4","text":"Long-term Bank Loan: ₹3,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c45-5","text":"Total Long-term Debt: ₹8,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c45-6","text":"(Exclude Creditors, Outstanding Expenses - these are Current Liabilities) Step 2: Calculate Shareholders'' Equity","type":"text","style":"paragraph"},{"id":"amd-u2-c45-7","text":"Equity Share Capital: ₹8,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c45-8","text":"Preference Share Capital: ₹3,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c45-9","text":"General Reserve: ₹2,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c45-10","text":"P&L (Credit): ₹1,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c45-11","text":"Total Equity: ₹14,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c45-12","text":"Step 3: Apply Formula","type":"text","style":"paragraph"},{"id":"amd-u2-c45-13","text":"Interpretation: The ratio of 0.57:1 indicates conservative financing. For every ₹1 of equity, the company has only ₹0.57 of long-term debt. This suggests low financial risk but possible under utilisation of debt financing.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('0084275a-04aa-40bb-a942-3274750e37d7', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What errors occur in Debt-Equity Ratio?', '', 'Common Errors:

Including Current Liabilities — Adding Creditors, Bank Overdraft to Long-term Debt 2. Missing Long-term Borrowings — Forgetting Public Deposits, Deferred Liabilities 3. Not Deducting Fictitious Assets — Including Preliminary Expenses in Equity

Wrong Ratio Format — Expressing as Equity:Debt instead of Debt:Equity (check question requirement)

Confusing with Capital Gearing — Different ratio (see separate flashcards) Critical Point: Only long-term debt in numerator; Current Liabilities excluded.', NULL, NULL, NULL, 46, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', 'c10634a5-f4d9-4f99-84b8-dad820699d59', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c46-q","text":"What errors occur in Debt-Equity Ratio?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c46-1","text":"Common Errors:","type":"text","style":"paragraph"},{"id":"amd-u2-c46-2","type":"numberList","items":["Including Current Liabilities — Adding Creditors, Bank Overdraft to Long-term Debt 2. Missing Long-term Borrowings — Forgetting Public Deposits, Deferred Liabilities 3. Not Deducting Fictitious Assets — Including Preliminary Expenses in Equity"]},{"id":"amd-u2-c46-3","type":"numberList","items":["Wrong Ratio Format — Expressing as Equity:Debt instead of Debt:Equity (check question requirement)"]},{"id":"amd-u2-c46-4","type":"numberList","items":["Confusing with Capital Gearing — Different ratio (see separate flashcards) Critical Point: Only long-term debt in numerator; Current Liabilities excluded."]}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('12dc2400-e24e-44be-9989-c145abc6b287', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'How might Debt-Equity Ratio be tested?', '', 'Variations:

Reverse Calculation: "Debt-Equity Ratio is 1:2, Equity ₹10,00,000. Find Long-term Debt" 2. Combined Question: Calculate with Proprietary Ratio, Capital Gearing Ratio 3. Interpretation: "Comment on the company''s leverage policy"

Multiple Years: Show trend (increasing/decreasing debt dependence)

Adjustment: "Debentures include ₹1,00,000 redeemable within 12 months" — reclassify to Current Liabilities

CAPITAL GEARING RATIO', NULL, NULL, NULL, 47, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', 'c10634a5-f4d9-4f99-84b8-dad820699d59', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c47-q","text":"How might Debt-Equity Ratio be tested?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c47-1","text":"Variations:","type":"text","style":"paragraph"},{"id":"amd-u2-c47-2","type":"numberList","items":["Reverse Calculation: \"Debt-Equity Ratio is 1:2, Equity ₹10,00,000. Find Long-term Debt\" 2. Combined Question: Calculate with Proprietary Ratio, Capital Gearing Ratio 3. Interpretation: \"Comment on the company''s leverage policy\""]},{"id":"amd-u2-c47-3","type":"numberList","items":["Multiple Years: Show trend (increasing/decreasing debt dependence)"]},{"id":"amd-u2-c47-4","type":"numberList","items":["Adjustment: \"Debentures include ₹1,00,000 redeemable within 12 months\" — reclassify to Current Liabilities"]},{"id":"amd-u2-c47-5","type":"numberList","items":["CAPITAL GEARING RATIO"]}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('288d17c3-ffd4-4f1f-8a13-2b0874c796ff', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Bond: meaning and basic terms.', 'Priority: Tier 2 | PYQ Connection: Foundation for Oct 2024 Q4B and Q4P | PYQ Connection: Foundation for Oct 2024 Q4B and Q4P', 'Bond: A debt instrument in which the issuer promises to pay periodic interest (coupon) and to repay the principal (face value) at maturity.
Terms:
Face/par value (F or M): amount repaid at maturity (₹100/₹1,000).
Coupon rate: annual interest rate on face value.
Annual coupon (C) = Coupon rate × Face value. Example: 12% on ₹100 → ₹12.
Maturity (n): years until repayment.
Market price (P): current traded price.
Required return / market yield (r): the discount rate investors demand.
Redemption value: amount repaid (usually par).
Price status: Par (price = face value), Discount (price < face value), Premium (price > face value).
Special types: Zero-coupon (no coupon, issued at a discount) and perpetual (no maturity).', NULL, NULL, NULL, 23, true, 'University Exam', NULL, NULL, NULL, '36af92ff-aa78-49a6-b953-c816f8fa02f9', 'ad766610-0fb2-46eb-8d3e-79013b3ff5c7', '{"blocks":[{"id":"equity-and-debt-markets-u4-c23-q","text":"Bond: meaning and basic terms.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"edm-u4-c23-1","type":"bulletList","items":["Bond: A debt instrument in which the issuer promises to pay periodic interest (coupon) and to repay the principal (face value) at maturity.","Terms:","Face/par value (F or M): amount repaid at maturity (₹100/₹1,000).","Coupon rate: annual interest rate on face value.","Annual coupon (C) = Coupon rate × Face value. Example: 12% on ₹100 → ₹12.","Maturity (n): years until repayment.","Market price (P): current traded price.","Required return / market yield (r): the discount rate investors demand.","Redemption value: amount repaid (usually par).","Price status: Par (price = face value), Discount (price < face value), Premium (price > face value).","Special types: Zero-coupon (no coupon, issued at a discount) and perpetual (no maturity)."]}],"version":1}'::jsonb, '2026-09-21 16:57:33.462562+00', '2026-09-21 16:57:33.462562+00'),
  ('201a35c6-8bf9-495c-9505-111f34bec2cc', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What is the Capital Gearing Ratio?', '', 'The Capital Gearing Ratio measures the relationship between fixed-interest-bearing securities (debt + preference capital) and equity shareholders'' funds. It indicates the degree of

financial leverage and the company''s reliance on fixed-cost capital.

Purpose: Assess capital structure and financial risk from fixed obligations.', NULL, NULL, NULL, 48, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '194c8938-6c54-46c2-863c-de7a9ad6387c', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c48-q","text":"What is the Capital Gearing Ratio?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c48-1","text":"The Capital Gearing Ratio measures the relationship between fixed-interest-bearing securities (debt + preference capital) and equity shareholders'' funds. It indicates the degree of","type":"text","style":"paragraph"},{"id":"amd-u2-c48-2","text":"financial leverage and the company''s reliance on fixed-cost capital.","type":"text","style":"paragraph"},{"id":"amd-u2-c48-3","text":"Purpose: Assess capital structure and financial risk from fixed obligations.","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('ecdd2d78-6d95-42a6-b5a2-f5d031595818', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What is the formula for Capital Gearing Ratio?', '', 'Capital Gearing Ratio = Fixed-Interest-Bearing Capital ÷ Equity Shareholders'' Funds

Where:

Fixed-Interest-Bearing Capital = Preference Share Capital + Debentures + Long-term Loans

Equity Shareholders'' Funds = Equity Share Capital + Reserves & Surplus + Retained Earnings − Fictitious Assets

Expressed as: X : 1 or Percentage

Classification:

High Gearing: Ratio \> 1 (more fixed-cost capital than equity)

Low Gearing: Ratio \< 1 (more equity than fixed-cost capital)', NULL, NULL, NULL, 49, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '194c8938-6c54-46c2-863c-de7a9ad6387c', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c49-q","text":"What is the formula for Capital Gearing Ratio?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c49-1","type":"formula","expression":"Capital Gearing Ratio = Fixed-Interest-Bearing Capital ÷ Equity Shareholders'' Funds"},{"id":"amd-u2-c49-2","text":"Where:","type":"text","style":"paragraph"},{"id":"amd-u2-c49-3","type":"formula","expression":"Fixed-Interest-Bearing Capital = Preference Share Capital + Debentures + Long-term Loans"},{"id":"amd-u2-c49-4","type":"formula","expression":"Equity Shareholders'' Funds = Equity Share Capital + Reserves & Surplus + Retained Earnings − Fictitious Assets"},{"id":"amd-u2-c49-5","text":"Expressed as: X : 1 or Percentage","type":"text","style":"paragraph"},{"id":"amd-u2-c49-6","text":"Classification:","type":"text","style":"paragraph"},{"id":"amd-u2-c49-7","text":"High Gearing: Ratio \\> 1 (more fixed-cost capital than equity)","type":"text","style":"paragraph"},{"id":"amd-u2-c49-8","text":"Low Gearing: Ratio \\< 1 (more equity than fixed-cost capital)","type":"text","style":"paragraph"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('30e943ba-8369-4877-9023-a292fa2bd0e7', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'What comprises Fixed-Interest-Bearing Capital and Equity Shareholders'' Funds?', '', 'Fixed-Interest-Bearing Capital:

Preference Share Capital (fixed dividend)

Debentures (fixed interest)

Long-term Bank Loans (fixed interest)

Public Deposits (fixed interest)

Exclude: Equity Share Capital (variable dividend), Current Liabilities Equity Shareholders'' Funds:

Equity Share Capital (paid-up)

Reserves & Surplus (General Reserve, Capital Reserve, Securities Premium) Retained Earnings (P&L Credit Balance)

Less: Fictitious Assets (Preliminary Expenses, P&L Debit)

Exclude: Preference Share Capital (already in numerator)

Key Distinction from Debt-Equity Ratio:

Debt-Equity: Long-term Debt ÷ Total Shareholders'' Equity (including Preference) Capital Gearing: (Preference + Debt) ÷ Equity Shareholders'' Funds only', NULL, NULL, NULL, 50, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '194c8938-6c54-46c2-863c-de7a9ad6387c', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c50-q","text":"What comprises Fixed-Interest-Bearing Capital and Equity Shareholders'' Funds?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c50-1","text":"Fixed-Interest-Bearing Capital:","type":"text","style":"paragraph"},{"id":"amd-u2-c50-2","text":"Preference Share Capital (fixed dividend)","type":"text","style":"paragraph"},{"id":"amd-u2-c50-3","text":"Debentures (fixed interest)","type":"text","style":"paragraph"},{"id":"amd-u2-c50-4","text":"Long-term Bank Loans (fixed interest)","type":"text","style":"paragraph"},{"id":"amd-u2-c50-5","text":"Public Deposits (fixed interest)","type":"text","style":"paragraph"},{"id":"amd-u2-c50-6","text":"Exclude: Equity Share Capital (variable dividend), Current Liabilities Equity Shareholders'' Funds:","type":"text","style":"paragraph"},{"id":"amd-u2-c50-7","text":"Equity Share Capital (paid-up)","type":"text","style":"paragraph"},{"id":"amd-u2-c50-8","text":"Reserves & Surplus (General Reserve, Capital Reserve, Securities Premium) Retained Earnings (P&L Credit Balance)","type":"text","style":"paragraph"},{"id":"amd-u2-c50-9","text":"Less: Fictitious Assets (Preliminary Expenses, P&L Debit)","type":"text","style":"paragraph"},{"id":"amd-u2-c50-10","text":"Exclude: Preference Share Capital (already in numerator)","type":"text","style":"paragraph"},{"id":"amd-u2-c50-11","text":"Key Distinction from Debt-Equity Ratio:","type":"text","style":"paragraph"},{"id":"amd-u2-c50-12","type":"formula","expression":"Debt-Equity: Long-term Debt ÷ Total Shareholders'' Equity (including Preference) Capital Gearing: (Preference + Debt) ÷ Equity Shareholders'' Funds only"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00'),
  ('d7a00832-7c46-46ff-92bf-d4c08defa6c9', 'bc3c8201-a885-45ea-a1e2-009a0714427d', 'flashcard', 'How is Capital Gearing Ratio calculated?', '', 'Steps:

Identify Fixed-Interest Capital (Preference Capital + Debentures + Long-term Loans) 2. Sum all Fixed-Cost Sources

Calculate Equity Shareholders'' Funds (Equity Capital + Reserves − Fictitious Assets) 4. Apply Formula = Fixed-Interest Capital ÷ Equity Shareholders'' Funds Example:

Fixed-Interest Capital:

10% Preference Capital: ₹2,00,000

12% Debentures: ₹3,00,000

Long-term Loan: ₹1,00,000

Total: ₹6,00,000

Equity Shareholders'' Funds:

Equity Share Capital: ₹5,00,000

General Reserve: ₹2,00,000

P&L (Credit): ₹1,00,000

Total: ₹8,00,000

Capital Gearing Ratio = 6,00,000 ÷ 8,00,000 = 0.75 : 1', NULL, NULL, NULL, 51, true, 'University Exam', NULL, NULL, NULL, '656387b2-9ca5-4391-9851-1afee0c37958', '194c8938-6c54-46c2-863c-de7a9ad6387c', '{"blocks":[{"id":"accounting-for-managerial-decisions-u2-c51-q","text":"How is Capital Gearing Ratio calculated?","type":"text","style":"paragraph"}],"version":1}'::jsonb, '{"blocks":[{"id":"amd-u2-c51-1","text":"Steps:","type":"text","style":"paragraph"},{"id":"amd-u2-c51-2","type":"numberList","items":["Identify Fixed-Interest Capital (Preference Capital + Debentures + Long-term Loans) 2. Sum all Fixed-Cost Sources"]},{"id":"amd-u2-c51-3","type":"numberList","items":["Calculate Equity Shareholders'' Funds (Equity Capital + Reserves − Fictitious Assets) 4. Apply Formula = Fixed-Interest Capital ÷ Equity Shareholders'' Funds Example:"]},{"id":"amd-u2-c51-4","text":"Fixed-Interest Capital:","type":"text","style":"paragraph"},{"id":"amd-u2-c51-5","text":"10% Preference Capital: ₹2,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c51-6","text":"12% Debentures: ₹3,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c51-7","text":"Long-term Loan: ₹1,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c51-8","text":"Total: ₹6,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c51-9","text":"Equity Shareholders'' Funds:","type":"text","style":"paragraph"},{"id":"amd-u2-c51-10","text":"Equity Share Capital: ₹5,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c51-11","text":"General Reserve: ₹2,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c51-12","text":"P&L (Credit): ₹1,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c51-13","text":"Total: ₹8,00,000","type":"text","style":"paragraph"},{"id":"amd-u2-c51-14","type":"formula","expression":"Capital Gearing Ratio = 6,00,000 ÷ 8,00,000 = 0.75 : 1"}],"version":1}'::jsonb, '2026-09-21 16:56:34.614107+00', '2026-09-21 16:56:34.614107+00')
